import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardCategory";

/**
 * Validate that retrieving a board category as an unauthorized user (non-admin/non-moderator)
 * is properly denied by the API.
 *
 * This test ensures that the endpoint for reading board category details enforces role-based access
 * controls. Only privileged users such as administrators or moderators should be able to receive the
 * category details. Requests from regular members or unauthenticated users must result in an access denied error.
 *
 * Steps:
 * 1. Try to access a board category detail with a random (or invalid) UUID as an unauthenticated/unauthorized user.
 * 2. Expect that the request fails with an authorization error (not found or unauthorized/forbidden error).
 */
export async function test_api_discussionboard_test_get_board_category_with_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Try to retrieve a board category with a random UUID as unauthorized user
  const randomId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("access denied for non-admin")(async () => {
    await api.functional.discussionboard.boardCategories.getById(connection, { id: randomId });
  });
}

