import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Validate that attempting to delete a discussion board section without admin permissions fails.
 *
 * This test ensures business rules forbid non-admin users from deleting board sections and the API correctly returns a permission error.
 *
 * Preconditions:
 * - There is a section to reference, created by an admin-capable connection, to ensure the section exists.
 * - The test executes the deletion attempt from a non-admin connection (no admin rights).
 *
 * Steps:
 * 1. Create a discussion board section via an admin (or default privileged) connection to ensure it exists for deletion attempt.
 * 2. Switch to a non-admin user context (simulate or use connection without admin privileges).
 * 3. Attempt to delete the previously created section using the non-admin context.
 * 4. Confirm that the API call fails with a permission/authorization error (any thrown error or HTTP error qualifies).
 *
 * Postconditions:
 * - Section is not deleted by the non-admin (no soft-delete occurs).
 * - Service correctly rejects the request per business rules and permission control.
 */
export async function test_api_discussionboard_test_soft_delete_section_without_admin_permission_fails(
  connection: api.IConnection,
) {
  // 1. Create section as admin (expect success)
  const section = await api.functional.discussionboard.sections.post(connection, {
    body: typia.random<IDiscussionboardSection.ICreate>(),
  });
  typia.assert(section);

  // 2. Simulate switch to non-admin (connection without admin rights)
  // (In this environment, we assume the provided connection is non-admin after this point.)

  // 3. Attempt to delete as non-admin (should fail)
  await TestValidator.error("non-admin forbidden from deleting section")(async () => {
    await api.functional.discussionboard.sections.eraseById(connection, { id: section.id });
  });
}

