import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { ISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/ISearchHistory";
import type { IDiscussionboardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchHistory";

/**
 * Validate the retrieval of a single search history entry by ID with different roles and error conditions.
 *
 * This test validates API access control and correct retrieval logic for the `/discussionboard/searchHistories/{id}` endpoint. Specifically, it tests that:
 *   1. The member who owns a search history entry can retrieve its details by ID.
 *   2. An admin can also retrieve another user's search history detail by ID.
 *   3. Retrieving a non-existent or unauthorized search history ID results in an error (404/permission error).
 *
 * Test Flow:
 *  1. Register a new member (member1).
 *  2. As member1, create a search history entry and get its ID.
 *  3. Retrieve the search history by ID as member1 (should succeed, expect details).
 *  4. Register a new admin (admin1).
 *  5. As admin1 (switch authentication if necessary), retrieve the same search history by ID (should succeed, since admin has access).
 *  6. Register another new member (member2).
 *  7. As member2, attempt to retrieve member1's search history by ID (should fail: 404 or permission error).
 *  8. Attempt to retrieve a completely random (non-existent) ID as admin (should fail: 404).
 */
export async function test_api_discussionboard_test_get_single_search_history_record_as_owner_and_as_admin(
  connection: api.IConnection,
) {
  // 1. Register member1
  const member1: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member1);

  // 2. As member1, create a search history entry
  const searchHistoryEntry: IDiscussionboardSearchHistory = await api.functional.discussionboard.searchHistories.post(
    connection,
    {
      body: typia.random<IDiscussionboardSearchHistory.ICreate>(),
    },
  );
  typia.assert(searchHistoryEntry);

  // 3. Retrieve search history by ID as member1 (should succeed)
  const selfRetrieved: ISearchHistory = await api.functional.discussionboard.searchHistories.getById(connection, {
    id: searchHistoryEntry.id,
  });
  typia.assert(selfRetrieved);
  TestValidator.equals("search history id matches")(selfRetrieved.id)(searchHistoryEntry.id);

  // 4. Register admin1
  const admin1: IDiscussionboardAdmin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin1);

  // Assume post-admin creation, connection has admin's auth (if not, would need explicit login, not provided in API)
  // 5. As admin1, retrieve the same search history by ID (should succeed)
  const adminRetrieved: ISearchHistory = await api.functional.discussionboard.searchHistories.getById(connection, {
    id: searchHistoryEntry.id,
  });
  typia.assert(adminRetrieved);
  TestValidator.equals("search history id matches as admin")(adminRetrieved.id)(searchHistoryEntry.id);

  // 6. Register member2
  const member2: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);

  // 7. As member2, attempt to retrieve member1's search history (fail)
  // Assume that after member2 is created, the connection is for member2's auth
  await TestValidator.error("member2 cannot access member1's search history entry")(
    async () => {
      await api.functional.discussionboard.searchHistories.getById(connection, {
        id: searchHistoryEntry.id,
      });
    },
  );

  // 8. As admin1, attempt to retrieve a random/non-existent search history id (fail)
  // Re-authenticate as admin1, since we just authenticated as member2
  await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });

  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("admin cannot access non-existent search history entry")(
    async () => {
      await api.functional.discussionboard.searchHistories.getById(connection, {
        id: randomId,
      });
    },
  );
}

