import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentLike";

/**
 * Test unliking (deleting) a comment like record by its owner as well as by a moderator/admin.
 *
 * This test simulates a real-world scenario of unliking a comment, including various user roles and proper error handling:
 *
 * 1. Create three members: a 'liker', an 'unrelated' member, and an 'admin'.
 *    - Note: As there is no explicit concept of admin/moderator membership in the available API, all are just members. 'admin' is simulated as a regular member with the intention.
 * 2. Create a comment (can be owned by the liker).
 * 3. Like the comment as the liker (create a like record for the comment and member).
 * 4. Delete (unlike) the like as its owner (should succeed):
 *    - Assert that the delete API returns the like and that future deletion attempts fail (404).
 * 5. Re-like the comment as the liker to test permission checks again.
 * 6. Attempt to delete the like as the unrelated member (should fail):
 *    - Assert that an error is thrown.
 * 7. Delete the like as the simulated admin (should succeed):
 *    - Assert success and that repeated delete attempts fail.
 * 8. Confirm that attempting to delete an already deleted or non-existent like yields a 404 error.
 * 9. Skipped: Analytics/audit log validation (not feasible since no API is provided for this purpose).
 */
export async function test_api_discussionboard_test_delete_comment_like_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. Create three members: liker, unrelated, admin
  const liker = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(liker);
  const unrelated = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(unrelated);
  const admin = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a comment by the liker
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. Like the comment as the liker
  const origLike = await api.functional.discussionboard.commentLikes.post(connection, {
    body: typia.random<IDiscussionboardCommentLike.ICreate>(),
  });
  typia.assert(origLike);

  // 4. Delete the like as owner (should succeed)
  const deletedLike = await api.functional.discussionboard.commentLikes.eraseById(connection, {
    id: origLike.id,
  });
  typia.assert(deletedLike);

  // Try to delete again - should fail (simulate 404)
  await TestValidator.error("already deleted like cannot be deleted again")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: origLike.id,
      });
    },
  );

  // 5. Re-like for permission tests
  const relike = await api.functional.discussionboard.commentLikes.post(connection, {
    body: typia.random<IDiscussionboardCommentLike.ICreate>(),
  });
  typia.assert(relike);

  // 6. Attempt to delete as unrelated user (should fail)
  await TestValidator.error("unrelated member cannot delete another's like")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: relike.id,
      });
    },
  );

  // 7. Delete like as simulated admin (should succeed)
  const deletedByAdmin = await api.functional.discussionboard.commentLikes.eraseById(connection, {
    id: relike.id,
  });
  typia.assert(deletedByAdmin);

  // 8. Attempt to delete non-existent like (should get error)
  await TestValidator.error("cannot delete non-existent comment like")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: relike.id,
      });
    },
  );
