import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * Validate updating an existing settings entry by an admin.
 *
 * This test ensures an admin can update a settings entry's owner_type, setting_value, description, and section_id fields using the PUT /discussionboard/settings/{id} endpoint.
 * Steps:
 * 1. Create a new settings entry to obtain a valid ID.
 * 2. Update the created settings record using new values for some of the updatable fields (e.g., owner_type, setting_value, description, section_id).
 * 3. Confirm the response has updated data for the requested fields, retains expected immutable fields (like setting_key), and contains a new updated timestamp differing from the original.
 * 4. Edge case: Attempt to update the record to a (setting_key, owner_type, owner_id) triple that already exists (should return an error).
 * 5. Edge case: Submit an update omitting updatable fields (should succeed and leave omitted fields unchanged).
 * 6. Edge case: Attempt to modify immutable key/ID (should not change them in response).
 */
export async function test_api_discussionboard_test_update_existing_setting_as_admin(connection: api.IConnection) {
  // 1. Create a new settings entry as admin
  const original = await api.functional.discussionboard.settings.post(connection, { body: typia.random<IDiscussionboardSettings.ICreate>() });
  typia.assert(original);

  // 2. Update: modify owner_type, setting_value, description, section_id
  const updateBody = typia.random<IDiscussionboardSettings.IUpdate>();
  const updated = await api.functional.discussionboard.settings.putById(connection, { id: original.id, body: updateBody });
  typia.assert(updated);
  // Should have new/changed values in updatable fields
  // Should retain immutable fields (like setting_key and id)
  TestValidator.notEquals("updated timestamp")(updated.updated_at)(original.updated_at);
  TestValidator.equals("immutable setting_key")(updated.setting_key)(original.setting_key);
  TestValidator.equals("immutable id")(updated.id)(original.id);

  // 3. Edge case: Try to update to existing (setting_key, owner_type, owner_id) triple
  const duplicate = await api.functional.discussionboard.settings.post(connection, { body: typia.random<IDiscussionboardSettings.ICreate>() });
  typia.assert(duplicate);
  await TestValidator.error("conflicting key/owner update")(() =>
    api.functional.discussionboard.settings.putById(connection, {
      id: original.id,
      body: { owner_type: duplicate.owner_type, owner_id: duplicate.owner_id } satisfies IDiscussionboardSettings.IUpdate,
    })
  );

  // 4. Edge case: Omitting updatable fields (should not change those fields)
  const partialUpdate = {} as IDiscussionboardSettings.IUpdate;
  const partialResult = await api.functional.discussionboard.settings.putById(connection, { id: original.id, body: partialUpdate });
  typia.assert(partialResult);
  TestValidator.equals("unchanged key")(partialResult.setting_key)(original.setting_key);
  TestValidator.equals("unchanged id")(partialResult.id)(original.id);

  // 5. Edge case: Attempt to change immutable fields (should not change in the stored object)
  const badUpdate = { setting_key: "attempted-change", id: "fake-id" } as any as IDiscussionboardSettings.IUpdate;
  const badResult = await api.functional.discussionboard.settings.putById(connection, { id: original.id, body: badUpdate });
  typia.assert(badResult);
  TestValidator.equals("immutable setting_key")(badResult.setting_key)(original.setting_key);
  TestValidator.equals("immutable id")(badResult.id)(original.id);
}

