 * A valid section is first created, associated with a channel. The section is then updated with a new unique name (to test name uniqueness enforcement), description, position, and visibility. After the update, the returned entity is checked to ensure all new values are present. For completeness, a follow-up update could also check edge behavior (e.g., toggling visibility), but this test focuses on normal editing workflow.
 *
 * Steps:
 * 1. Create a channel (dependency).
 * 2. Create a section associated with that channel (dependency).
 * 3. Prepare new values for the update (all modifiable fields, including a unique name).
 * 4. Update the section by its ID as admin.
 * 5. Assert the API call succeeds and returned data reflects the requested changes.
 */
export async function test_api_discussionboard_test_update_section_success_with_admin(
  connection: api.IConnection,
) {
  // 1. Create a channel (dependency)
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 2. Create a section in the channel (dependency)
  const originalSection = await api.functional.discussionboard.sections.post(connection, {
    body: {
      ...typia.random<IDiscussionboardSection.ICreate>(),
      channel_id: channel.id, // ensure the correct channel id on creation
    },
  });
  typia.assert(originalSection);

