  const newSectionName = `${originalSection.name}_updated_${Date.now()}`;
  const newDescription = `Updated desc ${RandomGenerator.paragraph()()}`;
  const newPosition = (typeof originalSection.position === "number" ? originalSection.position + 1 : 1);
  const newVisible = originalSection.visible === true ? false : true;

  // 4. Update the section by id as admin
  const updatedSection = await api.functional.discussionboard.sections.putById(connection, {
    id: originalSection.id,
    body: {
      name: newSectionName,
      description: newDescription,
      position: newPosition,
      visible: newVisible,
    },
  });
  typia.assert(updatedSection);

  // 5. Assert that the updated section matches the new values
  TestValidator.equals("updated name")(updatedSection.name)(newSectionName);
  TestValidator.equals("updated description")(updatedSection.description)(newDescription);
  TestValidator.equals("updated position")(updatedSection.position)(newPosition);
  TestValidator.equals("updated visibility")(updatedSection.visible)(newVisible);

  // (Optional) Assert the channel id did not change
  TestValidator.equals("channel id not changed")(updatedSection.channel_id)(originalSection.channel_id);
}

