  const admin = await api.functional.discussionboard.admins.post(connection, { body: typia.random<IDiscussionboardAdmin.ICreate>() });
  typia.assert(admin);

  // 2. Create a regular member (grantee)
  const member = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(member);

  // 3. Grant moderator status to member
  const moderatorAssign = await api.functional.discussionboard.moderators.post(connection, { body: typia.random<IDiscussionboardModerator.ICreate>() });
  typia.assert(moderatorAssign);

  // 4. Attempt to grant moderator status again (should fail)
