 *   * Results contain only matching comments
 *   * Pagination boundaries are respected
 *   * Permissions are enforced on soft-deleted/flagged comments
 *   * Invalid queries are rejected with error
 *   * Large pages never return >limit
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register members (including normal users & moderator)
  const members = await Promise.all([
