  const byParentList = await api.functional.discussionboard.comments.patch(connection, {
    body: { parent_id: rootComments[0].id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byParentList);
  byParentList.data.forEach(c => {
    TestValidator.equals("parent match")(c.parent_id)(rootComments[0].id);
  });

  // 7. Pagination - set a small page size
  const pagedList1 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 1, size: 2 } as IDiscussionboardComment.IRequest,
  });
  typia.assert(pagedList1);
  TestValidator.predicate("page1 limited")(pagedList1.data.length <= 2);

  // 8. Pagination - get next page
  const pagedList2 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 2, size: 2 } as IDiscussionboardComment.IRequest,
  });
