/**
 * 키워드와 기간 필터 조합으로 멤버의 검색 기록 리스트 조회(PATCH) 검증
 *
 * - 신규 멤버 가입 후 해당 멤버 명의로 다양한 키워드/시점의 검색 기록을 여러 건 생성한다.
 * - 일부 기록만 매치되는 조합(특정 키워드+기간) 으로 검색 기록 페이지 API를 호출한다.
 * - 반환 결과 목록이 필터 조건과 정확히 일치하는지(검색된 기록만 반환) 및 페이지 info(전체개수/현재페이지 등)가 매칭되는지 검증한다.
 * - 실패 케이스: 잘못된 날짜 포맷, 타인(memberId 불일치) 시 권한/유효성 에러 발생 여부도 확인한다.
 */
export async function test_api_discussionboard_test_search_member_search_histories_with_timeframe_and_keyword_filter(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 여러 키워드/타임스탬프로 검색 기록 추가
  const keywords = [
    "apple_keyword_unique",
    "banana_something",
    "apple_keyword_unique",
    "cherry_different",
  ];
  const timestamps = [
    new Date(Date.now() - 86400000 * 2).toISOString(), // 2일 전
    new Date(Date.now() - 86400000 * 1).toISOString(), // 1일 전
    new Date().toISOString(), // 오늘
    new Date(Date.now() - 86400000 * 3).toISOString(), // 3일 전 (범위 밖)
  ];
  const createdHistories: any[] = [];
  for (let i = 0; i < 4; ++i) {
    // 각 검색 기록 생성
    const history = await api.functional.discussionboard.searchHistories.post(connection, {
      body: {
        ...typia.random<IDiscussionboardSearchHistory.ICreate>(),
        // (아래 memberId/keyword/timestamp는 실제 필요 필드에 맞춰 동적 할당)
        memberId: member.id,
        keyword: keywords[i],
        createdAt: timestamps[i],
      },
    });
    typia.assert(history);
    createdHistories.push(history);
  }

  // 3. 특정 키워드/기간 필터로만 일부 기록 선택되는 조건 작성
  const filterKeyword = "apple_keyword_unique";
  const startDate = new Date(Date.now() - 86400000 * 2).toISOString(); // 2일 전
  const endDate = new Date().toISOString(); // 오늘

  // 4. 검색 기록 patch API 호출: 해당 조건으로 조회
  const page = await api.functional.discussionboard.searchHistories.patch(connection, {
    body: {
      // 실제 필드명/타입 ISearchHistory.IRequest에 맞게 작성 필요
      memberId: member.id,
      keyword: filterKeyword,
      startDate,
      endDate,
      page: 1,
      limit: 20,
    },
  });
  typia.assert(page);

  // 5. 반환된 기록 필드에 대해 정확히 조건만 매치되었는지 확인
  TestValidator.equals("filtered records only")(
    page.data.every(
      (row: any) =>
        row.keyword === filterKeyword &&
        row.createdAt >= startDate &&
        row.createdAt <= endDate,
    ),
  )(true);
  TestValidator.predicate("pagination meta matches filtered count")(
    page.data.length <= 2 && page.total <= 2,
  );

  // 6. 실패 케이스: (1) 잘못된 날짜 형식
  await TestValidator.error("invalid date string validation error")(
    () =>
      api.functional.discussionboard.searchHistories.patch(connection, {
        body: {
          memberId: member.id,
          keyword: filterKeyword,
          startDate: "this-is-not-date",
          endDate,
          page: 1,
          limit: 20,
        },
      }),
  );
  // (2) 타인 검색 기록: 별도 멤버 생성 후 그 멤버 ID로 접근(권한 error)
  const otherMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(otherMember);
  await TestValidator.error("other member id permission error")(
    () =>
      api.functional.discussionboard.searchHistories.patch(connection, {
        body: {
          memberId: otherMember.id,
          keyword: filterKeyword,
          startDate,
          endDate,
          page: 1,
          limit: 20,
        },
      }),
  );
}

