  const thread1 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread1);

  const thread2 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread2);

  // 3. Both members follow both threads
  // Track follows for test assertions
  const followRecords: Array<{
    member: any; // Opaque, but store for referential filtering
    thread: any;
    record: any;
  }> = [];

  // Member 1 follows thread 1
  const follow11 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow11);
  followRecords.push({ member: member1, thread: thread1, record: follow11 });

  // Member 1 follows thread 2
  const follow12 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow12);
  followRecords.push({ member: member1, thread: thread2, record: follow12 });

  // Member 2 follows thread 1
  const follow21 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow21);
  followRecords.push({ member: member2, thread: thread1, record: follow21 });

  // Member 2 follows thread 2
  const follow22 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow22);
  followRecords.push({ member: member2, thread: thread2, record: follow22 });

  // 4. As member 1, list follows (should only see their own)
  // (Simulation: connect as member1 if auth, otherwise just filter by id)
  const listAsMember1 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      // No other filters: get all for member1
    } as any,
  });
  typia.assert(listAsMember1);
  for (const record of (listAsMember1.data?.records ?? [])) {
    if (record.memberId !== member1.id) {
      throw new Error("Member1 should only see their own follows");
    }
  }

  // 5. As member 2, likewise only see theirs
  const listAsMember2 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member2.id,
    } as any,
  });
  typia.assert(listAsMember2);
  for (const record of (listAsMember2.data?.records ?? [])) {
    if (record.memberId !== member2.id) {
      throw new Error("Member2 should only see their own follows");
    }
  }

  // 6. Pagination/filter testing: get member1 follows, page 1, size 1
  const paged = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      page: 1,
      size: 1,
    } as any,
  });
  typia.assert(paged);
  if (!Array.isArray(paged.data?.records) || paged.data.records.length > 1) {
    throw new Error("Should only return at most one record on size 1 page");
  }

  // 7. Filtering by thread id for a member
  const filtered = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      threadId: thread2.id,
    } as any,
  });
  typia.assert(filtered);
  for (const record of (filtered.data?.records ?? [])) {
    if (record.memberId !== member1.id || record.threadId !== thread2.id) {
      throw new Error("Filter by both member and thread must restrict to intersect");
    }
  }

  // 8. Negative/invalid inputs
  await TestValidator.error("bad uuid in memberId")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: "not-a-uuid" as any,
      },
    }),
  );
  await TestValidator.error("negative page index")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: member1.id,
        page: -1,
      },
    }),
  );
}

