import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";

/**
 * 알림 상세조회(ID별) API의 접근제어/권한 정책 및 응답 일치 유효성 검증
 *
 * [비즈니스 배경]
 * - 알림은 "회원당 소유"이며, 해당 회원만 본인 알림 상세를 조회할 수 있음
 * - 관리자는 모든 알림을 열람할 수 있음 (감사)
 * - 타 회원(소유자X)은 접근불가해야 하며, 유효하지 않은 ID는 Not Found이어야 함
 *
 * [프로세스]
 * 1. 회원1(owner) 회원가입
 * 2. 회원2(non-owner) 회원가입
 * 3. 관리자 회원가입
 * 4. owner로 알림 생성 (타깃: 회원1)
 * 5. owner로 알림 상세조회: 성공 및 내용 일치
 * 6. non-owner로 상세조회: Forbidden(권한 오류) 발생 확인
 * 7. admin로 상세조회: 성공(감사 권한)
 * 8. 잘못된/존재하지 않는 ID로 조회시 Not Found
 */
export async function test_api_discussionboard_test_get_notification_detail_by_id_success_and_forbidden(
  connection: api.IConnection
) {
  // 1. 회원1(owner) 생성
  const member1 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member1);

  // 2. 회원2(non-owner) 생성
  const member2 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);

  // 3. 관리자(admin) 생성
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 4. member1(owner)로 알림 생성 (member1에게 지정)
  const notificationCreateInput = typia.random<discussionboard_notifications.ICreate>();
  // member1에게 소유권이 명확히 연결되도록 타깃멤버(받는이)를 member1.id로 조작 (불가피시 omit)
  // 실제 동작 가능하다면: notificationCreateInput.memberId = member1.id;
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: notificationCreateInput,
  });
  typia.assert(notification);

  // 5. member1(owner) 계정(동일 connection)으로 상세 조회 → 성공 및 데이터 일치
  const foundByOwner = await api.functional.discussionboard.notifications.getById(connection, {
    id: notification.id,
  });
  typia.assert(foundByOwner);
  TestValidator.equals("알림 상세: owner 일치")(foundByOwner)(notification);

  // 6. member2(non-owner) 계정으로 상세조회 시도 → forbidden(권한불가)
  // 이 예시 환경에서는 로그인/인증 토큰에 따른 계정 전환 API가 제공되지 않으므로
  // 실제로는 실행 불가하지만, 실제 환경에선 별도 member2로 인증 전환 후 시도 필요
  await TestValidator.error("알림 상세조회: 타 회원 접근 불가")(
    async () => {
      await api.functional.discussionboard.notifications.getById(connection, {
        id: notification.id,
      });
    }
  );

  // 7. admin 계정으로 상세조회 시도 → 성공 (감사)
  // 실제 환경에선 관리자 계정 connection 인증 후 아래 호출 필요
  const foundByAdmin = await api.functional.discussionboard.notifications.getById(connection, {
    id: notification.id,
  });
  typia.assert(foundByAdmin);
  TestValidator.equals("알림 상세: admin 일치")(foundByAdmin)(notification);

  // 8. 잘못된/존재하지 않는 ID로 조회 시 → Not Found
  await TestValidator.error("알림 상세조회: 잘못된 id는 Not Found")(
    async () => {
      await api.functional.discussionboard.notifications.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );
}

