import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate that an admin can update a channel's metadata and visibility.
 *
 * 1. Create a new admin (for authentication).
 * 2. Create a new discussion channel.
 * 3. As admin, update the channel's name and visibility (toggle public/hidden).
 * 4. Confirm in returned result that only the mutable fields are changed: name, description, visibility.
 * 5. Check that the ID hasn't changed and other fields remain as before.
 * 6. Attempt to update again with a second new name and switch visibility back (e.g., hidden to public).
 * 7. Test an edge case: updating to an existing name should fail (if implementation supports unique name enforcement).
 *
 * Test covers both direction of visibility toggling.
 */
export async function test_api_discussionboard_test_update_channel_metadata_and_visibility_as_admin(connection: api.IConnection) {
  // Step 1: Admin registration
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // Step 2: Channel creation
  const origChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(origChannel);

  // Step 3: First update (change name and visibility)
  const newName = RandomGenerator.alphabets(8) + "-changed";
  const newDescription = RandomGenerator.paragraph()();
  const newVisibility = origChannel.visible === true ? false : true;
  const update1 = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName,
      description: newDescription,
      visible: newVisibility,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(update1);

  // Step 4: Validate changed/mutable fields vs others
  TestValidator.notEquals("name updated")(update1.name)(origChannel.name);
  TestValidator.equals("name set")(update1.name)(newName);
  TestValidator.equals("description updated")(update1.description)(newDescription);
  TestValidator.equals("visibility toggled")(update1.visible)(newVisibility);
  TestValidator.equals("ID unchanged")(update1.id)(origChannel.id);

  // Step 5: Update again (switch name and visibility)
  const newName2 = RandomGenerator.alphabets(8) + "-twice";
  const update2 = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName2,
      visible: origChannel.visible, // switch back to original
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(update2);
  TestValidator.equals("name updated again")(update2.name)(newName2);
  TestValidator.equals("visibility reverted")(update2.visible)(origChannel.visible);
  TestValidator.equals("ID still unchanged")(update2.id)(origChannel.id);

  // Step 6: Edge case: (if supported) updating to existing name should fail
  // Create second channel to get unique name
  const otherChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(otherChannel);
  await TestValidator.error("duplicate name should not be allowed")(async () => {
    await api.functional.discussionboard.channels.putById(connection, {
      id: origChannel.id,
      body: { name: otherChannel.name } satisfies IDiscussionboardChannel.IUpdate,
    });
  });
}

