  const newName = RandomGenerator.alphabets(8) + "-changed";
  const newDescription = RandomGenerator.paragraph()();
  const origVisible = origChannel.visible;
  const toggledVisible = origVisible === true ? false : true;
  const updated1 = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName,
      description: newDescription,
      visible: toggledVisible,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(updated1);

  // 4. Assert that changes took effect and stable fields remain
  TestValidator.notEquals("name updated")(updated1.name)(origChannel.name);
  TestValidator.equals("name accurately set")(updated1.name)(newName);
  TestValidator.notEquals("description updated")(updated1.description)(origChannel.description);
  TestValidator.equals("description accurately set")(updated1.description)(newDescription);
  TestValidator.notEquals("visibility toggled")(updated1.visible)(origVisible);
  TestValidator.equals("visibility value")(updated1.visible)(toggledVisible);
  TestValidator.equals("ID unchanged")(updated1.id)(origChannel.id);

  // 5. Update again: new name, revert visibility to original
  const newName2 = RandomGenerator.alphabets(8) + "-twice";
  const reverted = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName2,
