  TestValidator.equals("visibility reverted")(reverted.visible)(origVisible);
  TestValidator.equals("ID still unchanged")(reverted.id)(origChannel.id);

  // 6. Duplicate name edge case
  const otherChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(otherChannel);
  await TestValidator.error("duplicate name should be rejected")(async () => {
