/**
 * 테스트 목적: 유효한 데이터로 섹션 생성에 성공하는 케이스를 검증합니다.
 *
 * 비즈니스 컨텍스트:
 * - 새로운 게시판 섹션을 생성하기 위해서는 반드시 사전에 채널이 존재해야 하며, 섹션의 이름은 해당 채널에서 유일해야 합니다.
 * - 섹션은 이름, 설명, 보여짐 여부, 순서(position)와 같은 정보를 포함합니다. 생성은 반드시 관리자 권한을 가진 계정으로 수행해야 합니다.
 *
 * 테스트 절차:
 * 1. 관리자 권한으로 새로운 채널을 생성한다 (의존성 선행).
 * 2. 고유한 이름, description, position, visible값을 지정하여 섹션을 생성한다. (name은 해당 채널 내에서 유일해야 함)
 * 3. 응답값이 올바른지, 생성된 섹션의 모든 필드가 저장되어 반환되는지 검증한다.
 * 4. 동일한 채널과 동일한 이름으로 중복 섹션 생성 시도 → 오류 발생 확인(유니크 제약조건 확인)
 * 5. 필수 필드를 누락하고 생성 시도 → 오류 발생 확인(필드 누락 검증)
 */
export async function test_api_discussionboard_test_create_section_success_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 새로운 채널을 생성한다.
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>()
  });
  typia.assert(channel);

  // 2. 해당 채널 하위에 고유한 이름, 설명, position, visible을 가진 섹션을 생성
  const uniqueName = `section-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`;
  const sectionInput = {
    // 채널 ID 필수: 생성된 channel의 ID 지정
    channel_id: channel.id,
    name: uniqueName,
    description: "Test section description",
    position: 1,
    visible: true,
  } satisfies IDiscussionboardSection.ICreate;
  const section = await api.functional.discussionboard.sections.post(connection, {
    body: sectionInput,
  });
  typia.assert(section);
  // 채널 ID 및 입력 정보가 그대로 저장/반환되는지 검증
  TestValidator.equals("section.channel_id")(section.channel_id)(channel.id);
  TestValidator.equals("section.name")(section.name)(uniqueName);
  TestValidator.equals("section.description")(section.description)(sectionInput.description);
  TestValidator.equals("section.position")(section.position)(sectionInput.position);
  TestValidator.equals("section.visible")(section.visible)(sectionInput.visible);

  // 3. 동일 채널 및 동일 이름으로 중복 섹션 생성 시도 → 오류 발생
  await TestValidator.error("중복 섹션명 생성 불가")(() =>
    api.functional.discussionboard.sections.post(connection, {
      body: { ...sectionInput },
    }),
  );

  // 4. 필수 필드 누락 케이스: name 생략 시 → 오류 발생 검증
  await TestValidator.error("누락 필드(name) 생성 시 오류")(() =>
    api.functional.discussionboard.sections.post(connection, {
      body: {
        ...sectionInput,
        name: undefined, // TypeScript 상 오류 케이스는 E2E에서 미구현, 값 null/undefined는 타입 오류 및 요청값 오류 발생
      } as any, // 실제 테스트에선 불가능(필드 누락 검증은 스킵)
    }),
  );
}

