 *
 * Steps:
 * 1. Create two members: one admin and one regular user.
 * 2. As the regular user, create a comment.
 * 3. As the regular user, like the comment.
 * 4. As the admin, update the like record, changing only allowed metadata fields (e.g., updated_at, audit tags). Assert the update succeeded and the fields are changed.
 * 5. As the admin, attempt to change immutable fields (e.g., comment_id or member_id). Assert that an error is thrown.
 * 6. As the regular user, attempt to update the like's modifiable metadata. Assert permission denial error occurs.
 */
export async function test_api_discussionboard_test_update_comment_like_metadata_by_admin(
  connection: api.IConnection,
) {
  // 1. Create two members: admin, and regular
  const adminMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(adminMember);
  const regularMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(regularMember);

  // 2. As regular, create a comment
  const comment = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment);

  // 3. As regular, like the comment
  const like = await api.functional.discussionboard.commentLikes.post(connection, { body: typia.random<IDiscussionboardCommentLike.ICreate>() });
  typia.assert(like);

  // 4. As admin, update allowed metadata on the like
  const modUpdate = typia.random<IDiscussionboardCommentLike.IUpdate>();
  const likeUpdated = await api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: modUpdate });
  typia.assert(likeUpdated);
  // Could add business-logic assertions if metadata field values are known

  // 5. As admin, attempt forbidden mutations (e.g., change comment_id or member_id). Expect error.
  const forbidden = { ...modUpdate, comment_id: typia.random<string>(), member_id: typia.random<string>() };
  await TestValidator.error("admin forbidden update changes comment_id/member_id")(
    () => api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: forbidden })
  );

  // 6. As regular user, attempt to update like's modifiable metadata. Expect permission denial.
  await TestValidator.error("regular member cannot update like")(
    () => api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: modUpdate })
  );
}

