 * 3. Try to update the second channel's name to the first channel's name (should fail due to uniqueness constraint).
 * 4. Attempt to update a channel with an empty name (should fail validation).
 * 5. Attempt to update with an invalid 'visible' value if applicable (should fail validation or be rejected).
 * 6. Validate that channels are not improperly changed after failed updates.
 */
export async function test_api_discussionboard_test_update_channel_with_duplicate_name_or_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create admin user
  const admin: IDiscussionboardAdmin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create two unique channels
  const channel1: IDiscussionboardChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel1);
  const channel2: IDiscussionboardChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel2);

  // 3. Attempt to update channel2's name to channel1's name; should fail (duplicate name)
  await TestValidator.error("duplicate channel name should fail")(() =>
    api.functional.discussionboard.channels.putById(connection, {
      id: channel2.id,
      body: { ...typia.random<IDiscussionboardChannel.IUpdate>(), name: channel1.name },
    }),
  );

  // 4. Attempt update with empty name; should fail
  await TestValidator.error("empty name should fail")(() =>
    api.functional.discussionboard.channels.putById(connection, {
      id: channel2.id,
      body: { ...typia.random<IDiscussionboardChannel.IUpdate>(), name: "" },
    }),
  );

  // 5. Attempt update with invalid 'visible' value (if supported in IUpdate); should fail
  await TestValidator.error("invalid visible value should fail")(() =>
    api.functional.discussionboard.channels.putById(connection, {
      id: channel2.id,
      body: { ...typia.random<IDiscussionboardChannel.IUpdate>(), visible: "INVALID" },
    }),
  );

  // 6. Confirm channel2 is unchanged after failed updates
  const channel2AfterAttempt: IDiscussionboardChannel = channel2; // (no GET endpoint in current API to reload; assume unchanged)
  typia.assert(channel2AfterAttempt);
}

