  // 실제로는 connection에서 Authorization 헤더를 빼거나, 신규 연결 사용해야 하지만
  // connection 조작은 외부에서 되어야 하므로 가정 테스트로만 표기
  await TestValidator.error("unauthenticated 사용자는 검색내역 생성이 거부됨")(
    async () => {
      // 인증 없는 연결(가정)로 시도
      await api.functional.discussionboard.searchHistories.post(
        { ...connection, headers: { ...connection.headers, Authorization: undefined } },
        { body: createHistoryBody },
      );
    },
  );
}

