    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 4. File a report for the created post
  const reasonExample = "spam"; // Example reason, adjust as appropriate
  const reportInput: IDiscussionboardReport.ICreate = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    targetPostId: post.id, // Assume the schema expects this link
    reporterId: member.id, // Assume the schema expects this link
    reasonCategory: reasonExample,
    anonymous: false,
  };
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: reportInput,
  });
  typia.assert(report);
  // Basic logical checks for correspondence
  TestValidator.equals("link reporter")(report.reporterId)(member.id);
  TestValidator.equals("link target post")(report.targetPostId)(post.id);
  TestValidator.equals("reasonCategory")(report.reasonCategory)(reasonExample);
  TestValidator.predicate("audit log present")(!!report.auditLogId || !!report.auditTrace);

  // 6. Negative: Try to report with an invalid post ID
  await TestValidator.error("invalid post ID should fail")(async () => {
