import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postReports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postReports";
import type { IDiscussionboardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReport";

/**
 * 테스트 목적:
 * - /discussionboard/postReports/{id} 엔드포인트의 포스트 신고 상태/모더레이터 코멘트 업데이트를 검증한다. 
 * - 관리자 또는 모더레이터만 성공적으로 갱신할 수 있어야 하며, RBAC 정책 및 결재 흐름이 적용되는지 확인한다.
 *
 * 주요 테스트 시나리오
 * 1. (준비) 신고자 회원 생성, 포스트 생성, 신고 생성, 관리자 계정 생성 및 로그인
 * 2. 정상 경로: 관리자로서 신고건의 상태, 코멘트를 수정(해결로 변경 포함) 후 응답 결과 반영 여부 확인
 * 3. 비정상 경로: 이미 해결(종결)된 신고건 재수정 시도 시 실패 예상
 * 4. 유효하지 않은/존재하지 않는/삭제된 신고 id로 업데이트 시 실패 예상
 * 5. 인증없는(비로그인) 접근 시 실패 예상
 * 6. 일반 회원 계정으로 시도 시 권한 오류로 실패 예상
 * 7. (부수) 업데이트 후 감시로그(감사로그)가 갱신되는지 확인 (직접 API는 없으므로 성공여부로 간접 증명)
 *
 * 구현 단계
 * 1. 회원 가입
 * 2. 포스트 작성
 * 3. 신고 생성 (회원으로)
 * 4. 신고 id 추출
 * 5. 관리자 생성
 * 6. (인가 세팅) 관리자 인증 정보 connection에 저장
 * 7. 정상 update (해결 상태/코멘트 수정)
 *    - 응답이 정상이고 반환 값에 즉시 반영됐는지 typia.assert 및 내용 비교
 * 8. 이미 해결된 신고에 재수정 시도 및 실패 확인
 * 9. 랜덤 uuid/nonexistent id, 삭제 id로 update 시도 및 실패 확인
 * 10. 인증 없이 PUT 시도 및 실패 확인
 * 11. 일반회원으로 PUT 시도 및 실패 확인
 * 12. 필요한 경우 추가 필드 업데이트(없는 필드 불가 시 생략)
 */
export async function test_api_discussionboard_postReports_putById_test_update_post_report_status_and_moderator_comments(
  connection: api.IConnection,
) {
  // 1. 신고 회원 가입
  const reporter = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(reporter);

  // 2. 게시글 작성 (멤버 로그인 필수 가정)
  // 인증 정보 덮어쓰기 생략: 기본 connection에 신고자로 로그인했다고 가정
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. 게시글 신고 생성 (신고자)
  const postReport = await api.functional.discussionboard.postReports.post(connection, {
    body: typia.random<Idiscussionboard_postReports.ICreate>(),
  });
  typia.assert(postReport);

  // 4. 신고 id 추출
  const reportId = postReport.id;

  // 5. 관리자 계정 생성/로그인 (connection.headers 덮어씀)
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);
  // 실제 api에서는 connection에 admin 로그인 처리가 별도 필요할 수 있음 (생략)

  // 6. 정상 업데이트: 상태 및 모더레이터 코멘트 갱신
  const updateInput: IDiscussionboardPostReport.IUpdate = typia.random<IDiscussionboardPostReport.IUpdate>();
  const updated = await api.functional.discussionboard.postReports.putById(connection, {
    id: reportId,
    body: updateInput,
  });
  typia.assert(updated);
  // (간접검증) updateInput 내용이 updated에 반영됐는지 비교 가능

  // 7. 이미 해결된 신고 재수정 (가정: updateInput으로 해결함) -> 실패 기대
  await TestValidator.error("이미 해결된 신고건 재수정 실패")(async () => {
    await api.functional.discussionboard.postReports.putById(connection, {
      id: reportId,
      body: typia.random<IDiscussionboardPostReport.IUpdate>(),
    });
  });

  // 8. 존재하지 않거나 삭제된 id로 업데이트 시도 -> 실패 기대
  await TestValidator.error("존재하지 않는 id")(async () => {
    await api.functional.discussionboard.postReports.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: typia.random<IDiscussionboardPostReport.IUpdate>(),
    });
  });

  // 9. 인증없는 임의 connection으로 시도 (connection.headers 비움)
  const connectionUnauth = { ...connection, headers: {} };
  await TestValidator.error("비회원/비로그인 실패")(async () => {
    await api.functional.discussionboard.postReports.putById(connectionUnauth, {
      id: reportId,
      body: typia.random<IDiscussionboardPostReport.IUpdate>(),
    });
  });

  // 10. 일반 회원으로 시도 (reporter로 로그인)
  await TestValidator.error("일반 회원 접근 실패")(async () => {
    await api.functional.discussionboard.postReports.putById(connection, {
      id: reportId,
      body: typia.random<IDiscussionboardPostReport.IUpdate>(),
    });
  });

  // TODO: 업데이트 audit log 직접 확인 불가하므로 성공 응답으로 간접 검증
}

