/**
 * Test listing and searching board feature assignments across a variety of filters and pagination scenarios.
 *
 * Scenario goals:
 * - Create at least two discussion boards, and assign different features to each.
 * - Ensure listing all board features returns both assignments (baseline check).
 * - Filter by feature_key (should reduce results as per key assignment).
 * - Filter by board id (should show only features for that board).
 * - Test with multiple pagination settings for consistency (including edge page/size cases).
 * - Search with invalid feature keys / invalid board ids (should get empty or error responses).
 * - (If system distinguishes roles in auth context, test that only proper roles may view non-public/system features – otherwise exclude.)
 *
 * Steps:
 * 1. Create two boards.
 * 2. Assign two different features (one to each board, with distinct feature_key values).
 * 3. List all features – validate both assignments appear.
 * 4. Filter by feature_key – check result filtered as expected.
 * 5. Filter by one boardId – check only relevant feature shown.
 * 6. Paginate with page/size combos – validate correct slicing/total.
 * 7. Filter on creation time ranges – both in range and out of range to see inclusions/exclusions.
 * 8. Search with invalid feature_key/board id (expect empty or valid error).
 *
 * Validation: Output counts, returned features, correct filtering by board/feature/pagination. (Omit role permission edge case if no API/connection way to emulate roles.)
 */
export async function test_api_discussionboard_test_list_board_features_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create two boards
  const board1 = await api.functional.discussionboard.boards.post(connection, { body: typia.random<IdiscussionboardBoards.ICreate>() });
  typia.assert(board1);
  const board2 = await api.functional.discussionboard.boards.post(connection, { body: typia.random<IdiscussionboardBoards.ICreate>() });
  typia.assert(board2);

  // 2. Assign two distinct features (feature_key differs), one to each board
  const featureKey1 = "feature_key_" + RandomGenerator.alphabets(6);
  const featureKey2 = "feature_key_" + RandomGenerator.alphabets(6);

  const feature1 = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: { ...typia.random<IDiscussionboardBoardFeature.ICreate>(), feature_key: featureKey1, board_id: board1.id },
  });
  typia.assert(feature1);

  const feature2 = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: { ...typia.random<IDiscussionboardBoardFeature.ICreate>(), feature_key: featureKey2, board_id: board2.id },
  });
  typia.assert(feature2);

  // 3. List all board features – expect both assignments present.
  const allFeatures = await api.functional.discussionboard.boardFeatures.patch(connection, {
    body: {} as IDiscussionboardBoardFeature.IRequest,
  });
  typia.assert(allFeatures);
  TestValidator.predicate("all features included")(
    allFeatures.data.some((x:any)=>x.feature_key===featureKey1) &&
    allFeatures.data.some((x:any)=>x.feature_key===featureKey2)
  );

  // 4. Filter by feature_key – should yield only that feature.
  const filteredByKey = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { feature_key: featureKey1 } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(filteredByKey);
  TestValidator.predicate("filter by feature_key single")(
    filteredByKey.data.length===1 && filteredByKey.data[0].feature_key===featureKey1
  );

  // 5. Filter by board id – should yield only features for that board.
  const filteredByBoard1 = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { board_id: board1.id } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(filteredByBoard1);
  TestValidator.predicate("filter by board id")(
    filteredByBoard1.data.every((x:any)=>x.board_id===board1.id)
  );

  // 6. Pagination test – with page / size
  const pageSize = 1;
  const page1 = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { page: 1, size: pageSize } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(page1);

  TestValidator.equals("pagination size")(page1.data.length)(pageSize);

  // 7. Creation time range filtering
  // Use the created_at or similar property, if available, from features for filtering
  if (feature1.created_at && feature2.created_at) {
    const minCreated = feature1.created_at < feature2.created_at ? feature1.created_at : feature2.created_at;
    const maxCreated = feature1.created_at > feature2.created_at ? feature1.created_at : feature2.created_at;
    const inRange = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { created_at_min: minCreated, created_at_max: maxCreated } as IDiscussionboardBoardFeature.IRequest });
    typia.assert(inRange);
    TestValidator.predicate("features in creation time range")(
      inRange.data.some((x:any)=>x.feature_key===featureKey1) &&
      inRange.data.some((x:any)=>x.feature_key===featureKey2)
    );
  }

  // 8. Invalid search – feature_key
  const invalidKey = "invalid_feature_key";
  const emptyKeyResult = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { feature_key: invalidKey } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(emptyKeyResult);
  TestValidator.equals("invalid feature_key yields empty")(emptyKeyResult.data.length)(0);

  // 9. Invalid search – board id
  const invalidId = RandomGenerator.alphabets(12);
  const emptyIdResult = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { board_id: invalidId } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(emptyIdResult);
  TestValidator.equals("invalid board_id yields empty")(emptyIdResult.data.length)(0);

  // End of scenario
}

