/**
 * Validate that updating a section's name in a channel to collide with another section's name is correctly rejected by the API.
 *
 * Business context:
 * - Section names within a channel must be unique.
 * - Attempts to update a section to duplicate an existing section's name in the same channel should fail.
 *
 * Test procedure:
 * 1. As admin, create a discussion board channel.
 * 2. Create two sections in this channel with different names.
 * 3. Attempt to update the second section's name to the first section's name.
 * 4. Expect and validate that an error is thrown due to the name collision (uniqueness constraint).
 */
export async function test_api_discussionboard_test_update_section_with_duplicate_name_in_channel_fails(
  connection: api.IConnection,
) {
  // 1. Create a channel
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 2. Create the first section with name 'first-section'
  const section1 = await api.functional.discussionboard.sections.post(connection, {
    body: {
      ...typia.random<IDiscussionboardSection.ICreate>(),
      channel_id: channel.id,
      name: "first-section",
    },
  });
  typia.assert(section1);

  // 3. Create the second section with name 'second-section'
  const section2 = await api.functional.discussionboard.sections.post(connection, {
    body: {
      ...typia.random<IDiscussionboardSection.ICreate>(),
      channel_id: channel.id,
      name: "second-section",
    },
  });
  typia.assert(section2);

  // 4. Attempt to update the second section's name to 'first-section', expect a uniqueness validation error
  await TestValidator.error(
    "duplicate section name in the same channel is rejected",
  )(() =>
    api.functional.discussionboard.sections.putById(connection, {
      id: section2.id,
      body: {
        ...typia.random<IDiscussionboardSection.IUpdate>(),
        name: "first-section",
      },
    })
  );
}

