 * 2. Login as memberA and create a post
 * 3. Login as memberA and attach a valid file record to the post (success)
 * 4. Verify output includes correct metadata structure (filename, uri, mimetype)
 * 5. Login as memberB and attempt to attach file to memberA's post (should fail per permission policy)
 * 6. Attempt to attach file to a non-existent post (should fail)
 * 7. Attempt to attach invalid file metadata (e.g., invalid mimetype/uri, should fail at validation)
 */
export async function test_api_discussionboard_test_create_post_attachment_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
