    { tagName: generatedTags[2]?.name },
    { boardId: generatedTags[3]?.board_id },
  ];
  for (const filter of filters) {
    const result = await api.functional.discussionboard.boardTags.patch(connection, {
      body: filter as IdiscussionboardBoardTags.IRequest,
    });
    typia.assert(result);
    // 조건에 따라 반환된 항목들이 실제 기대 결과와 일치하는지 확인 (태그명/게시판ID 필터)
