import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postLikes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postLikes";

/**
 * 테스트 목적: 관리자 또는 모더레이터가 게시글 좋아요 레코드의 메타데이터(예: timestamp, 감사(audit) 정보)를 변경하는 기능을 검증합니다.
 *
 * 검증 목표:
 * 1. 허용된 필드(예: created_at)만 업데이트가 가능함을 확인 (post_id, member_id는 불변)
 * 2. 일반 회원은 해당 API에 대해 권한 오류(403/401 등)를 반환함을 확인
 * 3. 수정 후 변경사항이 DB에 반영되고, 감사로그(이벤트/이력 등, 구현된 경우)에서 수정 사실이 알맞게 반영됨을 확인(직접 로그 확인 불가 시, 리턴 값 & 불변값/변경값 비교)
 *
 * 테스트 시나리오:
 * 1. (의존성) 회원 1을 생성
 * 2. (의존성) 게시글 1 생성
 * 3. (의존성) 게시글 좋아요 1개 작성(회원1+게시글1)
 * 4. (관리자 로그인/전환 필요시 시뮬레이션)
 * 5. putById로 좋아요의 허용 필드(예: created_at) 변경 요청 → 정상 변경됨을 리턴 필드에서 검증
 * 6. post_id, member_id 필드는 변경됐는지 시도했을 때 무시/오류/불변임을 확인
 * 7. 일반 회원 권한에서 putById 호출 시 403/401 등 권한 오류 발생을 확인(TestValidator.error)
 */
export async function test_api_discussionboard_test_update_post_like_metadata_by_admin(
  connection: api.IConnection,
) {
  // 1. 회원 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 게시글 생성
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. 좋아요 생성
  const like = await api.functional.discussionboard.postLikes.post(connection, {
    body: {
      post_id: post.id,
      member_id: member.id,
      ...typia.random<Omit<Idiscussionboard_postLikes.ICreate, "post_id" | "member_id">>()
    },
  });
  typia.assert(like);

  // 4. (관리자 권한 시뮬레이션 필요시 처리)
  // 관리자 권한 connection 확보 (구현체가 있거나 시뮬레이션 가능 시)
  // 본 예시에서는 connection 객체를 가정 사용

  // 5. 허용 필드(예: created_at) 변경
  const newCreatedAt = new Date(Date.now() + 100000).toISOString();
  const updateRes = await api.functional.discussionboard.postLikes.putById(connection, {
    id: like.id,
    body: { created_at: newCreatedAt }, // 허용 필드만 변경
  });
  typia.assert(updateRes);
  TestValidator.equals("created_at 변경됨")(updateRes.created_at)(newCreatedAt);
  // post_id, member_id 등은 불변임을 확인
  TestValidator.equals("post_id 불변")(updateRes.post_id)(like.post_id);
  TestValidator.equals("member_id 불변")(updateRes.member_id)(like.member_id);

  // 6. 불변 필드 변경 시도(post_id, member_id)를 body에 실어서 PUT 요청하면 어떻게 되는지(무시/오류/불변)
  const updateRes2 = await api.functional.discussionboard.postLikes.putById(connection, {
    id: like.id,
    body: {
      post_id: typia.random<string>(), // 잘못된 값
      member_id: typia.random<string>(), // 잘못된 값
      created_at: newCreatedAt, // 기존 값
    },
  });
  typia.assert(updateRes2);
  // post_id, member_id가 기존 값과 같음을 확인
  TestValidator.equals("post_id 무시 혹은 불변")(updateRes2.post_id)(like.post_id);
  TestValidator.equals("member_id 무시 혹은 불변")(updateRes2.member_id)(like.member_id);

  // 7. 일반 회원으로 putById 호출 시 권한 오류
  // (connection에 권한 변경 API가 제공되는 경우 가입 회원 세션으로 전환 후 시도)
  TestValidator.error("일반 회원 권한 오류")(async () => {
    await api.functional.discussionboard.postLikes.putById(connection, {
      id: like.id,
      body: { created_at: newCreatedAt },
    });
  });
}

