import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_appeals } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_appeals";

/**
 * Validate admin-only deletion and authorization rules for appeals.
 *
 * This test ensures that only an admin can delete an appeal record via the
 * /discussionboard/appeals/:id endpoint. Attempting the operation as a member
 * or moderator must fail. It also checks the behavior for repeat deletions and
 * the use of non-existent appeal IDs.
 *
 * Workflow:
 * 1. Create a new appeal as a member (setup dependency).
 * 2. Attempt deletion as member (should fail).
 * 3. Attempt deletion as moderator (should fail).
 * 4. Delete as admin (should succeed; validate response type).
 * 5. Attempt to delete again as admin (should fail).
 * 6. Attempt to delete a non-existent (random UUID) appeal as admin (should fail).
 */
export async function test_api_discussionboard_appeals_test_delete_appeal_by_admin(
  connection: api.IConnection,
) {
  // STEP 1. Create an appeal as member (dependency)
  const appeal: discussionboard_appeals =
    await api.functional.discussionboard.appeals.post(connection, {
      body: typia.random<discussionboard_appeals.ICreate>(),
    });
  typia.assert(appeal);

  // ---- STEP 2. Attempt deletion as MEMBER (should fail) ----
  await TestValidator.error("member cannot delete appeal")(async () => {
    await api.functional.discussionboard.appeals.eraseById(connection, {
      id: appeal.id,
    });
  });

  // ---- STEP 3. SWITCH to MODERATOR and attempt deletion (should fail) ----
  // --- (Stub: role switching, see IMPORTANT note below) ---
  // IMPORTANT: If there were actual authentication APIs to swap roles,
  // this is where we would use them to log in as moderator.
  // For this skeleton, we simply simulate the logic inline.
  await TestValidator.error("moderator cannot delete appeal")(async () => {
    await api.functional.discussionboard.appeals.eraseById(connection, {
      id: appeal.id,
    });
  });

  // ---- STEP 4. SWITCH to ADMIN and delete the appeal (should succeed) ----
  // --- (Stub: role switching, see IMPORTANT note below) ---
  // Again, actual role switching would be done via authentication APIs if available.
  const deleted: discussionboard_appeals =
    await api.functional.discussionboard.appeals.eraseById(connection, {
      id: appeal.id,
    });
  typia.assert(deleted);

  // ---- STEP 5. Attempt to delete the same appeal again (should fail) ----
  await TestValidator.error("already deleted appeal should fail")(async () => {
    await api.functional.discussionboard.appeals.eraseById(connection, {
      id: appeal.id,
    });
  });

  // ---- STEP 6. Attempt to delete a non-existent (random UUID) appeal (should fail) ----
  await TestValidator.error("non-existent appeal id should fail")(async () => {
    await api.functional.discussionboard.appeals.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // ---- STEP 7. (OPTIONAL): If audit APIs exist, validate record absence/logs here.
  // Not implemented as no such API is available in current materials.
}

