import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postLikes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postLikes";

/**
 * 검증 시나리오: 특정 게시글 좋아요를 ID로 조회
 *
 * 1. discussionboard_members POST로 두 명 등록 (게시글 작성자, 좋아요 회원)
 * 2. discussionboard_posts POST로 게시글 1개 작성 (작성자=멤버A)
 * 3. 좋아요 누를 멤버B로 로그인(전환) 및 discussionboard_postLikes POST로 게시글에 좋아요를 생성하고 리턴된 likeId 확보
 * 4. 좋아요 누른 멤버(B)로 discussionboard_postLikes/{id} GET 수행: 정상적으로 post_id, member_id, created_at 정보가 정확히 조회되는지 검증
 * 5. 게시글 작성자(A)로 계정 로그인 전환 후 해당 likeId GET: 조회 가능함을 검증
 * 6. 무관한 3번째 유저(멤버C) 생성 후 해당 계정으로 likeId GET: 권한 에러 발생 확인
 * 7. 존재하지 않는 likeId로 GET 시 404 확인
 */
export async function test_api_discussionboard_test_get_single_post_like_by_id_success(
  connection: api.IConnection,
) {
  // 1. 멤버A(게시글 작성자) 생성
  const author = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(author);

  // 2. 멤버B(좋아요 누를 회원) 생성
  const liker = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(liker);

  // 3. 멤버A로 discussionboard_posts POST로 게시글 1개 작성
  // [가정: 인증 컨텍스트 전환 불가 시, API는 member_id를 body에 명시적으로 받는 구조를 활용]
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      ...typia.random<IDiscussionboardPost.ICreate>(),
      member_id: author.id,
    },
  });
  typia.assert(post);

  // 4. 멤버B로 전환 (가정: connection 갱신/세션 전환 필요없음) 후 좋아요 생성
  const like = await api.functional.discussionboard.postLikes.post(connection, {
    body: {
      ...typia.random<Idiscussionboard_postLikes.ICreate>(),
      post_id: post.id,
      member_id: liker.id,
    },
  });
  typia.assert(like);

  // 5. 멤버B(본인)이 likeId로 GET시 성공
  const likeByLiker = await api.functional.discussionboard.postLikes.getById(connection, {
    id: like.id,
  });
  typia.assert(likeByLiker);
  TestValidator.equals("post_id와 일치")(likeByLiker.post_id)(post.id);
  TestValidator.equals("member_id와 일치")(likeByLiker.member_id)(liker.id);
  TestValidator.predicate("created_at 존재")(!!likeByLiker.created_at);

  // 6. 멤버A(게시글 소유자)로 전환 후 GET 가능함 검증
  // (가정: 인증 방식 동일, context update 필요없음)
  // 이 단계에서도 GET이 허용된다고 가정
  const likeByAuthor = await api.functional.discussionboard.postLikes.getById(connection, {
    id: like.id,
  });
  typia.assert(likeByAuthor);
  TestValidator.equals("post_id 확인 - 게시글 작성자 권한")(likeByAuthor.post_id)(post.id);

  // 7. 전혀 무관한 멤버C 생성 및 GET: 권한 거부 에러 검증
  const unrelated = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(unrelated);
  await TestValidator.error("무관 계정 접근 차단")(() =>
    api.functional.discussionboard.postLikes.getById(connection, { id: like.id }),
  );

  // 8. 존재하지 않는 likeId로 GET 시 404 확인
  await TestValidator.error("존재하지 않는 likeId 404")(() =>
    api.functional.discussionboard.postLikes.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

