import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchHistory";

/**
 * 토론 게시판에서 검색 기록을 해당 소유 멤버가 삭제하는 기능을 검증합니다.
 *
 * 1. 소유 멤버는 성공적으로 삭제할 수 있고, 삭제 후 해당 기록이 더 이상 조회되지 않아야 합니다.
 * 2. 다른 멤버 또는 인증되지 않은 사용자가 삭제 시도 시 권한 오류 또는 존재하지 않음(Not Found) 오류가 발생해야 합니다.
 * 3. 이미 삭제된 기록이나 존재하지 않는 id에 대해서는 추가로 삭제를 요청해도 안전한 이드폿(idempotent) 처리, 혹은 명확한 오류 응답이 발생해야 합니다.
 *
 * [테스트 순서]
 * 1. 소유 멤버 회원가입 및 인증 처리
 * 2. 해당 멤버로 검색 기록 생성
 * 3. (NEGATIVE) 부정케이스용 추가 멤버 회원가입
 * 4. 소유자 권한으로 기록 삭제 시도 > 성공 및 정상 삭제 응답 검증
 * 5. 동일 기록 삭제 후 재조회/재삭제 시도 > Not Found 등 처리 확인
 * 6. 추가 멤버 로그인 후 삭제 시도 > 금지(Forbidden) 또는 Not Found 등 오류 확인
 * 7. 인증되지 않은 상태(로그아웃)에서 삭제 시도 > 금지 오류(401/403 등) 확인
 */
export async function test_api_discussionboard_test_delete_search_history_entry_by_owner_and_forbidden_for_others(connection: api.IConnection) {
  // 1. 소유 멤버 회원가입
  const owner = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(owner);

  // 2. 소유 멤버로 검색 기록 생성
  const history = await api.functional.discussionboard.searchHistories.post(connection, { body: typia.random<IDiscussionboardSearchHistory.ICreate>() });
  typia.assert(history);

  // 3. 부정케이스용 세컨더리 멤버 회원가입
  const secondary = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(secondary);

  // 4. 정상 삭제: 소유자 식별 정보로 삭제 시도(로그인/토큰 등 자동 처리 가정)
  const delRes = await api.functional.discussionboard.searchHistories.eraseById(connection, { id: history.id });
  typia.assert(delRes);

  // 5. 삭제 후 재조회/재삭제 시도 (404/에러 등 확인)
  await TestValidator.error("삭제된 검색 기록 재삭제 시도는 safe idempotent 동작")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, { id: history.id }),
  );

  // 6. 세컨더리 멤버로 로그인했다고 가정 후 삭제 시도 (권한 없음)
  // 실제 인증 토큰 전환 로직은 생략, API 조건만 확인
  await TestValidator.error("타 멤버 권한 삭제 시도시 권한or존재하지 않음 오류")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, { id: history.id }),
  );

  // 7. 인증 없는 상태(로그아웃)에서 삭제 시도 (권한 오류)
  // 인증 정보 미포함 상태라면
  await TestValidator.error("비로그인 상태에서 삭제 시도시 권한 오류")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, { id: history.id }),
  );
}

