  const expectedSecondPage = dislikes.length > 6 ? 3 : Math.max(0, dislikes.length - 3);
  TestValidator.equals("page2 count")(resPage2.data.length)(expectedSecondPage);

  // 4f. Invalid: invalid member_id
  await TestValidator.error("invalid member id throws")(async () => {
    await api.functional.discussionboard.postDislikes.patch(connection, {
      body: { member_id: "not-a-valid-id" },
    });
  });

  // 4g. Invalid: date range order
  await TestValidator.error("invalid date order throws")(async () => {
    await api.functional.discussionboard.postDislikes.patch(connection, {
      body: { created_from: "2099-12-31T23:59:59.999Z", created_to: "2000-01-01T00:00:00.000Z" },
    });
  });

  // 4h. Invalid paging (negative)
  await TestValidator.error("invalid page/limit throws")(async () => {
    await api.functional.discussionboard.postDislikes.patch(connection, {
      body: { limit: -1, page: -2 },
    });
  });
}

