 * 2. Create two posts by this member (to allow generation and scoping of edit histories).
 * 3. Edit both posts at least once to trigger edit history/event records.
 * 4. List all edit histories for the first post (should return only the first post's edit events).
 * 5. Search with an editor/member filter (must only return edits by the filtered user).
 * 6. Use a date-range filter to ensure only events in the range are returned.
 * 7. Test page size (limit) controls: request a max page, and an excessive page size to validate enforcement.
 * 8. Attempt invalid/malformed filter (e.g., bad field or type) and expect validation error (use TestValidator.error).
 * 9. Register a second unrelated member, and ensure they cannot list edit histories to posts they do not own — confirm permissions are enforced.
 */
export async function test_api_discussionboard_test_list_post_edit_histories_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
