  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create two posts by this member
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post2);

  // 3. Edit both posts
  const edit1 = await api.functional.discussionboard.posts.putById(connection, {
    id: post1.id,
    body: typia.random<IDiscussionboardPost.IUpdate>(),
  });
  typia.assert(edit1);
  const edit2 = await api.functional.discussionboard.posts.putById(connection, {
    id: post2.id,
    body: typia.random<IDiscussionboardPost.IUpdate>(),
  });
  typia.assert(edit2);

  // 4. List all edit histories for post1
  const page1 = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
  typia.assert(page1);

  // 5. Filter by editor ID
  const page2 = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
