import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";

/**
 * 테스트 목적: 다양한 권한 시나리오에서 단일 게시글 첨부파일(attachment) 상세 정보를 조회하는 API의 권한 및 예외 처리를 검증한다.
 *
 * 비즈니스 컨텍스트:
 * - 게시글에 첨부파일을 올린 사용자는 본인 첨부파일을 정상적으로 조회할 수 있어야 함.
 * - 다른 일반 사용자는 타인의 첨부파일에 접근 시 권한 거부 또는 에러가 발생해야 함.
 * - 관리자 및 모더레이터는 모든 첨부파일 내역을 조회할 수 있어야 함.
 * - 잘못된 ID, 삭제·존재하지 않는 ID 조회 시 적절한 오류 응답이 반환되어야 함.
 *
 * 주요 테스트 단계:
 * 1. 일반 회원(userA) 가입 및 인증 → 게시글 작성
 * 2. userA로 첨부파일 업로드 → 해당 postAttachment의 ID 확보
 * 3. userA로 본인 첨부파일 상세 조회: 성공 및 데이터 검증
 * 4. userB(다른 일반 회원) 가입 및 인증 → userA 첨부파일 조회: 권한 오류/접근거부 검증
 * 5. 관리자(admin) 가입 및 인증 → userA 첨부파일 조회: 성공 및 데이터 검증
 * 6. 랜덤·유효하지 않은 ID로 조회 시 404/오류 검증
 * 7. 삭제·존재하지 않는 첨부파일 ID로 조회 시 적절한 에러 반환 검증
 */
export async function test_api_discussionboard_test_retrieve_post_attachment_by_id_with_permission_variants(
  connection: api.IConnection,
) {
  // 1. userA(일반 회원) 가입 및 인증
  const userA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(userA);

  // 2. userA로 게시글(post) 작성
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. userA로 첨부파일(attachment) 등록
  const attachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(attachment);

  // 4. userA로 본인 첨부파일 상세 조회 (성공)
  const attachmentSelf = await api.functional.discussionboard.postAttachments.getById(connection, {
    id: attachment.id,
  });
  typia.assert(attachmentSelf);
  TestValidator.equals("첨부파일 상세 - 본인 성공")(attachmentSelf.id)(attachment.id);

  // 5. userB(다른 회원) 가입 및 인증
  const userB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(userB);

  // userB로 userA의 첨부파일 접근 시도 (접근 거부 예상)
  await TestValidator.error("타인 첨부파일 접근 차단")(() =>
    api.functional.discussionboard.postAttachments.getById(connection, {
      id: attachment.id,
    })
  );

  // 6. 관리자(admin) 가입 및 인증
  const admin = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(admin);

  // admin 계정으로 userA 첨부파일 조회 (성공)
  const attachmentByAdmin = await api.functional.discussionboard.postAttachments.getById(connection, {
    id: attachment.id,
  });
  typia.assert(attachmentByAdmin);
  TestValidator.equals("admin 첨부파일 조회 성공")(attachmentByAdmin.id)(attachment.id);

  // 7. 잘못된/임의 UUID로 조회 → 404/오류 반환
  await TestValidator.error("유효하지 않은 첨부파일 ID 접근")(() =>
    api.functional.discussionboard.postAttachments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

