import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";

/**
 * 스레드 팔로우 단일 조회 API의 소유자/권한 별 접근성 및 에러 시나리오 검증.
 *
 * - 본인 소유 팔로우 단일 조회 성공(권한 있음)
 * - 타 회원/관리자 접근 시 권한 제어(에러) (단, 로그인/권한 API 미제공 시 구현 불가)
 * - 존재하지 않는 id 조회 시 404 반환 검증
 *
 * [테스트 흐름 및 설명]
 * 1. 멤버A(팔로우 오너)와 멤버B(비오너) 회원을 생성한다.
 * 2. 멤버A가 신규 스레드를 생성한다.
 * 3. 멤버A가 해당 스레드를 팔로우한다.
 * 4. 멤버A의 인증 상태에서 팔로우 id로 단일 조회 API 호출 → 정상적으로 본인 팔로우 단일정보 반환됨을 검증.
 *   (실제 토큰 분기/로그인 전환 없으므로 한 커넥션 사용)
 * 5. (관리자/타 회원 권한 분기 검증: 로그인/권한 전환 API 없으므로 구현 생략)
 * 6. 존재하지 않는, 임의의 UUID(id)로 단일 조회 시 404/에러 반환됨 확인.
 */
export async function test_api_discussionboard_test_get_thread_follow_by_id_as_owner_and_as_admin(
  connection: api.IConnection,
) {
  // 1. 멤버A(오너/수행자)와 멤버B(비오너) 가입
  const memberACreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberA = await api.functional.discussionboard.members.post(connection, { body: memberACreate });
  typia.assert(memberA);

  const memberBCreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberB = await api.functional.discussionboard.members.post(connection, { body: memberBCreate });
  typia.assert(memberB);

  // 2. 멤버A가 스레드 생성
  const threadCreate = typia.random<IDiscussionboardThread.ICreate>();
  const thread = await api.functional.discussionboard.threads.post(connection, { body: threadCreate });
  typia.assert(thread);

  // 3. 멤버A가 해당 스레드를 팔로우
  const threadFollowCreate = typia.random<IDiscussionboardThreadFollow.ICreate>();
  const follow = await api.functional.discussionboard.threadFollows.post(connection, { body: threadFollowCreate });
  typia.assert(follow);

  // 4. 멤버A(오너/수행자)로 본인 팔로우 단일 조회
  const followById = await api.functional.discussionboard.threadFollows.getById(connection, { id: follow.id });
  typia.assert(followById);

  // 5. (타회원/관리자 권한 분기 접근 검증: 로그인/전환 API 미제공이므로 실제 구현 불가, 주석으로 안내 처리)

  // 6. 존재하지 않는 임의 id로 조회시 404/에러 발생 검증
  await TestValidator.error("존재하지 않는 팔로우 id 조회 404")(async () => {
    await api.functional.discussionboard.threadFollows.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

