import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPageDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardPost";

/**
 * Test advanced filtering and pagination for post listing, with permission and edge case checks.
 *
 * This test verifies that posts can be listed with combined filters (thread ID, author ID, published, keyword, date, pagination), and evaluates correct permission handling (admin has full visibility; members see only allowed content).  
 * It covers validation of paginated results and filter accuracy, including edge and error cases. The test is limited by DTOs being 'any', so filters/assertions work only via documented API/blackbox results.
 *
 * Steps:
 * 1. Create an admin and multiple regular members
 * 2. Have each user create posts with varied meta (thread, authorship, published/unpublished)
 * 3. As admin, test all filters:
 *    - By thread ID
 *    - By author ID
 *    - By published/unpublished status
 *    - By keywords
 *    - By date range
 *    - Pagination, including large pageSize
 *    - Multi-filter combinations
 * 4. As regular member, verify only own posts are visible, not hidden/soft-deleted/unpublished by others
 * 5. Edge cases: filters yielding empty, out-of-bounds pagination, invalid filter parameters
 * 6. Validate result set consistency, permission correctness, and error handling as allowed by the DTOs (runtime only)
 */
export async function test_api_discussionboard_test_list_posts_with_advanced_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create test members: admin + 2 regulars
  const adminMember: any = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<any>(),
  });
  typia.assert(adminMember);
  const memberA: any = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<any>(),
  });
  typia.assert(memberA);
  const memberB: any = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<any>(),
  });
  typia.assert(memberB);

  // 2. Each member creates posts (with spread thread/authorship/published flags)
  const posts = [] as any[];
  for (const author of [adminMember, memberA, memberB]) {
    for (let i = 0; i < 3; ++i) {
      const threadId = `thread-${i + 1}`;
      const meta = {
        // Simulate published for two of three
        published: i % 2 === 0,
        // Minimal meta; you may extend if DTO supports
        threadId,
        authorId: author.id,
        title: `Post ${i + 1} by ${author.id}`,
        body: `Content of post ${i + 1} by ${author.id}`,
        // Add varied timestamps for date filtering if possible
      };
      const post: any = await api.functional.discussionboard.posts.post(connection, {
        body: meta,
      });
      typia.assert(post);
      posts.push(post);
    }
  }

  // Choose some IDs for filtering
  const someThreadId = posts[2]?.threadId ?? "thread-1";
  const someAuthorId = memberA.id;
  const somePostKeyword = "Post";
  const somePublished = true;
  const someUnpublished = false;

  // 3A. Query as "admin" (if system supports role switch; here, just query directly)--by thread
  let res = await api.functional.discussionboard.posts.patch(connection, {
    body: { threadId: someThreadId },
  });
  typia.assert(res);
  TestValidator.predicate("all threadId filtered")(
    res.data.every((p: any) => p.threadId === someThreadId),
  );

  // By authorId
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { authorId: someAuthorId },
  });
  typia.assert(res);
  TestValidator.predicate("all authorId filtered")(
    res.data.every((p: any) => p.authorId === someAuthorId),
  );

  // By 'published' status
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { published: somePublished },
  });
  typia.assert(res);
  TestValidator.predicate("all published filtered")(
    res.data.every((p: any) => p.published === somePublished),
  );

  // By 'unpublished' status
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { published: someUnpublished },
  });
  typia.assert(res);
  TestValidator.predicate("all unpublished filtered")(
    res.data.every((p: any) => p.published === someUnpublished),
  );

  // By keyword (title)
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { title: somePostKeyword },
  });
  typia.assert(res);
  TestValidator.predicate("all title contains keyword")(
    res.data.every((p: any) => p.title.includes(somePostKeyword)),
  );

  // By multiple filters (thread + author + published)
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: {
      threadId: someThreadId,
      authorId: someAuthorId,
      published: true,
    },
  });
  typia.assert(res);
  TestValidator.predicate("all filters respected")(
    res.data.every(
      (p: any) =>
        p.threadId === someThreadId &&
        p.authorId === someAuthorId &&
        p.published === true,
    ),
  );

  // Pagination: page 1 + pageSize 2
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { page: 1, pageSize: 2 },
  });
  typia.assert(res);
  TestValidator.predicate("page params respected")(
    res.data.length <= 2,
  );

  // Large pageSize
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { page: 1, pageSize: 100 },
  });
  typia.assert(res);
  TestValidator.predicate("large pageSize handled")(
    res.data.length <= 100,
  );

  // 4. As member, list only own posts
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { authorId: memberB.id },
  });
  typia.assert(res);
  TestValidator.predicate("member only sees own posts")(
    res.data.every((p: any) => p.authorId === memberB.id),
  );

  // 5A. Edge case - filter yields no results
  res = await api.functional.discussionboard.posts.patch(connection, {
    body: { threadId: "nonexistent-thread" },
  });
  typia.assert(res);
  TestValidator.equals("no results on bad filter")(res.data.length)(0);

  // 5B. Invalid filter value (invalid page - negative)
  await TestValidator.error("invalid page fails")(
    async () => {
      await api.functional.discussionboard.posts.patch(connection, {
        body: { page: -1 },
      });
    },
  );

  // 5C. Invalid type (authorId as number/string mismatch if system accepts only specific type)
  await TestValidator.error("invalid authorId fails")(
    async () => {
      await api.functional.discussionboard.posts.patch(connection, {
        body: { authorId: { nonsense: true } },
      });
    },
  );
}

