import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardBoardFeature } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardFeature";
import type { IPageDiscussionboardBoardFeature } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardBoardFeature";

/**
 * Test listing and searching board feature assignments across a variety of filters and pagination scenarios.
 *
 * Scenario goals:
 * - Create at least two discussion boards, and assign different features to each.
 * - Ensure listing all board features returns both assignments (baseline check).
 * - Filter by feature_key (should reduce results as per key assignment).
 * - Filter by board id (should show only features for that board).
 * - Test with multiple pagination settings for consistency (including edge page/size cases).
 * - Search with invalid feature keys / invalid board ids (should get empty or error responses).
 * - (If system distinguishes roles in auth context, test that only proper roles may view non-public/system features – otherwise exclude.)
 *
 * Steps:
 * 1. Create two boards.
 * 2. Assign two different features (one to each board, with distinct feature_key values).
 * 3. List all features – validate both assignments appear.
 * 4. Filter by feature_key – check result filtered as expected.
 * 5. Filter by one boardId – check only relevant feature shown.
 * 6. Paginate with page/size combos – validate correct slicing/total.
 * 7. Filter on creation time ranges – both in range and out of range to see inclusions/exclusions.
 * 8. Search with invalid feature_key/board id (expect empty or valid error).
 *
 * Validation: Output counts, returned features, correct filtering by board/feature/pagination. (Omit role permission edge case if no API/connection way to emulate roles.)
 */
export async function test_api_discussionboard_test_list_board_features_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create two boards
  const board1 = await api.functional.discussionboard.boards.post(connection, { body: typia.random<IdiscussionboardBoards.ICreate>() });
  typia.assert(board1);
  const board2 = await api.functional.discussionboard.boards.post(connection, { body: typia.random<IdiscussionboardBoards.ICreate>() });
  typia.assert(board2);

  // 2. Assign two distinct features (feature_key differs), one to each board
  const featureKey1 = "feature_key_" + RandomGenerator.alphabets(6);
  const featureKey2 = "feature_key_" + RandomGenerator.alphabets(6);

  const feature1 = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: { ...typia.random<IDiscussionboardBoardFeature.ICreate>(), feature_key: featureKey1, board_id: board1.id },
  });
  typia.assert(feature1);

  const feature2 = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: { ...typia.random<IDiscussionboardBoardFeature.ICreate>(), feature_key: featureKey2, board_id: board2.id },
  });
  typia.assert(feature2);

  // 3. List all board features – expect both assignments present.
  const allFeatures = await api.functional.discussionboard.boardFeatures.patch(connection, {
    body: {} as IDiscussionboardBoardFeature.IRequest,
  });
  typia.assert(allFeatures);
  TestValidator.predicate("all features included")(
    allFeatures.data.some((x:any)=>x.feature_key===featureKey1) &&
    allFeatures.data.some((x:any)=>x.feature_key===featureKey2)
  );

  // 4. Filter by feature_key – should yield only that feature.
  const filteredByKey = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { feature_key: featureKey1 } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(filteredByKey);
  TestValidator.predicate("filter by feature_key single")(
    filteredByKey.data.length===1 && filteredByKey.data[0].feature_key===featureKey1
  );

  // 5. Filter by board id – should yield only features for that board.
  const filteredByBoard1 = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { board_id: board1.id } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(filteredByBoard1);
  TestValidator.predicate("filter by board id")(
    filteredByBoard1.data.every((x:any)=>x.board_id===board1.id)
  );

  // 6. Pagination test – with page / size
  const pageSize = 1;
  const page1 = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { page: 1, size: pageSize } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(page1);
  TestValidator.equals("pagination size")(page1.data.length)(pageSize);

  // 7. Creation time range filtering
  // Use the created_at or similar property, if available, from features for filtering
  if (feature1.created_at && feature2.created_at) {
    const minCreated = feature1.created_at < feature2.created_at ? feature1.created_at : feature2.created_at;
    const maxCreated = feature1.created_at > feature2.created_at ? feature1.created_at : feature2.created_at;
    const inRange = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { created_at_min: minCreated, created_at_max: maxCreated } as IDiscussionboardBoardFeature.IRequest });
    typia.assert(inRange);
    TestValidator.predicate("features in creation time range")(
      inRange.data.some((x:any)=>x.feature_key===featureKey1) &&
      inRange.data.some((x:any)=>x.feature_key===featureKey2)
    );
  }

  // 8. Invalid search – feature_key
  const invalidKey = "invalid_feature_key";
  const emptyKeyResult = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { feature_key: invalidKey } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(emptyKeyResult);
  TestValidator.equals("invalid feature_key yields empty")(emptyKeyResult.data.length)(0);

  // 9. Invalid search – board id
  const invalidId = RandomGenerator.alphabets(12);
  const emptyIdResult = await api.functional.discussionboard.boardFeatures.patch(connection, { body: { board_id: invalidId } as IDiscussionboardBoardFeature.IRequest });
  typia.assert(emptyIdResult);
  TestValidator.equals("invalid board_id yields empty")(emptyIdResult.data.length)(0);

  // End of scenario
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardBoardFeature } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardFeature";

/**
 * Validate retrieval of a single board feature assignment by ID.
 *
 * This test covers the following workflow:
 * 1. Create a new discussion board as a prerequisite for feature assignment.
 * 2. Assign a feature to the created board, capturing the assignment's unique id.
 * 3. Retrieve the created board feature assignment by its id and verify that all fields are returned and type-valid.
 * 4. Attempt to retrieve a board feature with a random non-existent id and validate that a 404 error (not found) is returned.
 * 5. (If applicable) Access the API with an unauthorized or unprivileged user and assert that access is denied according to RBAC rules (skipped if no such mechanism/API present).
 */
export async function test_api_discussionboard_boardFeatures_getById(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board to receive the feature assignment (dependency)
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board);

  // 2. Assign a feature to the discussion board (dependency)
  const feature = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: typia.random<IDiscussionboardBoardFeature.ICreate>(),
  });
  typia.assert(feature);

  // 3. Retrieve the created board feature assignment by id
  const fetched = await api.functional.discussionboard.boardFeatures.getById(connection, {
    id: feature.id,
  });
  typia.assert(fetched);
  TestValidator.equals("Returned feature id matches request")(fetched.id)(feature.id);

  // 4. Attempt to retrieve a feature assignment using a random non-existent id, verify 404
  await TestValidator.error("Fetching non-existent board feature returns 404 error")(
    async () => {
      await api.functional.discussionboard.boardFeatures.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    }
  );

  // 5. (If RBAC present) Try fetching as an unauthorized user and assert access denial.
  // Not implemented because authentication/authorization API is not provided in the current materials.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardBoardFeature } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardFeature";

/**
 * Validate creating and enforcing uniqueness of a board feature assignment.
 *
 * This test covers the full business workflow and security aspects of board feature assignments:
 *
 * 1. Create a discussion board for feature assignment.
 * 2. Successfully assign a valid feature to the created board.
 * 3. Confirm the feature assignment is persisted and its core fields match the request values.
 * 4. Attempt to assign the same feature key to the same board again to trigger a uniqueness/conflict error (409 expected).
 * 5. Attempt to assign a feature to a board using an unauthorized connection (should fail with an authorization error).
 *
 * Assertions:
 * - The first successful response is type-safe, and board/feature keys match the request.
 * - Duplicate assignment is rejected with an error.
 * - Unauthorized creation attempt is properly rejected.
 */
export async function test_api_discussionboard_test_create_board_feature_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board (prerequisite)
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board);

  // 2. Assign a valid feature to the board
  const featureInput = typia.random<IDiscussionboardBoardFeature.ICreate>();
  featureInput.board_id = board.id;
  const feature = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: featureInput,
  });
  typia.assert(feature);
  TestValidator.equals('board ID')(feature.board_id)(featureInput.board_id);
  TestValidator.equals('feature key')(feature.feature_key)(featureInput.feature_key);

  // 3. Attempt to assign the same feature key to the same board again (should fail)
  await TestValidator.error('duplicate feature assignment should fail')(
    async () => {
      await api.functional.discussionboard.boardFeatures.post(connection, {
        body: featureInput,
      });
    },
  );

  // 4. Attempt feature assignment as unauthorized user (expect failure)
  const unauthorizedConnection = { ...connection, headers: {} };
  await TestValidator.error('unauthorized create should fail')(
    async () => {
      await api.functional.discussionboard.boardFeatures.post(unauthorizedConnection, {
        body: typia.random<IDiscussionboardBoardFeature.ICreate>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardBoardFeature } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardFeature";

/**
 * Test updating board feature assignments, validating permitted field updates, uniqueness constraints, not found, and insufficient privilege errors.
 *
 * 1. Create two boards (board1, board2) to serve as sources for feature assignment and conflict scenarios.
 * 2. Assign one feature to each board (featureAssignmentA on board1, featureAssignmentB on board2).
 * 3. As an authorized user (admin):
 *    a. Update featureAssignmentA to change a permitted field (such as enabled state or description). Verify successful update.
 *    b. Attempt to update featureAssignmentA's (board_id, feature_key) pair to the same as featureAssignmentB's, expecting a uniqueness constraint error.
 *    c. Attempt to update a non-existent feature assignment id, expecting a not found error.
 *    d. Attempt to update as an unauthorized/non-admin (simulated), expecting a permission error (as SDK does not expose authentication helpers).
 */
export async function test_api_discussionboard_boardFeatures_test_update_board_feature_assignment_fields_and_uniqueness_constraints(
  connection: api.IConnection,
) {
  // 1. Create two boards to enable feature tests and duplication checks
  const board1 = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board1);
  const board2 = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board2);

  // 2. Assign a feature to each board to set up update/duplication tests
  const featureAssignmentA = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: typia.random<IDiscussionboardBoardFeature.ICreate>(),
  });
  typia.assert(featureAssignmentA);
  const featureAssignmentB = await api.functional.discussionboard.boardFeatures.post(connection, {
    body: typia.random<IDiscussionboardBoardFeature.ICreate>(),
  });
  typia.assert(featureAssignmentB);

  // 3a. As authorized user, update permitted fields on featureAssignmentA
  const updated = await api.functional.discussionboard.boardFeatures.putById(connection, {
    id: featureAssignmentA.id,
    body: typia.random<IDiscussionboardBoardFeature.IUpdate>(),
  });
  typia.assert(updated);

  // 3b. Attempt uniqueness violation: change board_id and feature_key to make duplicate assignment
  await TestValidator.error("uniqueness constraint violation")(async () => {
    await api.functional.discussionboard.boardFeatures.putById(connection, {
      id: featureAssignmentA.id,
      body: {
        ...typia.random<IDiscussionboardBoardFeature.IUpdate>(),
        board_id: featureAssignmentB.board_id,
        feature_key: featureAssignmentB.feature_key,
      },
    });
  });

  // 3c. Attempt to update with a non-existent id
  await TestValidator.error("not found for non-existent id")(async () => {
    await api.functional.discussionboard.boardFeatures.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: typia.random<IDiscussionboardBoardFeature.IUpdate>(),
    });
  });

