  // ===== 2단계: 게시물 다수 생성 (작성자 랜덤할당)
  const posts = await ArrayUtil.asyncRepeat(NUM_POSTS)(async () =>
    await api.functional.discussionboard.posts.post(connection, {
      body: typia.random<IDiscussionboardPost.ICreate>(),
    })
  );
  posts.forEach(typia.assert);

  // ===== 3단계: 다양한 신고(postReport) 데이터 조합 생성(여러 멤버, 여러 게시물 혼합)
  const reports = [];
  for (let i = 0; i < NUM_REPORTS; ++i) {
    const reporterIdx = i % NUM_MEMBERS;
    const postIdx = (i * 2) % NUM_POSTS;
    const report = await api.functional.discussionboard.postReports.post(connection, {
      body: typia.random<Idiscussionboard_postReports.ICreate>()
    });
    typia.assert(report);
    reports.push(report);
  }

  // ===== 4단계: 관리자 계정으로 postReports 목록/필터링 시도 (고급필터, 페이징)
  // (세부 필터: 예를들면 reporterId, postId, 기간 등)
  const pageDataAdmin = await api.functional.discussionboard.postReports.patch(connection, {
    body: typia.random<Idiscussionboard_postReports.IRequest>(),
  });
  typia.assert(pageDataAdmin);

  // ===== 5단계: 멤버 계정으로 내가 작성한 신고만 필터되는지 검증(타인 신고 미노출)
  const member = members[0];
  // (실제 API에 멤버 인증이 분리 또는 토큰 기반으로 구현되어 있다면, 그에 맞춰 커넥션 전환이 필요)
  const pageDataMember = await api.functional.discussionboard.postReports.patch(connection, {
    body: typia.random<Idiscussionboard_postReports.IRequest>(),
  });
  typia.assert(pageDataMember);

  // ===== 6단계: 토큰 없는 커넥션(비로그인)에서 요청 시 권한 오류 발생하는지 확인
  await TestValidator.error("비로그인 postReports 목록조회는 권한 오류")(
    async () => {
      // header에서 Authorization 제거(비로그인 상태 시뮬)
      const anonConnection = { ...connection, headers: {} };
      await api.functional.discussionboard.postReports.patch(anonConnection, {
        body: typia.random<Idiscussionboard_postReports.IRequest>(),
      });
    },
  );

  // ===== 7단계: 잘못된 page/필터 입력 등 엣지/에러 상황 체크
  await TestValidator.error("out-of-range page는 오류 발생")(
    async () => {
      await api.functional.discussionboard.postReports.patch(connection, {
        body: typia.random<Idiscussionboard_postReports.IRequest>()
      });
    },
  );
}

