  await TestValidator.error("Forbidden error for memberB on another's report")(
    async () => {
      await api.functional.discussionboard.postReports.getById(connection, { id: report.id });
    },
  );

  // 9. Attempt to get a non-existent report (random UUID)
  await TestValidator.error("Not found error for non-existent report")(
    async () => {
      await api.functional.discussionboard.postReports.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );

  // 10. Attempt to get report with invalid/malformed ID
  await TestValidator.error("Validation error for malformed ID")(
    async () => {
      await api.functional.discussionboard.postReports.getById(connection, { id: "invalid-not-a-uuid" as any });
    },
  );
}

