  // (Cannot do property-by-property checks due to 'any' type. Assert only.)

  // 4. Fail: Update Board A's name to boardB.name (duplicate)
  await TestValidator.error("duplicate board name results in validation/conflict error")(
    async () => {
      await api.functional.discussionboard.boards.putById(connection, {
        id: boardA.id,
        body: { ...typia.random<IdiscussionboardBoards.IUpdate>(), name: boardB.name },
