  await TestValidator.error("update by unauthorized/non-admin is forbidden")(
    async () => {
      await api.functional.discussionboard.boards.putById(unauthConn, {
        id: boardA.id,
        body: typia.random<IdiscussionboardBoards.IUpdate>(),
      });
