      await api.functional.discussionboard.boards.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: typia.random<IdiscussionboardBoards.IUpdate>(),
      });
    },
  );
  // 7. Immutable field enforcement not possible (DTOs are any).
}

