import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate fetching a discussion board admin by ID, including positive and negative cases.
 *
 * 1. Create an admin and retrieve it by its UUID, ensuring all relevant details are correct, and the password hash is not present.
 * 2. Attempt to fetch using an invalid UUID format for the ID parameter (expect validation error).
 * 3. Attempt to fetch a non-existing (valid format, but not present) UUID and verify a 404 Not Found error results.
 * 4. Check that fetching as a non-admin user produces a 403 Forbidden error.
 */
export async function test_api_discussionboard_admins_test_get_admin_by_id_valid_and_invalid_cases(connection: api.IConnection) {
  // 1. Create an admin to obtain a valid UUID
  const createdAdmin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(createdAdmin);

  // 2. Retrieve by its UUID and validate details
  const fetchedAdmin = await api.functional.discussionboard.admins.getById(connection, {
    id: createdAdmin.id,
  });
  typia.assert(fetchedAdmin);
  // Check that the admin ID matches
  TestValidator.equals("admin id matches")(fetchedAdmin.id)(createdAdmin.id);

  // 3. Fetch with invalid UUID (bad format)
  await TestValidator.error("invalid UUID format returns validation error")(
    async () => {
      await api.functional.discussionboard.admins.getById(connection, { id: "not-a-uuid" as any });
    },
  );

  // 4. Fetch with non-existing, but valid UUID
  await TestValidator.error("non-existing admin id returns 404")(
    async () => {
      await api.functional.discussionboard.admins.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. Attempt fetching as a non-admin (simulate by removing authorization)
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("fetching as non-admin produces forbidden")(
    async () => {
      await api.functional.discussionboard.admins.getById(noAuthConnection, { id: createdAdmin.id });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
