/**
 * E2E test for creating new admin accounts on the discussion board platform.
 *
 * Validates business-critical flows, including:
 * 1. Successfully creating a new admin with unique credentials.
 * 2. Failure to create a new admin with duplicate email/username.
 * 3. Failure for invalid email or weak password.
 * 4. Privilege enforcement: non-admins/unauthenticated users are forbidden.
 *
 * Note: Since field-level structure is declared `any`, only operation flow and error branches are covered.
 */
export async function test_api_discussionboard_test_create_admin_with_valid_and_duplicate_email_username(
  connection: api.IConnection,
) {
  // 1. Successfully create admin with unique credentials.
  const validAdminInput: any = {
    email: typia.random<string & tags.Format<"email">>(),
    username: RandomGenerator.alphabets(8),
    password: RandomGenerator.alphaNumeric(16),
  };
  const createdAdmin = await api.functional.discussionboard.admins.post(connection, { body: validAdminInput });
  typia.assert(createdAdmin);

  // 2. Conflict: duplicate email/username not allowed.
  await TestValidator.error("Duplicate admin creation fails")(() =>
    api.functional.discussionboard.admins.post(connection, {
      body: { ...validAdminInput, password: RandomGenerator.alphaNumeric(16) },
    })
  );

  // 3. Validation: invalid email/weak password should fail.
  await TestValidator.error("Invalid email format fails")(() =>
    api.functional.discussionboard.admins.post(connection, {
      body: { ...validAdminInput, email: "invalid-email", username: RandomGenerator.alphabets(8), password: RandomGenerator.alphaNumeric(16) },
    })
  );
  await TestValidator.error("Weak password fails")(() =>
    api.functional.discussionboard.admins.post(connection, {
      body: { ...validAdminInput, password: "123" },
    })
  );

  // 4. Privilege: non-admin user or unauthenticated should fail.
  const nonAdminConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("Forbidden for non-admin user")(() =>
    api.functional.discussionboard.admins.post(nonAdminConnection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        username: RandomGenerator.alphabets(8),
        password: RandomGenerator.alphaNumeric(16),
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * E2E Test: Update Discussion Board Admin (permissions, validation, side effects)
 *
 * This test verifies the update functionality for discussion board admin accounts, focusing on three dimensions:
 * (1) Correct, privileged update succeeds and changes are reflected.
 * (2) Unprivileged or improper attempts fail (permissions, re-auth required, etc.).
 * (3) Uniqueness validation prevents duplicates.
 * (4) Auditability/side effect: change is persisted in the returned entity.
 *
 * Workflow:
 * 1. Create two admin accounts (adminA: privileged, adminB: for permission and duplication testing).
 * 2. Update adminA's fields with unique new values (simulate privilege).
 * 3. Attempt update as another (simulate non-privileged); expect error.
 * 4. Attempt duplicate email/username bug; expect validation error.
 *
 * Notes:
 * - Only POST and PUT-by-ID endpoints are available in this SDK; GET and audit log testing is omitted.
 * - All privilege/permission checks are simulated to the extent possible under available API constraints.
 */
export async function test_api_discussionboard_test_update_admin_fields_with_permission_and_validation(
  connection: api.IConnection,
) {
  // 1. Create adminA
  const adminA = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminA);

  // 2. Create adminB
  const adminB = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminB);

  // 3. Valid update by privileged adminA (simulate privilege)
  const newEmail = typia.random<string>();
  const newUsername = typia.random<string>();
  const newPassword = typia.random<string>();
  const updatedAdmin = await api.functional.discussionboard.admins.putById(connection, {
    id: adminA.id,
    body: {
      email: newEmail,
      username: newUsername,
      password: newPassword,
    } satisfies IDiscussionboardAdmin.IUpdate,
  });
  typia.assert(updatedAdmin);
  TestValidator.equals("email updated")(updatedAdmin.email)(newEmail);
  TestValidator.equals("username updated")(updatedAdmin.username)(newUsername);

  // 4. Attempt update as another admin (simulate non-privilege by using adminB's id to update adminB; actual context switching is not implemented)
  TestValidator.error("Only privileged admin can update others")(
    async () => {
      await api.functional.discussionboard.admins.putById(connection, {
        id: adminB.id,
        body: {
          email: newEmail,
        },
      });
    },
  );

  // 5. Attempt update with duplicate email/username (should fail uniqueness)
  TestValidator.error("Duplicate email/username triggers validation error")(
    async () => {
      await api.functional.discussionboard.admins.putById(connection, {
        id: adminA.id,
        body: {
          email: adminB.email,
          username: adminB.username,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * 플랫폼 관리자 소프트 딜리트(삭제) API 종합 검증
 *
 * 이 테스트는 관리자 계정 소프트 삭제(soft-delete) 기능에 대해 주요 케이스를 다음과 같이 검증합니다:
 *
 * 1. 서로 다른 2명의 새로운 관리자를 생성(A: privileged, B: target).
 * 2. 관리 A가 B를 삭제(soft-delete)하면, 응답과 deleted_at 필드 존재 및 변경을 검증합니다.
 * 3. 관리 A가 자신의 계정(본인 id) 삭제 시도를 하면 forbidden/권한실패(403 등)가 반환되는지 확인합니다.
 * 4. 무작위/존재하지 않는 UUID로 삭제 시도 시 404 등이 반환되는지 확인합니다.
 * 5. 관리자 권한이 없는 connection에서 삭제 시도 시 인증/권한 에러(401/403 등)가 발생하는지 검사합니다.
 * 6. 실제 감사 로그는 별도 조회 기능이 없어, deleted_at 값이 적절히 변화하는 것(soft-delete)으로 간접 검증합니다.
 *
 * 시험 순서는: 관리자 생성 → 소프트 딜리트 성공 케이스 → 각종 에러(본인 삭제, 미존재/권한 실패).
 */
export async function test_api_discussionboard_test_soft_delete_admin_by_id_with_audit_validation(
  connection: api.IConnection,
) {
  // 1. 관리자 A(삭제 수행자) 계정 생성
  const adminA = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminA);
  // 2. 관리자 B(삭제 대상자) 계정 생성
  const adminB = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminB);

  // 3. A가 B 계정 삭제 시도(정상 케이스):
  const deleted = await api.functional.discussionboard.admins.eraseById(connection, {
    id: adminB.id,
  });
  typia.assert(deleted);
  // deleted_at 값 존재(soft-delete) 확인
  TestValidator.predicate("deleted_at must exist")(!!deleted.deleted_at);
  // id 동일
  TestValidator.equals("deleted id matches")(deleted.id)(adminB.id);

  // 4. 본인(A) 계정 본인 삭제 → forbidden/권한실패(error)
  await TestValidator.error("cannot delete own admin account")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(connection, {
        id: adminA.id,
      });
    },
  );

  // 5. 임의의 무작위 UUID(존재하지 않는 id)로 삭제 시도 → 404 error
  await TestValidator.error("non-existent UUID returns 404")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 6. (권한 없는 connection) 비관리자 권한 상태로 삭제 시도 → 401/403
  // 권한없는 커넥션 모의: typia.random<IConnection>()로도 시도
  const anonymousConnection = typia.random<api.IConnection>();
  await TestValidator.error("non-admin connection forbidden")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(anonymousConnection, {
        id: adminB.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";
import type { IPageDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardThreadFollow";

/**
 * Test filtered, paginated listing and permission checks for thread follow records in the discussion board.
 *
 * This end-to-end test validates several core behaviors:
 * - Regular members can only list thread follows where they themselves are the follower
 * - Filter/search/pagination parameters (memberId, threadId, follow date, etc) work and restrict results as intended
 * - The API never leaks follow information the actor does not own/cannot access
 * - Invalid input (malformed UUIDs, negative pagination) is rejected cleanly
 *
 * The test covers:
 * 1. Creation of two members
 * 2. Creation of two threads
 * 3. Both members following both threads in cross-pattern
 * 4. Listing as member 1: should only see their own follows, even if filters for other member/thread are used
 * 5. Listing as member 2: likewise only see own follows
 * 6. Pagination/filtering with real IDs
 * 7. Negative/invalid parameter inputs (bad uuid/negative page)
 */
export async function test_api_discussionboard_test_list_thread_follows_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create two members
  const member1 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);

  // 2. Create two threads
  const thread1 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread1);

  const thread2 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread2);

  // 3. Both members follow both threads
  // Track follows for test assertions
  const followRecords: Array<{
    member: any; // Opaque, but store for referential filtering
    thread: any;
    record: any;
  }> = [];

  // Member 1 follows thread 1
  const follow11 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow11);
  followRecords.push({ member: member1, thread: thread1, record: follow11 });

  // Member 1 follows thread 2
  const follow12 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow12);
  followRecords.push({ member: member1, thread: thread2, record: follow12 });

  // Member 2 follows thread 1
  const follow21 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow21);
  followRecords.push({ member: member2, thread: thread1, record: follow21 });

  // Member 2 follows thread 2
  const follow22 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow22);
  followRecords.push({ member: member2, thread: thread2, record: follow22 });

  // 4. As member 1, list follows (should only see their own)
  // (Simulation: connect as member1 if auth, otherwise just filter by id)
  const listAsMember1 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      // No other filters: get all for member1
    } as any,
  });
  typia.assert(listAsMember1);
  for (const record of (listAsMember1.data?.records ?? [])) {
    if (record.memberId !== member1.id) {
      throw new Error("Member1 should only see their own follows");
    }
  }

  // 5. As member 2, likewise only see theirs
  const listAsMember2 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member2.id,
    } as any,
  });
  typia.assert(listAsMember2);
  for (const record of (listAsMember2.data?.records ?? [])) {
    if (record.memberId !== member2.id) {
      throw new Error("Member2 should only see their own follows");
    }
  }

  // 6. Pagination/filter testing: get member1 follows, page 1, size 1
  const paged = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      page: 1,
      size: 1,
    } as any,
  });
  typia.assert(paged);
  if (!Array.isArray(paged.data?.records) || paged.data.records.length > 1) {
    throw new Error("Should only return at most one record on size 1 page");
  }

  // 7. Filtering by thread id for a member
  const filtered = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      threadId: thread2.id,
    } as any,
  });
  typia.assert(filtered);
  for (const record of (filtered.data?.records ?? [])) {
    if (record.memberId !== member1.id || record.threadId !== thread2.id) {
      throw new Error("Filter by both member and thread must restrict to intersect");
    }
  }

  // 8. Negative/invalid inputs
  await TestValidator.error("bad uuid in memberId")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: "not-a-uuid" as any,
      },
    }),
  );
  await TestValidator.error("negative page index")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: member1.id,
        page: -1,
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";

/**
 * 스레드 팔로우 단일 조회 API의 소유자/권한 별 접근성 및 에러 시나리오 검증.
 *
 * - 본인 소유 팔로우 단일 조회 성공(권한 있음)
 * - 타 회원/관리자 접근 시 권한 제어(에러) (단, 로그인/권한 API 미제공 시 구현 불가)
 * - 존재하지 않는 id 조회 시 404 반환 검증
 *
 * [테스트 흐름 및 설명]
 * 1. 멤버A(팔로우 오너)와 멤버B(비오너) 회원을 생성한다.
 * 2. 멤버A가 신규 스레드를 생성한다.
