/**
 * Test creating a new thread follow as a registered member and verify duplicate prevention.
 *
 * 1. Register a new discussion board member (user).
 * 2. Create a discussion thread as that member.
 * 3. As the member, follow the thread (should succeed).
 * 4. Attempt to follow the same thread again with the same member (should fail with 409 Conflict).
 * 5. Attempt to follow a non-existent thread (should fail with 404 Not Found).
 * 6. Attempt to follow as an unauthorized/unregistered user (should fail with 403 Forbidden).
 */
export async function test_api_discussionboard_test_create_thread_follow_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register a new member (user)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a discussion thread as that member
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 3. As the member, follow the thread (should succeed)
  const followParams = typia.random<IDiscussionboardThreadFollow.ICreate>();
  const follow = await api.functional.discussionboard.threadFollows.post(connection, {
    body: followParams,
  });
  typia.assert(follow);
  // If ID properties exist, you could check:
  // TestValidator.equals("thread id matches")(follow.threadId)(followParams.threadId);
  // TestValidator.equals("member id matches")(follow.memberId)(followParams.memberId);

  // 4. Attempt to follow the same thread again (should fail with 409 Conflict)
  await TestValidator.error("Duplicate thread follow should fail with 409")(() =>
    api.functional.discussionboard.threadFollows.post(connection, {
      body: followParams,
    })
  );

  // 5. Attempt to follow a non-existent thread (should fail with 404)
  const nonExistentFollowParams = {
    ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
    threadId: "00000000-0000-0000-0000-000000000000",
  };
  await TestValidator.error("Follow on non-existent thread should fail with 404")(() =>
    api.functional.discussionboard.threadFollows.post(connection, {
      body: nonExistentFollowParams,
    })
  );

  // 6. Attempt to follow as unauthorized/unregistered user (should fail with 403)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("Follow as unauthenticated user should fail with 403")(() =>
    api.functional.discussionboard.threadFollows.post(unauthConnection, {
      body: followParams,
    })
  );
}

