    api.functional.discussionboard.threadFollows.putById(connection, {
      id: threadFollow.id,
      body: typia.random<IDiscussionboardThreadFollow.IUpdate>(),
    })
  );

  // 7. 존재하지 않는 랜덤 팔로우ID에 putById 시도 시 Not Found(404)
  TestValidator.error('존재하지 않는 팔로우ID putById → 404')(() =>
    api.functional.discussionboard.threadFollows.putById(connection, {
