    api.functional.discussionboard.commentEditHistories.patch(connection, {
      body: { comment_id: "not-a-uuid" } satisfies IDiscussionboardCommentEditHistory.IRequest,
    })
  );

  // 6. Request a non-existent page (very large page number)
  const emptyResult = await api.functional.discussionboard.commentEditHistories.patch(connection, {
    body: { page: 9999, limit: 10 } satisfies IDiscussionboardCommentEditHistory.IRequest,
  });
  typia.assert(emptyResult);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
