import type { IPageIDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentEditHistory";

/**
 * Test retrieving a specific discussion board comment edit history record by ID.
 *
 * This test verifies the life cycle of comment edit audit history:
 * 1. Create a comment
 * 2. Edit the comment (to trigger an edit audit record)
 * 3. List edit histories for the comment to obtain a real edit history ID
 * 4. Retrieve the history record by ID and check fields
 * 5. Attempt to fetch a bogus/non-existent or unauthorized record and expect error (404/403)
 *
 * Due to type=any for DTOs, deep property checks are impossible, but type- and ID-level threading can be confirmed.
 */
export async function test_api_discussionboard_test_get_comment_edit_history_by_id_existing_and_nonexistent(
  connection: api.IConnection,
) {
  // 1. Create a new comment
  const createdComment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(createdComment);

  // 2. Edit the comment to generate an edit history
  const editedComment = await api.functional.discussionboard.comments.putById(connection, {
    id: createdComment.id,
    body: typia.random<IDiscussionboardComment.IUpdate>(),
  });
  typia.assert(editedComment);

  // 3. List all edit histories for the comment
  const historiesPage = await api.functional.discussionboard.commentEditHistories.patch(connection, {
    body: { comment_id: createdComment.id } as any, // Filtering by comment (cannot check scheme, type=any)
  });
  typia.assert(historiesPage);

  // Should have at least one history (the just-made edit)
  if (!Array.isArray(historiesPage.data) || historiesPage.data.length === 0)
    throw new Error("No edit histories returned for updated comment");
  const historyItem = historiesPage.data[0];
  if (!historyItem?.id)
    throw new Error("First edit history record missing 'id' property");

  // 4. Retrieve the specific history record by its ID
  const retrieved = await api.functional.discussionboard.commentEditHistories.getById(connection, {
    id: historyItem.id,
  });
  typia.assert(retrieved);
  // Minimal cross-thread validation possible (opaque DTO): ID matches history list
  TestValidator.equals("edit history id")(retrieved.id)(historyItem.id);

  // 5. Attempt to retrieve a non-existent or unauthorized edit history record
  await TestValidator.error("should fail to get non-existent edit history")(
    () => api.functional.discussionboard.commentEditHistories.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentEditHistory";

/**
 * Validate the creation of a discussion board comment edit history when a comment is edited.
 *
 * This function will:
 * 1. Create a new discussion board comment (via /discussionboard/comments POST).
 * 2. Edit the comment using valid update data (via /discussionboard/comments/{id} PUT)
 *    to simulate an actual edit operation.
 * 3. Create an explicit edit history record for that comment (via /discussionboard/commentEditHistories POST), referencing the comment and editor.
 * 4. Verify the new edit history record matches the edit data, references the correct comment and editor.
 * 5. Attempt to create a commentEditHistory where the comment or editor does not exist, and verify the API responds with an error (TestValidator.error, expect 400/404 or similar).
 */
export async function test_api_discussionboard_test_create_comment_edit_history_on_comment_edit(
  connection: api.IConnection,
) {
  // 1. Create a base comment
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 2. Edit the comment to simulate a real edit
  const editedBody = typia.random<IDiscussionboardComment.IUpdate>();
  const editedComment = await api.functional.discussionboard.comments.putById(connection, {
    id: comment.id,
    body: editedBody,
  });
  typia.assert(editedComment);

  // 3. Create a comment edit history explicitly
  const historyInput = {
    // Assume ICreate for edit history needs comment_id, editor_member_id, and the new body.
    comment_id: comment.id,
    editor_member_id: comment.author_id ?? comment.member_id ?? comment.editor_id ?? typia.random<string>(),
    body: editedBody.body ?? editedComment.body ?? typia.random<string>(),
  } satisfies IDiscussionboardCommentEditHistory.ICreate;
  const editHistory = await api.functional.discussionboard.commentEditHistories.post(connection, {
    body: historyInput,
  });
  typia.assert(editHistory);
  TestValidator.equals("comment_id on editHistory")(editHistory.comment_id)(comment.id);
  TestValidator.equals("body on editHistory")(editHistory.body)(historyInput.body);
