  const memberA = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberB);
  const adminMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(adminMember);

  // 2. 댓글 생성 (멤버A의 댓글이어야 이상적이나, 타입상 랜덤)
  const comment = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment);

  // 3. 싫어요 생성 (멤버A것이어야 하나 정보가 없어 타입상 랜덤)
  const dislike = await api.functional.discussionboard.commentDislikes.post(connection, { body: typia.random<IDiscussionboardCommentDislike.ICreate>() });
  typia.assert(dislike);

  // 4. 생성된 dislike 를 id로 상세조회(성공)
  const found = await api.functional.discussionboard.commentDislikes.getById(connection, { id: dislike.id });
  typia.assert(found);

  // 5. 임의로 존재하지 않을 만한 id로 조회 시(실패-에러남)
  await TestValidator.error("임의의 없는 dislike id(detail) 조회시 에러처리됨을 확인")(
    async () => {
      await api.functional.discussionboard.commentDislikes.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );
}

