import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchHistory";

/**
 * 토론 게시판에서 검색 기록의 삭제 및 권한 관련 시나리오를 검증합니다.
 *
 * [비즈니스 목적 및 필요성]
 * - 토론 게시판의 회원은 자신의 검색 기록을 삭제(erasable)할 수 있어야 하며,
 *   타인이 해당 기록에 접근 또는 삭제할 수 없어야 합니다.
 * - GDPR/CCPA 등 데이터 삭제 권리와, 보안/프라이버시 규정 준수를 보장함
 * - 이미 삭제된 항목이나 존재하지 않는 검색 기록에 대한 추가 삭제 요청은 idempotent 하거나 명확히 오류(404 등)로 응답해야 합니다.
 *
 * [시나리오]
 * 1. 소유 멤버 생성 및 인증(로그인)
 * 2. 소유 멤버로 검색 기록 생성
 * 3. 부정 케이스용 secondary 회원 생성
 * 4. (SUCCESS) 소유 멤버가 정상적으로 자신의 검색 기록 삭제
 * 5. (NEGATIVE) 삭제 후 동일 id 재삭제 시도(idempotency, 404 등 기대)
 * 6. (NEGATIVE) secondary 멤버가 남의 기록 삭제 시도(Forbidden/NotFound 등 오류)
 * 7. (NEGATIVE) 인증 없는 상태(비로그인)에서 검색 기록 삭제 시도(권한 오류)
 *
 * 단, 이 테스트는 인증 상태 전환(로그인/로그아웃/token switching) API가 부재하다고 가정하고,
 * connection 객체 context 전환 없이 단일 connection 기준으로 검증 수행함.
 */
export async function test_api_discussionboard_test_delete_search_history_entry_by_owner_and_forbidden_for_others(
  connection: api.IConnection,
) {
  // 1. 소유 멤버 회원가입 (owner)
  const owner = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(owner);

  // 2. 소유 멤버로 검색 기록 생성
  const history = await api.functional.discussionboard.searchHistories.post(connection, {
    body: typia.random<IDiscussionboardSearchHistory.ICreate>(),
  });
  typia.assert(history);

  // 3. 세컨더리 멤버 생성(negative test)
  const secondary = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(secondary);

  // 4. (SUCCESS) owner가 자기 검색 기록 정상 삭제
  const delRes = await api.functional.discussionboard.searchHistories.eraseById(connection, {
    id: history.id,
  });
  typia.assert(delRes);

  // 5. (NEGATIVE) 이미 삭제된 기록을 다시 삭제 시도 (idempotency, not found 등 정책 기대)
  await TestValidator.error("이미 삭제된 기록 재삭제: 정책에 따라 idempotent OK 또는 명확한 오류")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, {
      id: history.id,
    }),
  );

  // 6. (NEGATIVE) secondary 멤버 관점에서 남 기록 삭제 시도 (Forbidden/NotFound 등)
  await TestValidator.error("타 사용자 권한으로 기록 삭제 시도: forbidden or not found 등 오류 기대")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, {
      id: history.id,
    }),
  );

  // 7. (NEGATIVE) 인증 정보 없이(비로그인) 삭제 시도 (권한 오류)
  await TestValidator.error("비로그인 상태에서 기록 삭제 시도: 인증 오류 기대")(
    () => api.functional.discussionboard.searchHistories.eraseById(connection, {
      id: history.id,
    }),
  );
}

