/**
 * 테스트: 관리자가 moderator 할당 메타데이터를 업데이트하는 시나리오
 *
 * - 관리자(admin) 계정으로 member를 생성
 * - 관리자(admin) 계정이 해당 member를 moderator로 지정
 * - 관리자(admin)가 moderator 할당의 메타데이터(예: revoked_at)를 업데이트
 * - 허용되지 않은 필드로 업데이트 시도 시 거부 또는 무시되는지 확인
 * - 존재하지 않는 moderator assignment ID로 업데이트 시도(404 발생 확인)
 * - 비관리자(멤버)가 직접 업데이트 시 권한 오류 확인(실제 권한 스위칭 지원 시에만)
 * - 정상 업데이트 시 반환 객체에서 올바른 값 변경 확인
 *
 * 절차:
 * 1. 관리자(admin) 계정 생성
 * 2. 멤버(member) 계정 생성
 * 3. moderator 할당 생성(admin에 의해 수행)
 * 4. revoked_at(=권한 회수 시점) 업데이트 가능 여부 검증
 * 5. 허용되지 않은 필드의 업데이트 시도(거부/무시 확인)
 * 6. 존재하지 않는 ID로 업데이트 시 404 에러 확인
 * 7. 비관리자 권한으로 업데이트 시 권한 거부(지원될 때만)
 * 8. 정상 반환값이 요청값대로 변경되었는지 검증
 */
export async function test_api_discussionboard_test_update_moderator_assignment_status_and_metadata(
  connection: api.IConnection,
) {
  // 1. 관리자 계정 생성
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. 멤버 계정 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 3. moderator 할당 생성
  const modAssign = await api.functional.discussionboard.moderators.post(connection, {
    body: typia.random<IDiscussionboardModerator.ICreate>(),
  });
  typia.assert(modAssign);

  // 4. revoked_at(회수 시각) 업데이트
  const newRevokedAt = new Date().toISOString();
  const updated = await api.functional.discussionboard.moderators.putById(connection, {
    id: modAssign.id,
    body: { revoked_at: newRevokedAt } as IDiscussionboardModerator.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("revoked_at 업데이트됨")(updated.revoked_at)(newRevokedAt);

  // 5. 허용되지 않은 필드(id, member_id 등) 업데이트 시도 → 거부 또는 무시됨 확인
  await TestValidator.error("non-updatable fields rejected or ignored")(() =>
    api.functional.discussionboard.moderators.putById(connection, {
      id: modAssign.id,
      body: { id: "forbidden", member_id: "forbidden" } as IDiscussionboardModerator.IUpdate,
    }),
  );

  // 6. 존재하지 않는 ID로 업데이트 시 404 확인
  await TestValidator.error("존재하지 않는 moderator는 404 발생")(() =>
    api.functional.discussionboard.moderators.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { revoked_at: newRevokedAt } as IDiscussionboardModerator.IUpdate,
    }),
  );

  // 7. 비관리자 권한으로 업데이트 시도(권한 오류 반환) - 실제 지원 시 구현
  // (API에서 명시적 사용자 권한 스위칭 지원 시 해당 시나리오 추가)
}

