/**
 * Test soft-deleting a board tag entity as an admin, including idempotency, non-existent deletion, and indirect reference validation.
 *
 * Business context:
 * - Board tags are assigned for search/discovery on discussion boards.
 * - Only admins can manage these tags; deletions are soft (logical rather than physical).
 * - It is required to ensure the tag can be deleted, does not allow repeat-delete failures, and invalid-UUID handling.
 *
 * Steps:
 * 1. Create a board tag by POST /discussionboard/boardTags (dependency for delete)
 * 2. Delete that tag (soft delete) via DELETE /discussionboard/boardTags/{id}
 * 3. Confirm that the response returns the tag info (note: as 'any' type, cannot assert .deleted field)
 * 4. Attempt to delete again — verify error or correct idempotency handling
 * 5. Attempt to delete using a random non-existent UUID — expect error/exception
 * 6. (Skipping validation against listing/analytics — API not available)
 *
 * Edge cases:
 * - Rapid double-delete
 * - Deletion with invalid UUID
 */
export async function test_api_discussionboard_boardTags_test_soft_delete_board_tag_and_deletion_of_nonexistent_tag(
  connection: api.IConnection,
) {
  // 1. Create a new board tag (dependency)
  const created: IdiscussionboardBoardTags = await api.functional.discussionboard.boardTags.post(connection, {
    body: typia.random<IdiscussionboardBoardTags.ICreate>(),
  });
  typia.assert(created);

  // 2. Perform soft-delete using its id
  const erased: IdiscussionboardBoardTags = await api.functional.discussionboard.boardTags.eraseById(connection, {
    id: created.id,
  });
  typia.assert(erased);
