import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate an admin can update a channel's metadata fields (name, description, visibility) and ensure only mutable fields change.
 *
 * This E2E test covers:
 * 1. Creating an admin account for proper authorized access.
 * 2. Creating a discussion board channel as the target.
 * 3. Updating channel name, description, and visibility as admin (toggle public/hidden).
 * 4. Verifying only expected fields change in the updated channel; unchanged fields are stable.
 * 5. Toggling visibility back and changing name again to confirm round-trip mutation.
 * 6. Attempting to update to a duplicate name (should fail if unique check is present).
 *
 * Steps in detail:
 * - Admin registers and is authenticated for privileged mutation
 * - Channel is created
 * - First update assigns new name/description, toggles visibility (public<->hidden)
 * - Result is checked for updated values and ID stability
 * - Second update changes name again and reverts visibility
 * - Edge case: try duplicate name (expect error)
 */
export async function test_api_discussionboard_test_update_channel_metadata_and_visibility_as_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a channel to mutate
  const origChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(origChannel);

  // 3. Update the channel's name, description, and visibility
  const newName = RandomGenerator.alphabets(8) + "-changed";
  const newDescription = RandomGenerator.paragraph()();
  const origVisible = origChannel.visible;
  const toggledVisible = origVisible === true ? false : true;
  const updated1 = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName,
      description: newDescription,
      visible: toggledVisible,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(updated1);

  // 4. Assert that changes took effect and stable fields remain
  TestValidator.notEquals("name updated")(updated1.name)(origChannel.name);
  TestValidator.equals("name accurately set")(updated1.name)(newName);
  TestValidator.notEquals("description updated")(updated1.description)(origChannel.description);
  TestValidator.equals("description accurately set")(updated1.description)(newDescription);
  TestValidator.notEquals("visibility toggled")(updated1.visible)(origVisible);
  TestValidator.equals("visibility value")(updated1.visible)(toggledVisible);
  TestValidator.equals("ID unchanged")(updated1.id)(origChannel.id);

  // 5. Update again: new name, revert visibility to original
  const newName2 = RandomGenerator.alphabets(8) + "-twice";
  const reverted = await api.functional.discussionboard.channels.putById(connection, {
    id: origChannel.id,
    body: {
      name: newName2,
      visible: origVisible,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
  typia.assert(reverted);
  TestValidator.equals("name updated again")(reverted.name)(newName2);
  TestValidator.equals("visibility reverted")(reverted.visible)(origVisible);
  TestValidator.equals("ID still unchanged")(reverted.id)(origChannel.id);

  // 6. Duplicate name edge case
  const otherChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(otherChannel);
  await TestValidator.error("duplicate name should be rejected")(async () => {
    await api.functional.discussionboard.channels.putById(connection, {
      id: origChannel.id,
      body: { name: otherChannel.name } satisfies IDiscussionboardChannel.IUpdate,
    });
  });
}

