/**
 * Test successful update of section properties (name, description, position, visibility) as admin.
 *
 * This test validates that an admin user can successfully update an existing board section's core fields and that changes are reflected in the returned entity.
 * A valid section is first created, associated with a channel. The section is then updated with a new unique name (to test name uniqueness enforcement), description, position, and visibility. After the update, the returned entity is checked to ensure all new values are present. For completeness, a follow-up update could also check edge behavior (e.g., toggling visibility), but this test focuses on normal editing workflow.
 *
 * Steps:
 * 1. Create a channel (dependency).
 * 2. Create a section associated with that channel (dependency).
 * 3. Prepare new values for the update (all modifiable fields, including a unique name).
 * 4. Update the section by its ID as admin.
 * 5. Assert the API call succeeds and returned data reflects the requested changes.
 */
export async function test_api_discussionboard_test_update_section_success_with_admin(
  connection: api.IConnection,
) {
  // 1. Create a channel (dependency)
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 2. Create a section in the channel (dependency)
  const originalSection = await api.functional.discussionboard.sections.post(connection, {
    body: {
      ...typia.random<IDiscussionboardSection.ICreate>(),
      channel_id: channel.id, // ensure the correct channel id on creation
    },
  });
  typia.assert(originalSection);

  // 3. Prepare new update values (must be unique name within channel)
  const newSectionName = `${originalSection.name}_updated_${Date.now()}`;
  const newDescription = `Updated desc ${RandomGenerator.paragraph()()}`;
  const newPosition = (typeof originalSection.position === "number" ? originalSection.position + 1 : 1);
  const newVisible = originalSection.visible === true ? false : true;

  // 4. Update the section by id as admin
  const updatedSection = await api.functional.discussionboard.sections.putById(connection, {
    id: originalSection.id,
    body: {
      name: newSectionName,
      description: newDescription,
      position: newPosition,
      visible: newVisible,
    },
  });
  typia.assert(updatedSection);

  // 5. Assert that the updated section matches the new values
  TestValidator.equals("updated name")(updatedSection.name)(newSectionName);
  TestValidator.equals("updated description")(updatedSection.description)(newDescription);
  TestValidator.equals("updated position")(updatedSection.position)(newPosition);
  TestValidator.equals("updated visibility")(updatedSection.visible)(newVisible);

  // (Optional) Assert the channel id did not change
  TestValidator.equals("channel id not changed")(updatedSection.channel_id)(originalSection.channel_id);
}

