  const invalidLikePayload = { post_id: typia.random<string>() } satisfies Idiscussionboard_postLikes.ICreate;
  await TestValidator.error("Non-existent post like should fail")(
    () => api.functional.discussionboard.postLikes.post(connection, { body: invalidLikePayload })
  );

  // 6. 삭제/잠금 게시글 시도: 관련 openAPI/SDK endpoint 공개시 대응 예정
}

