/**
 * Validate that duplicate likes by the same member on the same post are blocked.
 *
 * This test covers the scenario where a member attempts to like the same post twice in succession.
 * The API must enforce a uniqueness constraint, so that the first like is allowed and the second attempt
 * results in a 409 Conflict error. Only one like should be associated with the post and member combination.
 *
 * Business context:
 * - A member can only like a post once (no duplicates).
 * - Ensures database-level uniqueness for (member_id, post_id) pairs.
 * - Duplicate likes must be rejected for analytics and correct UX.
 *
 * Steps:
 * 1. Create a member for the test's actions.
 * 2. Create a post (potentially with member as author, though DTO doesn't enforce this link).
 * 3. Perform a first 'like' from the member to the post (must succeed).
 * 4. Immediately attempt to like the same post again from the same member (must yield a 409 error).
 * 5. Optionally, check only one like exists (ignored as no retrieval endpoint is exposed).
 */
export async function test_api_discussionboard_postLikes_test_create_post_like_duplicate_error(
  connection: api.IConnection,
) {
  // 1. Create a new member for like operations
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. First like should succeed
  const likePayload = {
    member_id: member.id,
    post_id: post.id,
  } satisfies Idiscussionboard_postLikes.ICreate;
  const firstLike = await api.functional.discussionboard.postLikes.post(connection, {
    body: likePayload,
  });
  typia.assert(firstLike);

  // 4. Duplicate like must result in error
  await TestValidator.error("Duplicate like should return 409 conflict")(
    async () => {
      await api.functional.discussionboard.postLikes.post(connection, {
        body: likePayload,
      });
    },
  );
}

