  await TestValidator.error("invalid pagination expects error")(() =>
    api.functional.discussionboard.settings.patch(connection, {
      body: { page: -1, limit: "huge" },
    })
  );

  // 5. As non-admin, switch account (simulate) and expect RBAC forbidden error
  // (Assume 'connection' can be switched to non-admin; if not, conceptually outline here)
  // await switchToNonAdmin(connection);
  await TestValidator.error("non-admin access forbidden")(() =>
    api.functional.discussionboard.settings.patch(connection, {
      body: {},
    })
  );
}

