/**
 * Validate system enforcement of anti-duplicate reporting policy within a time window.
 *
 * This test ensures that a single member cannot file multiple reports against the same target entity (post or comment) in rapid succession where such action is restricted by platform policy. It also validates that other members are not blocked from reporting the same content and that duplicate prevention is scope-limited (does not block different targets).
 *
 * Steps:
 * 1. Create a member (MemberA) who will perform initial and duplicate reports.
 * 2. Create another member (MemberB) to test unrestricted reporting.
 * 3. Create a post (PostX) which will be the reporting target.
 * 4. MemberA files a report on PostX successfully.
 * 5. MemberA attempts to report PostX again within the restricted window – expect a 409 Conflict or validation error.
 * 6. MemberB files a report on PostX successfully without restriction.
 * 7. MemberA files a report on a different, unrelated post (PostY) – should succeed, confirming the restriction is only for same target.
 */
export async function test_api_discussionboard_test_prevent_duplicate_report_within_window(
  connection: api.IConnection,
) {
  // 1. Create MemberA
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
