    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberA.id,
    targetPostId: postX.id,
  };
  const reportA1 = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyA1,
  });
