  TestValidator.equals("report links to correct member")(
    reportA1.reporterId
  )(memberA.id);
  TestValidator.equals("report links to correct post")(
    reportA1.targetPostId
  )(postX.id);

  // 5. MemberA attempts to report PostX again (should fail with duplicate error)
  await TestValidator.error("Duplicate report by MemberA on same PostX within window should fail")(
    async () => {
      await api.functional.discussionboard.reports.post(connection, {
        body: {
          ...typia.random<IDiscussionboardReport.ICreate>(),
          reporterId: memberA.id,
          targetPostId: postX.id,
        },
      });
    },
  );

  // 6. MemberB files a report on PostX (should be allowed)
  const reportBodyB = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberB.id,
    targetPostId: postX.id,
  };
  const reportB = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyB,
  });
  typia.assert(reportB);
  TestValidator.equals("report by B links to correct member")(
    reportB.reporterId
  )(memberB.id);
  TestValidator.equals("report by B links to correct post")(
    reportB.targetPostId
  )(postX.id);

  // 7. MemberA files a report on a different post (PostY)
  const postY = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(postY);
  const reportBodyA2 = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberA.id,
    targetPostId: postY.id,
  };
  const reportA2 = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyA2,
  });
  typia.assert(reportA2);
  TestValidator.equals("report by A links to correct member for new post")(
    reportA2.reporterId
  )(memberA.id);
  TestValidator.equals("report by A links to correct (other) post")(
    reportA2.targetPostId
  )(postY.id);
}

