 * 4. Update the report as privileged actor (reason and details)
 * 5. Assert updates took effect
 * 6. Attempt to update non-existent report (should error)
 * 7. Attempt to update a "resolved" report (should error)
 * 8. Attempt to update forbidden fields (reporter, target) and verify error or ignore
 * 9. Simulate forbidden update as unauthorized user (skipped if connection context can't be altered)
 *
 * Business context: Only privileged roles (moderator/admin) should be able to update a report; audit trails and error conditions must be enforced.
 */
export async function test_api_discussionboard_test_update_report_fields_by_moderator(
  connection: api.IConnection,
) {
  // 1. Register a discussionboard member (normal user)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a board post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. File a report for that post (as the same user)
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>(),
  });
  typia.assert(report);

