  await TestValidator.error("invalid uri/mimeType rejected")(() =>
    api.functional.discussionboard.postAttachments.post(connection, {
      body: invalidMetadataInput as any,
    })
  );

  // 7. Attempt permission case: memberB tries to attach to memberA's post (should fail if permissions enforced)
  const wrongOwnerInput = { ...attachmentInput, memberId: memberB.id };
  await TestValidator.error("permission denied for non-owner")(() =>
    api.functional.discussionboard.postAttachments.post(connection, {
      body: wrongOwnerInput as any,
