 *
 * - 첨부파일의 소유 회원은 삭제를 성공적으로 할 수 있어야 합니다.
 * - 일반 타 회원(비소유자)의 삭제 시도는 권한 오류로 실패해야 합니다.
 * - 운영진/관리자 계정은 첨부파일을 정상적으로 삭제할 수 있어야 합니다.
 * - 이미 삭제된 첨부파일/존재하지 않는 ID 삭제 시도는 적절하게 오류를 반환해야 합니다.
 * - (가능하면) 감사 로그가 정상적으로 생성되는지도 검증합니다.
 *
 * [Test Steps]
 * 1. 첨부파일 소유 회원, 일반 회원, 운영진 계정 생성
 * 2. 소유 회원으로 게시글 및 첨부파일 등록
 * 3. 소유자 본인의 삭제 시도 → 성공
 * 4. 일반 회원이 삭제 시도 → 권한 오류 발생
 * 5. 운영진이 첨부파일 등록 및 삭제 → 성공
 * 6. 이미 삭제된 파일/존재하지 않는 ID 삭제 시도 → 적절한 오류 반환
 * 7. (감사 로그 검증 API 있다면 호출)
 */
export async function test_api_discussionboard_test_delete_post_attachment_as_owner_and_admin_with_various_outcomes(
  connection: api.IConnection,
) {
  // 1. 첨부파일 소유 회원, 일반 회원, 운영진 회원 생성
  const ownerMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(ownerMember);

  const anotherMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(anotherMember);

  const adminMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(adminMember);

  // 2. owner 계정 context (소유자 회원으로 게시글/첨부 등록)
  // ※ 실제 시스템에서는 로그인/토큰 context 전환 필요
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  const attachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(attachment);

  // 3. 첨부파일 소유자 본인이 삭제 시도 (성공해야 함)
  const deleted1 = await api.functional.discussionboard.postAttachments.eraseById(connection, {
    id: attachment.id,
  });
  typia.assert(deleted1);

  // 4. 비소유자(일반회원) context에서 삭제 시도 (권한 오류 발생)
  // ※ 실제 시스템에서는 anotherMember로 로그인 context 전환 필요
  await TestValidator.error("비소유자에 의한 첨부파일 삭제는 오류가 발생해야 함")(
    async () => {
      await api.functional.discussionboard.postAttachments.eraseById(connection, {
        id: attachment.id,
      });
    },
  );

  // 5. 운영진 context에서 첨부파일 새로 등록 후 삭제 (성공)
  // ※ 운영진 전용 context(login) 필요
  const adminAttachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(adminAttachment);
  const deleted2 = await api.functional.discussionboard.postAttachments.eraseById(connection, {
    id: adminAttachment.id,
  });
  typia.assert(deleted2);

  // 6. 이미 삭제된 파일/존재하지 않는 ID 재삭제 시도 (적절한 오류)
  await TestValidator.error("이미 삭제된 파일 재삭제 시 오류 발생해야 함")(
    async () => {
      await api.functional.discussionboard.postAttachments.eraseById(connection, {
        id: attachment.id,
      });
    },
  );

  await TestValidator.error("존재하지 않는 첨부파일 아이디는 오류 반환해야 함")(
    async () => {
      await api.functional.discussionboard.postAttachments.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 7. 감사 로그 등 부가 검증은 관련 API 있으면 추가 구현
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IPageDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardThread";

/**
 * Test searching and paginating discussion threads by title keyword.
 *
 * Scenario:
 * 1. Register a new discussion board member.
 * 2. Create a discussion board.
 * 3. As the member, create at least two threads on the board: one with a unique keyword in the title, one without.
 * 4. Search for threads using the unique keyword — verify only the matching thread is returned and pagination info reflects correct total/count.
 * 5. Search using a non-existent keyword — verify empty results.
 * 6. Search with a high page number that would skip available results — verify empty results for that page.
 */
export async function test_api_discussionboard_test_list_threads_with_title_search_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Register member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // Step 2: Create board
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board);

  // Step 3: Create two threads with distinct titles (one including a unique keyword)
  const uniqueKeyword = "UniqueKeyword_" + RandomGenerator.alphabets(6);
  const otherTitle = "General Thread Title " + RandomGenerator.alphabets(6);

  const threadWithKeyword = await api.functional.discussionboard.threads.post(
    connection,
    {
      body: {
        ...typia.random<IDiscussionboardThread.ICreate>(),
        board_id: board.id,
        title: `Discussion about ${uniqueKeyword}`,
      },
    },
  );
  typia.assert(threadWithKeyword);

  const threadWithoutKeyword = await api.functional.discussionboard.threads.post(
    connection,
    {
      body: {
        ...typia.random<IDiscussionboardThread.ICreate>(),
        board_id: board.id,
        title: otherTitle,
      },
    },
  );
  typia.assert(threadWithoutKeyword);

  // Step 4: Search threads by unique keyword (should only find one)
  const pageResult = await api.functional.discussionboard.threads.patch(connection, {
    body: {
      ...typia.random<IDiscussionboardThread.IRequest>(),
      board_id: board.id,
      title: uniqueKeyword,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageResult);
  TestValidator.equals("Should find exactly one thread with keyword")(pageResult.data.length)(1);
  TestValidator.equals("Thread returned must have matching title")(pageResult.data[0].title.includes(uniqueKeyword))(true);

  // Step 5: Search for a non-existent title keyword (should return no results)
  const pageResultEmpty = await api.functional.discussionboard.threads.patch(connection, {
    body: {
      ...typia.random<IDiscussionboardThread.IRequest>(),
      board_id: board.id,
      title: "nonexistentkeyword__" + RandomGenerator.alphabets(6),
      page: 1,
      limit: 10,
    },
  });
  typia.assert(pageResultEmpty);
  TestValidator.equals("Should return zero results for non-existent keyword")(pageResultEmpty.data.length)(0);

  // Step 6: Paginate with out-of-range page (should return zero results)
  const pageResult2 = await api.functional.discussionboard.threads.patch(connection, {
    body: {
      ...typia.random<IDiscussionboardThread.IRequest>(),
      board_id: board.id,
      page: 100,
      limit: 10,
    },
  });
  typia.assert(pageResult2);
  TestValidator.equals("Should return zero results for high page number")(pageResult2.data.length)(0);
}

