import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardSearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSearchHistory";

/**
 * 인증된 멤버의 검색 내역 생성 기능 E2E 테스트
 *
 * 플랫폼 discussionboard_members에 회원 가입 → 이 계정으로 discussionboard_searchHistories에 검색 내역 POST →
 * 실제로 기록이 잘 생성되는지, 필수 정보가 응답으로 포함되는지, 그리고 인증 없는 경우 생성 시도를 하면 거부되는지 검증합니다.
 *
 * [테스트 흐름]
 * 1. 신규 멤버 계정 가입
 * 2. 이 계정(즉 로그인/인증 세션)에서 검색 내역 신규 생성
 * 3. 생성 결과가 정상 타입이고, 오류 없이 기록됨을 typia.assert로 확인
 * 4. 인증 없는 세션(Authorization 제거)에서 같은 요청 시도 → 권한 에러 발생 확인
 * (any 타입 한계로 상세 property 비교는 불가, 타입 보장만 수행)
 */
export async function test_api_discussionboard_test_create_search_history_entry_for_authenticated_member(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 가입
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 검색 내역 생성 (인증 상태)
