import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfigurations } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfigurations";

/**
 * Test creating a new configuration for the discussion board with unique and duplicate keys.
 *
 * This E2E test validates that an admin can successfully create a configuration record with all required fields, and that the system properly enforces uniqueness for config_key. It also asserts system rejection for missing required fields or invalid value_type, ensuring robust validation against schema and business rules.
 *
 * Steps:
 * 1. Create a configuration with valid config_key, config_value, value_type, and description.
 *    - Confirm successful creation (fields match input).
 * 2. Attempt to create another configuration with the same config_key.
 *    - Confirm the system rejects with an error (conflict or validation error).
 * 3. Attempt creation missing the required config_key field.
 *    - Expect schema validation failure.
 * 4. Attempt creation with an invalid value_type.
 *    - Expect server-side validation failure.
 */
export async function test_api_discussionboard_test_create_configuration_with_unique_and_duplicate_key(
  connection: api.IConnection,
) {
  // 1. Create valid configuration
  const configKey = RandomGenerator.alphaNumeric(12);
  const validCreate = {
    config_key: configKey,
    config_value: "true",
    value_type: "boolean",
    description: RandomGenerator.paragraph()(1),
  };
  const created = await api.functional.discussionboard.configurations.post(connection, { body: validCreate });
  typia.assert(created);
  TestValidator.equals("config_key matches")(created.config_key)(configKey);
  TestValidator.equals("value_type matches")(created.value_type)("boolean");

  // 2. Attempt duplicate config_key
  await TestValidator.error("duplicate config_key should fail")(async () => {
    await api.functional.discussionboard.configurations.post(connection, { body: validCreate });
  });

  // 3. Attempt creation missing required config_key
  const missingKey = { ...validCreate };
  delete missingKey.config_key;
  await TestValidator.error("missing config_key should fail")(async () => {
    await api.functional.discussionboard.configurations.post(connection, { body: missingKey as any });
  });

  // 4. Attempt creation with invalid value_type
  const invalidValueType = { ...validCreate, value_type: "unsupported_type" };
  await TestValidator.error("invalid value_type should fail")(async () => {
    await api.functional.discussionboard.configurations.post(connection, { body: invalidValueType as any });
  });
}

