import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postDislikes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postDislikes";
import type { IPageIdiscussionboard_postDislikes } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_postDislikes";

/**
 * Comprehensive E2E test for listing discussion board post dislikes with complex filtering and pagination.
 *
 * Business scenario: Moderators and analytics roles need to filter post dislikes by member, post, and date range for investigation and reporting. Test includes combinations of filters and paginated queries, as well as error paths.
 *
 * Steps:
 * 1. Register 3 member accounts
 * 2. For each member, create 2 posts (total 6 posts)
 * 3. Members add dislikes to various posts (per the test matrix)
 * 4. Query dislikes via various filter and paging cases, valid and invalid
 *
 * All critical API/model assertions are validated. Error handling for invalid queries is included.
 */
export async function test_api_discussionboard_postDislikes_test_list_post_dislikes_with_various_filters(connection: api.IConnection) {
  // 1. Register 3 members
  const members: IDiscussionboardMember[] = await Promise.all(ArrayUtil.repeat(3)(async () => {
    const m = await api.functional.discussionboard.members.post(connection, {
      body: typia.random<IDiscussionboardMember.ICreate>(),
    });
    typia.assert(m);
    return m;
  }));

  // 2. Create 2 posts per member (total 6 posts, preserving author refs)
  const posts: IDiscussionboardPost[] = [];
  for (const m of members) {
    for (let i = 0; i < 2; ++i) {
      const post = await api.functional.discussionboard.posts.post(connection, {
        body: { ...typia.random<IDiscussionboardPost.ICreate>(), author_id: m.id },
      });
      typia.assert(post);
      posts.push(post);
    }
  }

  // 3. Add dislikes as described in matrix
  //    Matrix: A dislikes 2,4,5; B dislikes 1,3,6; C dislikes 1,5
  const dislikeMatrix = [
    { member: members[0], postIndices: [1, 3, 4] },
    { member: members[1], postIndices: [0, 2, 5] },
    { member: members[2], postIndices: [0, 4] },
  ];
  type DislikeRecord = { member_id: string; post_id: string; created_at: string };
  const dislikes: DislikeRecord[] = [];
  for (const row of dislikeMatrix) {
    for (const idx of row.postIndices) {
      const dislike = await api.functional.discussionboard.postDislikes.post(connection, {
        body: { member_id: row.member.id, post_id: posts[idx].id },
      });
      typia.assert(dislike);
      dislikes.push({
        member_id: row.member.id,
        post_id: posts[idx].id,
        created_at: dislike.created_at,
      });
    }
  }

  // 4a. Filter: by member_id (validate all belong to that member, count matches)
  const resMemberA = await api.functional.discussionboard.postDislikes.patch(connection, {
    body: { member_id: members[0].id },
  });
  typia.assert(resMemberA);
  TestValidator.predicate("all dislikes are by memberA")(resMemberA.data.every(d => d.member_id === members[0].id));
  TestValidator.equals("memberA count")(resMemberA.data.length)(3);

  // 4b. Filter: by post_id (validate returned dislikes match expected members)
  const resPost1 = await api.functional.discussionboard.postDislikes.patch(connection, {
    body: { post_id: posts[0].id },
  });
  typia.assert(resPost1);
  const expectedMembers = dislikes.filter(d => d.post_id === posts[0].id).map(d => d.member_id).sort();
  TestValidator.equals("post1 disliked by")(resPost1.data.map(d => d.member_id).sort())(expectedMembers);

  // 4c. Filter: by date range (grab first 2 dislikes by time)
  const sortedByTime = [...dislikes].sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
  const from = sortedByTime[0].created_at;
  const to = sortedByTime[1].created_at;
  const resDateRange = await api.functional.discussionboard.postDislikes.patch(connection, {
    body: { created_from: from, created_to: to },
  });
  typia.assert(resDateRange);
  const idsInRange = dislikes.filter(d => d.created_at >= from && d.created_at <= to).map(d => d.post_id).sort();
  TestValidator.equals("date range posts")(resDateRange.data.map(d => d.post_id).sort())(idsInRange);

