import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Test administrative compliance deletion of a post edit history record.
 *
 * This test validates that only admin users can delete post edit history records for compliance purposes, and that correct audit and permission enforcement occurs. It also verifies proper error handling for duplicate/illegal deletions.
 *
 * Steps:
 * 1. Register a normal member.
 * 2. Register an admin user.
 * 3. Member creates a post.
 * 4. Member edits the post to trigger an edit history record.
 * 5. Attempt to delete the edit history as non-admin (should fail with permission error).
 * 6. Delete the edit history as admin (should succeed).
 * 7. Attempt to retrieve the deleted edit history (should fail/not found; omitted if no API).
 * 8. Attempt to delete the same or non-existent history entry again (should result in correct error or idempotent response).
 * 9. Confirm appropriate audit trail/log events if retrievable via API (cannot implement if audit API not available).
 */
export async function test_api_discussionboard_test_delete_post_edit_history_entry_admin_compliance_only(
  connection: api.IConnection,
) {
  // 1. Register a normal member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Register an admin user
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 3. Member creates a post
  const memberPost = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(memberPost);

  // 4. Member edits the post to create an edit history entry
  const updatedPost = await api.functional.discussionboard.posts.putById(connection, {
    id: memberPost.id,
    body: typia.random<IDiscussionboardPost.IUpdate>(),
  });
  typia.assert(updatedPost);

  // Note: There is no API to directly fetch edit history IDs, so we will use a random UUID for demonstration.
  // In actual production, this should be the real ID generated by post edit history mechanism.
  const editHistoryId = typia.random<string & tags.Format<'uuid'>>();

  // 5. Attempt deletion as a non-admin (should fail with permission error)
