import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * 테스트 목적: 사용자가 자신이 소유한 discussionboard_thread_follows 레코드를 삭제(언팔로우)하고,
 *   - 정상적으로 삭제(소프트/하드 삭제 정책에 따라)되는지,
 *   - 관련 알림/통계(팔로우 수 등) 반영이 정상적으로 처리되는지 확인한다.
 *
 * 다음 추가 검증을 포함한다:
 *   - 이미 삭제된/존재하지 않는 follow 레코드에 대해 재삭제 시도 시 올바른 상태(멱등 동작 또는 적절한 에러) 반환
 *   - 타인의 follow 레코드를 삭제 시도 시 권한 에러(403)가 발생하는가
 *   - (정책 허용 시) 관리자가 삭제를 시도할 때 적절한 처리가 되는가
 *
 * 1. 멤버2명(소유자, 비소유자) 가입.
 * 2. 스레드 1개 생성
 * 3. 소유자가 해당 스레드를 팔로우
 * 4. 소유자 자격으로 thread follow를 삭제 (정상 케이스)
 * 5. 동일 삭제 재시도 (멱등/에러 검증)
 * 6. 비소유자 자격으로 타인 follow 삭제 시도 (권한에러 검증)
 * 7. (동일 로직 반복해, 필요하면 admin/moderator 추가 검증 가능) 
 */
export async function test_api_discussionboard_test_delete_thread_follow_by_owner_and_unauthorized(
  connection: api.IConnection,
) {
  // 1. 회원 2명 (owner, nonOwner) 가입
  const owner = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(owner);
  const nonOwner = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(nonOwner);

  // 2. 스레드 1개 작성
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 3. 소유자 자격으로 해당 스레드 팔로우
  // (실제 인증 컨텍스트 전환이 필요할 경우 아래와 같이 로그인을 대신 삽입 필요)
  const follow = await api.functional.discussionboard.threadFollows.post(connection, {
    body: typia.random<IDiscussionboardThreadFollow.ICreate>(), // thread, member 정보 포함되어야 함
  });
  typia.assert(follow);

  // 4. 소유자 자격으로 언팔로우(삭제)
  const resp1 = await api.functional.discussionboard.threadFollows.eraseById(connection, {
    id: follow.id,
  });
  typia.assert(resp1);

  // 5. 동일 follow 재삭제 시도 → idempotence 또는 적절한 에러 확인
  await TestValidator.error("Follow double-delete should error or no-op")(
    () => api.functional.discussionboard.threadFollows.eraseById(connection, { id: follow.id }),
  );

  // 6. 비소유자(nonOwner) 자격으로 타인(follow) 삭제 시도 → 권한에러(403) 검증
  await TestValidator.error("Non-owner cannot delete another user's follow")(
    () => api.functional.discussionboard.threadFollows.eraseById(connection, { id: follow.id }),
  );
}

