import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostAttachment";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * 다양한 회원 권한 시나리오에서 게시글 첨부파일 삭제 API의 정상 동작, 권한 오류, 예외 처리를 검증합니다.
 *
 * - 첨부파일의 소유 회원은 삭제를 성공적으로 할 수 있어야 합니다.
 * - 일반 타 회원(비소유자)의 삭제 시도는 권한 오류로 실패해야 합니다.
 * - 운영진/관리자 계정은 첨부파일을 정상적으로 삭제할 수 있어야 합니다.
 * - 이미 삭제된 첨부파일/존재하지 않는 ID 삭제 시도는 적절하게 오류를 반환해야 합니다.
 * - (가능하면) 감사 로그가 정상적으로 생성되는지도 검증합니다.
 *
 * [Test Steps]
 * 1. 첨부파일 소유 회원, 일반 회원, 운영진 계정 생성
 * 2. 소유 회원으로 게시글 및 첨부파일 등록
 * 3. 소유자 본인의 삭제 시도 → 성공
 * 4. 일반 회원이 삭제 시도 → 권한 오류 발생
 * 5. 운영진이 첨부파일 등록 및 삭제 → 성공
 * 6. 이미 삭제된 파일/존재하지 않는 ID 삭제 시도 → 적절한 오류 반환
 * 7. (감사 로그 검증 API 있다면 호출)
 */
export async function test_api_discussionboard_test_delete_post_attachment_as_owner_and_admin_with_various_outcomes(
  connection: api.IConnection,
) {
  // 1. 첨부파일 소유 회원, 일반 회원, 운영진 회원 생성
  const ownerMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(ownerMember);

  const anotherMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(anotherMember);

  const adminMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(adminMember);

  // 2. owner 계정 context (소유자 회원으로 게시글/첨부 등록)
  // ※ 실제 시스템에서는 로그인/토큰 context 전환 필요
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  const attachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(attachment);

  // 3. 첨부파일 소유자 본인이 삭제 시도 (성공해야 함)
  const deleted1 = await api.functional.discussionboard.postAttachments.eraseById(connection, {
    id: attachment.id,
  });
  typia.assert(deleted1);

  // 4. 비소유자(일반회원) context에서 삭제 시도 (권한 오류 발생)
  // ※ 실제 시스템에서는 anotherMember로 로그인 context 전환 필요
  await TestValidator.error("비소유자에 의한 첨부파일 삭제는 오류가 발생해야 함")(
    async () => {
      await api.functional.discussionboard.postAttachments.eraseById(connection, {
        id: attachment.id,
      });
    },
  );

  // 5. 운영진 context에서 첨부파일 새로 등록 후 삭제 (성공)
  // ※ 운영진 전용 context(login) 필요
  const adminAttachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(adminAttachment);
  const deleted2 = await api.functional.discussionboard.postAttachments.eraseById(connection, {
    id: adminAttachment.id,
