import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * Validate creation of new settings entry in discussionboard_settings by an admin.
 *
 * This test ensures:
 * - Successful creation of a unique settings entry with all required fields provided.
 * - Audit fields (like timestamp) are properly set in the response.
 * - Error on missing required fields.
 * - Error on submitting a duplicate (setting_key, owner_type, owner_id/section_id) combination.
 * - Error if non-admin (or insufficient privilege) tries to create a setting.
 *
 * Steps:
 * 1. As admin, create a settings entry with unique key, value, owner_type and (if required) owner_id/section_id.
 * 2. Verify response includes the created entry with all details, including audit/timestamp field.
 * 3. Attempt to create with missing required fields and verify error response.
 * 4. Attempt to create same key/owner tuple as step 1 and verify error for duplicate.
 * 5. Attempt to create as non-admin and verify access denied or insufficient permission error.
 */
export async function test_api_discussionboard_test_create_setting_with_valid_unique_data_as_admin(
  connection: api.IConnection,
) {
  // 1. As admin, create unique settings entry with all required fields
  const setting_create: IDiscussionboardSettings.ICreate = typia.random<IDiscussionboardSettings.ICreate>();
  const created = await api.functional.discussionboard.settings.post(connection, {
    body: setting_create,
  });
  typia.assert(created);

  // 2. (Generic) Verify audit fields/creation timestamp if present in schema
  // Skipped since DTO is any, but would appear here.

  // 3. Check error on missing required fields
  await TestValidator.error("Missing required fields should fail")(async () => {
    await api.functional.discussionboard.settings.post(connection, {
      body: {}, // empty object simulates missing everything
    } as any);
  });

  // 4. Check error on duplicate creation (should fail for unique constraint)
  await TestValidator.error("Duplicate key/owner/owner_id should fail")(async () => {
    await api.functional.discussionboard.settings.post(connection, {
      body: setting_create,
    });
  });

  // 5. Check error when trying as non-admin (simulate by stripping Authorization)
  const unauthorized_connection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };
  await TestValidator.error("Non-admin access denied")(async () => {
    await api.functional.discussionboard.settings.post(unauthorized_connection, {
      body: typia.random<IDiscussionboardSettings.ICreate>(),
    });
  });
}

