import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostTag";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Test the deletion of a post tag assignment by id, covering business rules,
 * RBAC, and edge cases.
 *
 * This E2E test simulates the workflow for removing a tag assignment from a
 * discussion board post. It covers both normal and error/edge cases,
 * including:
 *
 * 1. Create a new post via POST /discussionboard/posts
 * 2. Assign a tag to the post via POST /discussionboard/postTags
 * 3. Delete the tag assignment by ID via DELETE /discussionboard/postTags/{id}
 * 4. Attempt to delete the same assignment again (should return an error or be idempotent)
 * 5. Simulate an unauthorized deletion attempt (should be denied)
 * 6. Try deleting with a nonexistent or invalid tag-assignment ID (should error)
 * 7. (Skipped, as not implementable): Confirm the tag is not present via list/search/get
 *
 * Preconditions: No need for explicit login or user switching functions, as only the
 * basic connection object is available; RBAC simulation for step 5 is done by clearing headers.
 * All API usage follows available endpoints and provided DTO/type definitions.
 *
 * This ensures correct deletion, error handling, permission boundaries, and correct
 * enforcement of business rules around tag assignment deletion.
 */
export async function test_api_discussionboard_test_delete_post_tag_assignment_by_id_with_rbac_and_edge_cases(
  connection: api.IConnection,
) {
  // 1. Create a new post (as a presumed authorized user)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 2. Assign a tag to the post
  const tagAssignment = await api.functional.discussionboard.postTags.post(connection, {
    body: typia.random<IDiscussionboardPostTag.ICreate>(),
  });
  typia.assert(tagAssignment);

  // 3. Delete the tag assignment by its ID
  const deletionResult = await api.functional.discussionboard.postTags.eraseById(connection, {
    id: tagAssignment.id,
  });
  typia.assert(deletionResult);

  // 4. Attempt to delete the same tag assignment again (should error or be idempotent)
  await TestValidator.error("Cannot delete same tag assignment twice")(
    () => api.functional.discussionboard.postTags.eraseById(connection, { id: tagAssignment.id })
  );

  // 5. Simulate unauthorized deletion attempt (clear out headers in connection)
  const unauthorizedConn = { ...connection, headers: {} };
  await TestValidator.error("Unauthorized delete attempt fails")(
    () => api.functional.discussionboard.postTags.eraseById(unauthorizedConn, { id: tagAssignment.id })
  );

  // 6. Try deleting a nonexistent/invalid tag-assignment ID
  await TestValidator.error("Delete with nonexistent ID")(
    () => api.functional.discussionboard.postTags.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );

  // 7. Skipped: Would check that the tag is no longer present on the post after deletion, if such API existed.
}

