import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IPageIDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardComment";

/**
 * Test retrieving a paginated, filtered list of comments from the discussion board.
 *
 * This test verifies:
 * 1. Filtering correctness by post ID, author ID, parent ID
 * 2. Pagination logic correctness
 * 3. Error handling for invalid params
 * 4. Permissions/soft-delete/flagged status—cannot be tested here due to API constraints, so omitted
 *
 * Steps:
 * 1. Register several members (authors for comments)
 * 2. Create a post as the parent for comments
 * 3. Create a comment hierarchy:
 *    - Multiple root comments (no parent)
 *    - Several replies (with parent_id)
 *    - Each authored by a different member
 * 4. List/filter comments: by post, by author, by parent
 * 5. Paginate: page and size edge testing
 * 6. Test invalid parameter error (e.g., negative page)
 *
 * Note: Since no API for soft-delete/flag/role exists, corresponding tests are omitted.
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register members (authors for comments)
  const members = await Promise.all([
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
  ]);
  typia.assert(members[0]);
  typia.assert(members[1]);
  typia.assert(members[2]);

  // 2. Create a post to serve as a comment parent
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. Create a comment hierarchy:
  const rootComments = await Promise.all([
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[0].id, parent_id: null },
    }),
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[1].id, parent_id: null },
    }),
  ]);
  typia.assert(rootComments[0]);
  typia.assert(rootComments[1]);
  // Replies to root
  const replies = await Promise.all([
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[2].id, parent_id: rootComments[0].id },
    }),
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[1].id, parent_id: rootComments[0].id },
    }),
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[0].id, parent_id: rootComments[1].id },
    }),
  ]);
  replies.forEach(typia.assert);

  // 4. List by post
  const byPostList = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byPostList);

  // 5. List by author_id
  const byAuthorList = await api.functional.discussionboard.comments.patch(connection, {
    body: { author_id: members[1].id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byAuthorList);
  byAuthorList.data.forEach(c => {
    TestValidator.equals("author match")(c.author_id)(members[1].id);
  });

  // 6. List by parent_id (all replies to one root)
  const byParentList = await api.functional.discussionboard.comments.patch(connection, {
    body: { parent_id: rootComments[0].id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byParentList);
  byParentList.data.forEach(c => {
    TestValidator.equals("parent match")(c.parent_id)(rootComments[0].id);
  });

  // 7. Pagination (small size, multiple pages)
  const pagedList1 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 1, size: 2 } as IDiscussionboardComment.IRequest,
  });
  typia.assert(pagedList1);
  TestValidator.predicate("page1 limited")(pagedList1.data.length <= 2);

  // Next page
  const pagedList2 = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 2, size: 2 } as IDiscussionboardComment.IRequest,
  });
  typia.assert(pagedList2);
  TestValidator.predicate("page2 limited")(pagedList2.data.length <= 2);
  if (pagedList1.data.length > 0 && pagedList2.data.length > 0) {
    const ids1 = pagedList1.data.map(x => x.id);
    const ids2 = pagedList2.data.map(x => x.id);
    TestValidator.predicate("no overlap")(ids1.every(id => !ids2.includes(id)));
  }

  // 8. Invalid params (negative page)
  await TestValidator.error("invalid page param")(async () => {
    await api.functional.discussionboard.comments.patch(connection, {
      body: { post_id: post.id, page: -1 } as IDiscussionboardComment.IRequest,
    });
  });

  // Soft-delete/flagged tests/permission are not validated here (no API support)
}

