import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * E2E tests updating a discussion board ban record.
 *
 * This function verifies all core update ban workflows and error handling:
 *  
 * 1. As admin/moderator, create a valid ban (prerequisite via POST)
 * 2. Update the ban with new values (expiry, rationale, type), as authorized user
 * 3. Confirm updates are reflected in response
 * 4. Attempt to update as unauthorized user (should be access denied)
 * 5. Attempt to update a non-existent ban (should be not found)
 *
 * Prerequisites: The POST /discussionboard/bans endpoint to create the original ban.
 *
 * Steps:
 * 1. Create a ban (via POST)
 * 2. As admin/mod, update the ban: PUT /discussionboard/bans/{id} with new expiry or rationale
 * 3. Assert updated fields were changed in result
 * 4. Switch to unauthorized context, attempt update (should fail with error)
 * 5. Attempt to update a random non-existent ID (should fail with not found)
 */
export async function test_api_discussionboard_test_update_ban_valid_and_permission_denied(connection: api.IConnection) {
  // 1. Create a ban as an authorized user
  const ban = await api.functional.discussionboard.bans.post(connection, {
    body: typia.random<IDiscussionboardBan.ICreate>(),
  });
  typia.assert(ban);

  // 2. Update the ban with new expiry/rationale/type as same authorized user
  const updateInput = typia.random<IDiscussionboardBan.IUpdate>();
  const updated = await api.functional.discussionboard.bans.putById(connection, {
    id: ban.id,
    body: updateInput,
  });
  typia.assert(updated);

  // (Validation: expect fields changed)
  // This is generic because type is 'any', so only check 'id' equality
  TestValidator.equals("ban id matches")(updated.id)(ban.id);

  // 3. Attempt update as unauthorized user
  // (Simulate unauth context by using connection with Authorization header removed)
  const unauthorizedConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("permission denied updating ban")(() => api.functional.discussionboard.bans.putById(unauthorizedConnection, {
    id: ban.id,
    body: typia.random<IDiscussionboardBan.IUpdate>(),
  }));

  // 4. Attempt update of a non-existent ban as authorized user
  await TestValidator.error("not found updating non-existent ban")(() => api.functional.discussionboard.bans.putById(connection, {
    id: typia.random<string & tags.Format<"uuid">>(),
    body: typia.random<IDiscussionboardBan.IUpdate>(),
  }));
}

