import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerationAction";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Validate creation of a warning record by an admin/moderator and cover all negative scenarios (validation, duplication, permission).
 *
 * This test ensures that:
 * 1. An admin or moderator can successfully create a warning with all required fields filled.
 * 2. Validation errors occur for missing required fields.
 * 3. Duplicate creation with same keys is rejected.
 * 4. Invalid member ID is rejected.
 * 5. Permissions are enforced: regular users cannot create warnings.
 *
 * Process:
 * 1. Create a member (target of warning).
 * 2. Create a moderation action for reference.
 * 3. As an authorized user (admin/mod), create a warning for that member and action. Assert success.
 * 4. Attempt to create with missing required fields — expect validation failure.
 * 5. Attempt to create a duplicate — expect rejection.
 * 6. Attempt with invalid member ID — expect validation failure.
 * 7. Attempt as a non-privileged user (if possible) — expect permission error.
 */
export async function test_api_discussionboard_test_create_warning_with_all_required_fields_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create member (warning target)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create moderation action for reference
  const action = await api.functional.discussionboard.moderationActions.post(connection, {
    body: typia.random<IDiscussionboardModerationAction.ICreate>(),
  });
  typia.assert(action);

  // 3. Successful warning creation as admin/moderator
  const warningInput: IDiscussionboardWarning.ICreate = typia.random<IDiscussionboardWarning.ICreate>();
  warningInput.memberId = member.id;
  warningInput.actionId = action.id;
  const warning = await api.functional.discussionboard.warnings.post(connection, {
    body: warningInput,
  });
  typia.assert(warning);

  // 4. Validation error: missing required field (simulate by deleting one)
  await TestValidator.error("validation error missing field")(async () => {
    const badBody = { ...warningInput };
    delete badBody.type;
    await api.functional.discussionboard.warnings.post(connection, {
      body: badBody,
    });
  });

  // 5. Duplication error (repeat with same keys)
  await TestValidator.error("duplicate warning rejection")(async () => {
    await api.functional.discussionboard.warnings.post(connection, {
      body: warningInput,
    });
  });

  // 6. Invalid member id error
  await TestValidator.error("invalid member id failure")(async () => {
    const invalidBody = { ...warningInput, memberId: "invalid-id" };
    await api.functional.discussionboard.warnings.post(connection, {
      body: invalidBody,
    });
  });

  // 7. Permission check: simulate as normal user if possible
