import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Validate post deletion permissions and behavior for discussion board posts.
 *
 * This test verifies that only permitted users (post author, moderator/admin) can delete posts, while unauthorized users are denied.
 *
 * Steps:
 * 1. Register three members: (A) author, (B) moderator/admin, (C) another member.
 * 2. Author creates a post.
 * 3. Author deletes their post (should succeed).
 * 4. Moderator/admin creates a new post, author deletes (should fail), moderator deletes (should succeed).
 * 5. Unauthorized member attempts to delete a post (should fail).
 * 6. Attempt deletion of non-existent or already-deleted post (ensure 404 or idempotency).
 * 7. Check soft/hard delete by attempting to retrieve the deleted post, and verifying visibility in lists or queries (skipped if listing/query API not provided).
 * 8. (Skipped) Audit/moderation record verification as API does not expose those endpoints.
 */
export async function test_api_discussionboard_test_delete_post_by_author_moderator_and_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Register author, moderator, and unauthorized member
  const author = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(author);
  const moderator = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(moderator);
  const unauthorized = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(unauthorized);

  // 2. Author creates a post
  const authorPost = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(authorPost);

  // 3. Author deletes their post (should succeed)
  await api.functional.discussionboard.posts.eraseById(connection, {
    id: authorPost.id,
  });

  // 4. Moderator creates a post, test deletion permissions
  const moderatorPost = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(moderatorPost);
  // Author attempts to delete moderator's post (should fail)
  await TestValidator.error("author cannot delete moderator's post")(
    () =>
      api.functional.discussionboard.posts.eraseById(connection, {
        id: moderatorPost.id,
      }),
  );
  // Moderator deletes their own post (should succeed)
  await api.functional.discussionboard.posts.eraseById(connection, {
    id: moderatorPost.id,
  });

  // 5. Unauthorized member tries to delete author's deleted post (should fail or 404)
  await TestValidator.error("unauthorized cannot delete already deleted post")(
    () =>
      api.functional.discussionboard.posts.eraseById(connection, {
        id: authorPost.id,
      }),
  );

  // 6. Attempt deletion of random non-existent post
  await TestValidator.error("delete non-existent post should fail")(
    () =>
      api.functional.discussionboard.posts.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 7. Check soft/hard delete mode—would require post-get or list endpoint (skipped)
  // 8. (Skipped) Check audit/moderation trail—no audit/moderation API provided
}

