/**
 * E2E test for retrieving discussion board member history logs with various filters and verifying role-based access.
 *
 * This test checks that:
 * 1. Member history records are retrievable with filters (member, event type, recent date) for admin.
 * 2. Moderator can also retrieve filtered histories.
 * 3. Non-privileged users (basic) cannot access all histories—they should get rejected.
 * 4. Audit logs are only visible to admin/moderator.
 * 5. Malformed filter payloads result in server rejection.
 * 6. Paged response structure and history item contents are correct.
 *
 * Steps:
 * 1. Create multiple members to serve as both history actors and targets.
 * 2. Insert several member history records tied to the members, each with distinctive event types, timestamps, and actor/target variation.
 * 3. Login as admin, fetch history with filter (by target member, event type, date window), validate:
 *    - All matches have correct event types, actors, timestamps, pagination structure.
 * 4. Repeat as moderator, check access works similarly.
 * 5. Attempt to get complete history as regular (non-privileged) member; confirm access is denied.
 * 6. Attempt list with malformed/invalid filter criteria; confirm server rejects.
 */
export async function test_api_discussionboard_test_list_member_histories_with_various_filters_and_permissions(connection: api.IConnection) {
