  TestValidator.error("basic member forbidden history access")(() =>
    api.functional.discussionboard.memberHistories.patch(connection, { body: reqFilter })
  );

  // 6. Malformed filter: send empty/invalid payload
  TestValidator.error("malformed filter payload")(() =>
