import type { IdiscussionboardMemberHistories } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardMemberHistories";

/**
 * Test soft-deletion of a discussionboard member history by its ID through the admin API.
 *
 * This test validates the following business logic:
 * - An admin can soft-delete (set deleted_at) a specific member history event
 * - After deletion, the record remains for audit (deleted_at set) but is not returned in ordinary list queries
 * - Proper error is raised when attempting to delete as a non-admin, or to delete a non-existent/already-deleted record
 * - Deletion does not break auditability or related data linkage to the member
 *
 * Test Steps:
 * 1. Create a member (for event linkage)
 * 2. Create a member history event for that member (simulate admin privilege)
 * 3. Delete the member history event as admin (eraseById)
 *    - Assert: The returned record has deleted_at populated
 * 4. (Simulate) List member histories (should not include the soft-deleted event)
 *    - This step is omitted as no such API is present in materials
 * 5. Attempt to delete the same event again — expect error
 * 6. Attempt delete as non-admin (simulate by using same connection, since roles cannot be switched in provided API) — expect error
 * 7. Attempt to delete a random non-existent event — expect error
 *
 * Note: Admin/non-admin switching and list query cannot be performed as relevant APIs are not provided. Only feasible business logic is checked.
 */
export async function test_api_discussionboard_memberHistories_test_delete_member_history_by_id_normal_and_forbidden(
  connection: api.IConnection,
) {
  // 1. Create a member (for event linkage)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a member history event for that member
  const event = await api.functional.discussionboard.memberHistories.post(connection, {
    body: typia.random<IDiscussionboardMemberHistory.ICreate>(),
  });
  typia.assert(event);

  // 3. Delete the member history event (soft-delete)
  const deleted = await api.functional.discussionboard.memberHistories.eraseById(connection, {
    id: event.id,
  });
  typia.assert(deleted);
  // (Optional) If available: TestValidator.predicate('deleted_at set')(!!deleted.deleted_at);

  // 4. List query to confirm event is not visible in default queries is omitted — no such API present.

  // 5. Attempt to delete the same event again — expect error
  await TestValidator.error("already deleted event - second deletion should fail")(
    () => api.functional.discussionboard.memberHistories.eraseById(connection, { id: event.id })
  );

  // 6. Attempt deletion as non-admin is omitted — no way to distinguish/authenticate role in given API

  // 7. Attempt to delete a random non-existent event — expect error
  await TestValidator.error("deleting non-existent member history should fail")(
    () => api.functional.discussionboard.memberHistories.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );
}

