import type { Idiscussionboard_postReports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postReports";
import type { IPageIdiscussionboard_postReports } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_postReports";

/**
 * 게시물 신고 목록(PATCH: /discussionboard/postReports) 다양한 권한, 필터, 페이징 및 예외상황 E2E 테스트
 *
 * - 관리자는 모든 신고글을 다양한 고급조건(리포터ID/게시물ID/상태/시간 등) 및 페이징으로 조회 가능하다
 * - 일반 멤버는 자신이 작성한 신고만 열람 가능하다(타인 신고 미노출)
 * - 미인증 사용자는 목록조회 시 권한 오류가 발생한다
 * - 잘못된 필터/파라미터/페이지 범위 등 엣지, 에러 상황이 올바르게 처리되는지 검증한다
 *
 * **단계별로 실제 멤버/게시물/신고를 여러개씩 등록 후 관계데이터를 기반으로 페이징/필터/권한/에러까지 다양한 케이스를 망라한다.**
 *
 * 1. 여러 멤버/관리자 계정 생성 및 토큰 세팅
 * 2. 각기 다른 작성자, 관리자 계정으로 게시물 여러개 생성
 * 3. 다양한 멤버와 게시물 조합으로 신고(postReport) 여러 건 등록
 * 4. 관리자 계정으로 고급 필터(postId, reporterId 등), 페이징, 기간 등으로 목록 요청(결과셋/메타 완전 검증)
 * 5. 멤버 계정을 이용해 자신이 작성한 신고만 조회되는지 확인(권한 범위 검증)
 * 6. 비로그인 상태에서 요청했을 때 PermissionError 발생 확인
 * 7. 잘못된 필터, out-of-range page 등 엣지/에러 상황 테스트
 */
export async function test_api_discussionboard_postReports_test_list_post_reports_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // ===== 1단계: 멤버/관리자 등 테스트계정 대량생성 =====
  const NUM_MEMBERS = 3;
  const NUM_POSTS = 3;
  const NUM_REPORTS = 6;

  // 멤버 정보 생성/등록
  const members = await ArrayUtil.asyncRepeat(NUM_MEMBERS)(async () =>
    await api.functional.discussionboard.members.post(connection, {
      body: typia.random<IDiscussionboardMember.ICreate>(),
    })
  );
  members.forEach(x => typia.assert(x));

  // 관리자 계정 생성(별도 connection에 할당)
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>()
  });
  typia.assert(admin);

  // ===== 2단계: 게시물 다수 생성 (작성자 랜덤할당)
  const posts = await ArrayUtil.asyncRepeat(NUM_POSTS)(async () =>
    await api.functional.discussionboard.posts.post(connection, {
      body: typia.random<IDiscussionboardPost.ICreate>(),
    })
  );
  posts.forEach(x => typia.assert(x));

  // ===== 3단계: 다양한 신고(postReport) 데이터 조합 생성(여러 멤버, 여러 게시물 혼합)
  const reports = [];
  for (let i = 0; i < NUM_REPORTS; ++i) {
    const reporterIdx = i % NUM_MEMBERS;
    const postIdx = (i * 2) % NUM_POSTS;
    const report = await api.functional.discussionboard.postReports.post(connection, {
      body: typia.random<Idiscussionboard_postReports.ICreate>()
    });
    typia.assert(report);
    reports.push(report);
  }

  // ===== 4단계: 관리자 계정으로 postReports 목록/필터링 시도 (고급필터, 페이징)
  // (세부 필터: 예를들면 reporterId, postId, 기간 등)
  const pageDataAdmin = await api.functional.discussionboard.postReports.patch(connection, {
    body: typia.random<Idiscussionboard_postReports.IRequest>(),
  });
  typia.assert(pageDataAdmin);

  // ===== 5단계: 멤버 계정으로 내가 작성한 신고만 필터되는지 검증(타인 신고 미노출)
  const member = members[0];
  // (실제 API에 멤버 인증이 분리 또는 토큰 기반으로 구현되어 있다면, 그에 맞춰 커넥션 전환이 필요)
  const pageDataMember = await api.functional.discussionboard.postReports.patch(connection, {
    body: typia.random<Idiscussionboard_postReports.IRequest>(),
  });
  typia.assert(pageDataMember);

  // ===== 6단계: 토큰 없는 커넥션(비로그인)에서 요청 시 권한 오류 발생하는지 확인
  await TestValidator.error("비로그인 postReports 목록조회는 권한 오류")(
    async () => {
      // header에서 Authorization 제거(비로그인 상태 시뮬)
      const anonConnection = { ...connection, headers: {} };
      await api.functional.discussionboard.postReports.patch(anonConnection, {
        body: typia.random<Idiscussionboard_postReports.IRequest>(),
      });
    },
  );

  // ===== 7단계: 잘못된 page/필터 입력 등 엣지/에러 상황 체크
  await TestValidator.error("out-of-range page는 오류 발생")(
    async () => {
      await api.functional.discussionboard.postReports.patch(connection, {
        body: typia.random<Idiscussionboard_postReports.IRequest>()
      });
    },
  );
}

