 * 2. Register an admin user.
 * 3. memberA creates a post.
 * 4. memberA reports their own post (creating a report).
 * 5. memberA retrieves their own report by ID (happy path: success expected).
 * 6. Admin retrieves the report by ID (admin cross-access: success expected).
 * 7. memberB attempts to retrieve the report they do not own and receives forbidden error.
 * 8. Attempt to retrieve report by a non-existent (random) UUID, expecting not found.
 * 9. Attempt to retrieve a report by an invalid ID format (not UUID), expects validation error.
 *
 * Note: User/session switching for RBAC is denoted by comments. Actual session tokens or login APIs are not present in current SDK/DTO. Replace comments with concrete authentication code when login is available.
 */
export async function test_api_discussionboard_postReports_test_get_post_report_by_id_with_various_roles_and_error_cases(
  connection: api.IConnection,
) {
