  // 6. memberA (report author) retrieves their own report (should succeed)
  // --- Session: memberA
  const authorGet = await api.functional.discussionboard.postReports.getById(connection, { id: report.id });
  typia.assert(authorGet);

  // 7. Admin retrieves the report (should succeed)
  // --- Session: admin (session switch assumed by infra)
  const adminGet = await api.functional.discussionboard.postReports.getById(connection, { id: report.id });
  typia.assert(adminGet);

