import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postReports } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postReports";
import type { IDiscussionboardPostReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReport";

/**
 * /discussionboard/postReports/{id} 포스트 신고 레코드의 상태/모더레이터 코멘트 등 업데이트 검증
 *
 * - 관리자·모더레이터만 정상적으로 업데이트 가능함을 확인(RBAC)
 * - 해결 상태/모더레이터 코멘트 갱신 성공과, 이미 종결된 신고 재수정, 삭제/미존재 id, 회원/비회원 update 모두 실패 처리되는지 검증
 * - 직접적 감사로그 확인 API는 없으나, update의 성공 응답으로 간접 증명
 *
 * 진행순서:
 * 1. 신고 회원 가입
 * 2. 신고 대상 게시글 작성
 * 3. 신고 생성
 * 4. 신고 id 획득
 * 5. 어드민 등록
 * 6. 관리자 권한으로 정상 update (상태·코멘트 등)
 * 7. 이미 종결된 신고 재수정 시도 실패
 * 8. 무효/삭제된 id로 update 시도 실패
 * 9. 인증없는 connection(비로그인) update 실패
 * 10. 일반회원 update 시도 실패
 */
export async function test_api_discussionboard_postReports_putById_test_update_post_report_status_and_moderator_comments(
  connection: api.IConnection,
) {
  // 1. 신고자 회원 생성
  const reporter = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(reporter);

  // 2. 게시글 작성
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. 신고 생성
  const postReport = await api.functional.discussionboard.postReports.post(connection, {
    body: typia.random<Idiscussionboard_postReports.ICreate>(),
  });
  typia.assert(postReport);

  // 4. 신고 id 획득
  const reportId = postReport.id;

  // 5. 어드민 등록
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 6. 관리자 권한으로 정상 update
  const updateInput: IDiscussionboardPostReport.IUpdate = typia.random<IDiscussionboardPostReport.IUpdate>();
  const updated = await api.functional.discussionboard.postReports.putById(connection, {
    id: reportId,
    body: updateInput,
  });
  typia.assert(updated);

  // 7. 종결된 신고 재수정 (updateInput으로 종결했다 가정), 실패 체크
  await TestValidator.error("종결 신고 재수정")(
    async () => {
      await api.functional.discussionboard.postReports.putById(connection, {
        id: reportId,
        body: typia.random<IDiscussionboardPostReport.IUpdate>(),
      });
    },
  );

  // 8. 랜덤 uuid로 update 시도 (존재하지 않는/삭제된 id), 실패 체크
  await TestValidator.error("존재하지 않는 id update")(
    async () => {
      await api.functional.discussionboard.postReports.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: typia.random<IDiscussionboardPostReport.IUpdate>(),
      });
    },
  );

  // 9. 비회원 connection (headers 없이)
