  await TestValidator.error("404 for non-existent board id")(() =>
    api.functional.discussionboard.boards.getById(connection, {
      id: randomUUID,
    }),
  );

  // 5. Create board with inactive status (simulate soft-deleted)
  const inactiveBoard = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(inactiveBoard);

  // 6. Attempt access as non-admin for inactive board (should fail/deny if policy enforced)
  await TestValidator.error("non-admin cannot access inactive/soft-deleted board")(() =>
    api.functional.discussionboard.boards.getById(connection, {
      id: inactiveBoard.id,
    }),
  );

  // 7. Admin access to inactive board (should succeed)
  const adminFetchedInactive = await api.functional.discussionboard.boards.getById(connection, {
    id: inactiveBoard.id,
  });
  typia.assert(adminFetchedInactive);
  TestValidator.equals("inactive board id matches")(adminFetchedInactive.id)(inactiveBoard.id);
}

