import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * Validate creation of comments under various conditions for the discussion board API.
 *
 * This test covers:
 * 1. Registering multiple members to act as comment authors.
 * 2. Creating a post as a base for commenting.
 * 3. Creating a top-level comment (simple reply to the post).
 * 4. Creating a nested reply to an existing comment (parent-child relationship).
 * 5. Verifying that comments cannot be created without all required fields, or with invalid IDs.
 * 6. Ensuring only authenticated (registered) members can create comments; unauthenticated creation is denied.
 * 7. Testing anti-spam/abuse behaviors (duplicate/rapid comments).
 * 8. Ensuring references to deleted or nonexistent parents/posts return appropriate errors.
 */
export async function test_api_discussionboard_test_create_comment_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register two members: commenter1 and commenter2
  const commenter1 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(commenter1);
  const commenter2 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(commenter2);

  // 2. commenter1 creates a new post
  // Simulate login by associating with commenter1 (no explicit login, so assume context is set)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. commenter2 creates a top-level comment on the post
  // (simulate context/use connection as commenter2)
  const comment1 = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment1);

  // 4. commenter2 creates a nested reply to their own previously created comment
  const nestedReply = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(nestedReply);

  // 5. commenter1 attempts to create a comment with missing/invalid data (should fail)
  await TestValidator.error("missing required field should fail")(async () => {
    // Intentionally omit a field using undefined (simulate TypeScript omission error, but real test would skip since TS would error)
    return api.functional.discussionboard.comments.post(connection, {
      body: {} as any,
    });
  });

  await TestValidator.error("invalid post_id should fail")(async () => {
    return api.functional.discussionboard.comments.post(connection, {
      body: typia.random<IDiscussionboardComment.ICreate>(),
    });
  });

  // 6. Attempt to create a comment while unauthenticated (should fail)
  const unauthConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization")
    ),
  };
  await TestValidator.error("unauthenticated actor should be rejected")(async () => {
    return api.functional.discussionboard.comments.post(unauthConnection, {
      body: typia.random<IDiscussionboardComment.ICreate>(),
    });
  });

  // 7. Test spam/abuse prevention by rapidly posting duplicate comments
  const spamCommentData = typia.random<IDiscussionboardComment.ICreate>();
  await api.functional.discussionboard.comments.post(connection, {
    body: spamCommentData,
  });
  await TestValidator.error("duplicate/rapid comment detected")(async () => {
    return api.functional.discussionboard.comments.post(connection, {
      body: spamCommentData,
    });
  });

  // 8. Attempt to reply to nonexistent parent/comment/post (should error)
  await TestValidator.error("nonexistent parent ID should fail")(async () => {
    return api.functional.discussionboard.comments.post(connection, {
      body: typia.random<IDiscussionboardComment.ICreate>(),
    });
  });
}

