import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";

/**
 * E2E test for deleting comments on the discussion board, covering permission and deletion policy variations.
 *
 * Business context:
 * - Comments can be deleted either via soft deletion (by author or moderator/admin) or hard/permanent deletion by authorized admin.
 * - Audit logging and notification triggers should occur on deletion.
 * - Moderation workflows, proper permission checks, and deletion visibility must be validated.
 *
 * Step-by-step process:
 * 1. Register four members: Author, Moderator, Admin, UnrelatedUser.
 *    - Assume only Admin has hard delete rights; Author/Moderator/Admin have soft delete rights.
 * 2. Author creates a top-level comment and a reply (child comment).
 * 3. Author (simulated) soft-deletes their own comment and validates response.
 * 4. Moderator (simulated) soft-deletes the child comment and validates response.
 * 5. Admin (simulated) hard-deletes the already soft-deleted parent comment and validates response.
 * 6. UnrelatedUser (simulated) attempts and fails to delete someone else's comment (permission denied).
 * 7. Attempts to delete already-deleted or non-existent comments (error responses as expected).
 * 8. All audit log, moderation, and notification triggers are described in comments (no API for these).
 *
 * Note:
 * - Member "role/context switching" for permission simulation is described in comments. No session-switching/auth APIs provided, so all calls use same connection and explain intent via comments.
 * - DTO structures are "any" (no strong typings). Only generic assertion and field existence checks are possible.
 * - No get/list endpoints available, so validation is confined to responses from creation/deletion calls.
 */
export async function test_api_discussionboard_test_delete_comment_soft_and_permanent_deletion(
  connection: api.IConnection,
) {
  // 1. Register four members: Author, Moderator, Admin, UnrelatedUser
  const author = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(author);
  const moderator = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(moderator);
  const admin = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(admin);
  const unrelatedUser = await api.functional.discussionboard.members.post(
    connection,
    { body: typia.random<IDiscussionboardMember.ICreate>() },
  );
  typia.assert(unrelatedUser);

  // 2. Author creates a top-level comment
  const parentComment = await api.functional.discussionboard.comments.post(
    connection,
    { body: typia.random<IDiscussionboardComment.ICreate>() },
  );
  typia.assert(parentComment);

  // Author creates a reply to the top-level comment (child comment)
  const childCommentCreate = typia.random<IDiscussionboardComment.ICreate>();
  childCommentCreate.parent_id = parentComment.id;
  const childComment = await api.functional.discussionboard.comments.post(
    connection,
    { body: childCommentCreate },
  );
  typia.assert(childComment);

  // 3. Author attempts to soft-delete their own comment (simulate author context)
  // In real scenario, switch session/auth to author
  const deletedByAuthor = await api.functional.discussionboard.comments.eraseById(
    connection,
    { id: parentComment.id },
  );
  typia.assert(deletedByAuthor);
  // If deleted/soft-delete flag is present, assert it here (structure unknown, as DTO is any)
  // e.g. TestValidator.predicate("soft-deleted status")(!!deletedByAuthor.deleted)

  // 4. Moderator attempts to soft-delete the child comment (simulate moderator context)
  // In real scenario, switch session/auth to moderator
  const deletedByModerator = await api.functional.discussionboard.comments.eraseById(
    connection,
    { id: childComment.id },
  );
  typia.assert(deletedByModerator);

  // 5. Admin attempts to hard-delete the already soft-deleted parent comment (simulate admin context)
  // In real scenario, switch session/auth to admin
  const deletedByAdmin = await api.functional.discussionboard.comments.eraseById(
    connection,
    { id: parentComment.id },
  );
  typia.assert(deletedByAdmin);
  // If deletion is hard/permanent, object structure may indicate (absence/flag changes); unable to check precisely (DTO is any)

  // 6. Unrelated user attempts to delete someone else's comment (simulate unrelated context)
  // In real scenario, switch session/auth to unrelatedUser
  await TestValidator.error("Unrelated user cannot delete someone else's comment")(
    () =>
      api.functional.discussionboard.comments.eraseById(connection, {
        id: parentComment.id,
      }),
  );

  // 7. Attempt to delete already deleted/non-existent comments
  // (a) Already hard-deleted parent
  await TestValidator.error("Cannot delete already deleted comment")(
    () =>
      api.functional.discussionboard.comments.eraseById(connection, {
        id: parentComment.id,
      }),
  );
  // (b) Random non-existent comment
  await TestValidator.error("Cannot delete non-existent comment")(
    () =>
      api.functional.discussionboard.comments.eraseById(connection, {
        id: typia.random<string & tags.Format<'uuid'>>(),
      }),
  );
  // 8. Audit logs/moderation/notification triggers:
  // (Cannot verify due to API surface. In real test, would check for audit records or notification dispatches here.)
}

