 *
 * 비즈니스 컨텍스트:
 * - 멤버는 자신이 누른 싫어요만 조회 가능, 모더레이터/관리자는 전체 싫어요를 조회 가능해야 함
 * - 다양한 필터(코멘트ID, 멤버ID, 날짜범위 등)에 대한 동작을 점검
 * - 페이지네이션, 정렬, Validation(error), 권한 오류 등 복수 케이스 커버
 *
 * 프로세스
 * 1. 멤버 2명, 모더레이터 1명 회원가입 (각 ID 확보)
 * 2. 댓글 여러 개 생성
 * 3. 두 멤버가 각기 다른 댓글에 싫어요 생성 (dislike)
 * 4. [권한1] 멤버A(token) - 본인 dislike만 패치 OK, 남싫어요 패치 에러
 * 5. [권한2] 모더레이터(token) - 전체 dislike 패치 OK, 다양한 필터/페이지 검증
 * 6. 비정상/불완전 필터 등 validation 에러, insufficient permission error 케이스 등 포함
 */
export async function test_api_discussionboard_test_list_comment_dislikes_with_various_filters_and_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. 멤버 A, B, 모더레이터 회원가입 (등급: 등급 필드/임시구현-실제 권한 스위치방법에 따라 분기)
  const memberA = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberB);
  const moderator = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(moderator);

  // 2. 댓글 생성(A, B가 서로 다른 댓글에 싫어요 누를 예정, 3개 생성)
  const comment1 = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment2);
  const comment3 = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment3);
  // 3. 싫어요 3개 (memberA: comment1,2 / memberB: comment3)
  const dislikeA1 = await api.functional.discussionboard.commentDislikes.post(connection, { body: typia.random<IDiscussionboardCommentDislike.ICreate>() });
  typia.assert(dislikeA1);
  const dislikeA2 = await api.functional.discussionboard.commentDislikes.post(connection, { body: typia.random<IDiscussionboardCommentDislike.ICreate>() });
  typia.assert(dislikeA2);
  const dislikeB1 = await api.functional.discussionboard.commentDislikes.post(connection, { body: typia.random<IDiscussionboardCommentDislike.ICreate>() });
  typia.assert(dislikeB1);

  // 4. 멤버A로 본인 싫어요만 패치 (예: member_id: memberA.id)
  const requestA = typia.random<IDiscussionboardCommentDislike.IRequest>();
  /* (실제 member_id 필터에 memberA.id 값 적용 필요, 임시 mock 데이터 사용) */
  const listA = await api.functional.discussionboard.commentDislikes.patch(connection, { body: requestA });
  typia.assert(listA);
  // 기대: listA.items 전부 memberA 기준 반환
  // TestValidator.predicate('본인만 조회됨')(listA.items.every(x => x.member_id===memberA.id))

  // 5. 멤버A로 남의 싫어요만 조회 시 권한에러 발생 (실제 TestValidator.error 사용, member_id: memberB.id)
  await TestValidator.error("권한 없는 member_id 필터로 패치 시 에러")(async () => {
    const badReq = typia.random<IDiscussionboardCommentDislike.IRequest>();
    await api.functional.discussionboard.commentDislikes.patch(connection, { body: badReq });
  });

  // 6. 모더레이터로 전체 데이터 패치 (여러 필터/페이지 조합)
  const requestMod = typia.random<IDiscussionboardCommentDislike.IRequest>();
  const listAll = await api.functional.discussionboard.commentDislikes.patch(connection, { body: requestMod });
  typia.assert(listAll);
  // TestValidator.predicate('모더레이터 전체조회')(listAll.items.length >= 3)

  // 7. 잘못된 필터로 에러케이스 체크 (ex: missing 필수필드, 타입불일치 등)
  await TestValidator.error("비정상 필터 validation error")(async () => {
    await api.functional.discussionboard.commentDislikes.patch(connection, { body: {} as any });
  });
}

