import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * 댓글 싫어요 이벤트 단건 상세 조회 E2E 테스트.
 *
 * - 본인, 혹은 운영자/관리자만 해당 싫어요(Dislike) 기록의 상세를 볼 수 있고, 타인은 볼 수 없어야 함을 검증합니다.
 * - 올바른 접근 권한 보유자(본인, 관리자)가 정상적으로 싫어요 상세를 조회할 수 있어야 합니다.
 * - 권한 없는 사용자가 남의 싫어요를 조회 시도하면 에러가 발생해야 함을 (API가 제공하는 한도 내에서) 검증합니다.
 * - 존재하지 않는 id로 조회할 때 적절한 에러(404 등)가 발생하는지 확인합니다.
 * - 응답 결과가 스키마와 일치하는 지 typia.assert로 검증합니다.
 *
 * [한계] 실제 역할(멤버/운영자)간 전환, 인증 기반 권한 분기/스위칭은 지원 API가 없어 구현 불가합니다.
 *        멤버/관리자 구분 없이 record 생성/조회는 가능하나, 진짜 권한 분기 로직 검증은 보류합니다.
 *        입력/출력 스키마 유효성과, 존재/비존재 ID에 따른 정상/에러 흐름만 본다.
 *
 * # 테스트 프로세스
 * 1. 멤버A, 멤버B, '관리자' 용도로 멤버 3명 생성
 * 2. 임의 댓글 생성 (멤버A 것이어야 하나, 타입 상세 없음 = 랜덤)
 * 3. 임의 싫어요 엔티티 생성 (멤버A소유여야 하나, 정보 불확실 = 랜덤)
 * 4. dislike.id로 상세조회 (성공해야 함)
 * 5. 존재하지 않는 random id로 조회 시도(실패/에러) (권한 분기 불가, 오로지 에러만 봄)
 */
export async function test_api_discussionboard_test_get_comment_dislike_detail_by_id_with_permissions_and_error_handling(
  connection: api.IConnection,
) {
  // 1. 멤버 3명 생성 (A, B, 관리용)
  const memberA = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberA);
  const memberB = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(memberB);
  const adminMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(adminMember);

  // 2. 댓글 생성 (멤버A의 댓글이어야 이상적이나, 타입상 랜덤)
  const comment = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment);

  // 3. 싫어요 생성 (멤버A것이어야 하나 정보가 없어 타입상 랜덤)
  const dislike = await api.functional.discussionboard.commentDislikes.post(connection, { body: typia.random<IDiscussionboardCommentDislike.ICreate>() });
  typia.assert(dislike);

  // 4. 생성된 dislike 를 id로 상세조회(성공)
  const found = await api.functional.discussionboard.commentDislikes.getById(connection, { id: dislike.id });
  typia.assert(found);

  // 5. 임의로 존재하지 않을 만한 id로 조회 시(실패-에러남)
  await TestValidator.error("임의의 없는 dislike id(detail) 조회시 에러처리됨을 확인")(
    async () => {
      await api.functional.discussionboard.commentDislikes.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );
