import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentDislike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentDislike";

/**
 * 댓글 비공감(싫어요) 기록 삭제(언디슬라이크) E2E 검증
 *
 * 본 테스트는 discussionboard_comment_dislikes 테이블의 특정 dislike 기록이 소유자(멤버)와 privileged role(스태프/관리자) 계정에 의해 삭제되는 정상 케이스와, 주인이 아닌 멤버의 삭제 시도·존재하지 않는 idempotent 삭제 등 다양한 시나리오를 모두 점검한다.
 *
 * - 소유자인 멤버 혹은 staff(모더레이터/관리자)만 삭제권한을 갖는지 검증
 * - 잘못된/잘못된 주체의 삭제 시도 시 오류 응답을 검증
 * - 이미 삭제된 dislike(존재하지 않는 기록) 삭제 시 idempotent하게 성공됨을 확증
 * - dislike 삭제 후 실제 누락 여부를 API 결과로 검증
 * - (가능하다면) 댓글이나 멤버 삭제 시 cascade 효과로 dislike 자동삭제되는지 확인
 *
 * [테스트 절차]
 * 1. 일반 멤버 A, B, C와 staff(스태프) 계정 생성
 * 2. C가 댓글 작성
 * 3. A, B가 해당 댓글에 dislike
 * 4. A가 자신의 dislike 삭제(정상, 소유자)
 * 5. staff가 B의 dislike 삭제(정상, privileged role)
 * 6. C(댓글작성자)가 B의 dislike 삭제 시도(권한 오류, 실패)
 * 7. A가 삭제된 자신의 dislike를 재삭제(존재하지 않음, idempotent 처리)
 * 8. B가 삭제된 자신의 dislike를 재삭제(존재하지 않음, idempotent 처리)
 * 9. (가능하다면) 댓글/멤버 삭제 시 해당 dislike cascade 제거 확인
 */
export async function test_api_discussionboard_test_delete_comment_dislike_by_owner_and_privileged_roles(
  connection: api.IConnection,
) {
  // 1. 멤버 및 staff 등 계정 4개 발급
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  const memberC = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberC);

  const staff = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(staff);
  // (실제 테스트 환경에선 staff의 권한 부여 필요)

  // 2. C가 댓글 작성
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. A, B가 댓글에 dislike
  const dislikeA = await api.functional.discussionboard.commentDislikes.post(connection, {
    body: typia.random<IDiscussionboardCommentDislike.ICreate>(),
  });
  typia.assert(dislikeA);

  const dislikeB = await api.functional.discussionboard.commentDislikes.post(connection, {
    body: typia.random<IDiscussionboardCommentDislike.ICreate>(),
  });
  typia.assert(dislikeB);

  // 4. A가 자신의 dislike 삭제
  const deletedA = await api.functional.discussionboard.commentDislikes.eraseById(connection, {
    id: dislikeA.id,
  });
  typia.assert(deletedA);

  // 5. staff가 B의 dislike 삭제
  const deletedB = await api.functional.discussionboard.commentDislikes.eraseById(connection, {
    id: dislikeB.id,
  });
  typia.assert(deletedB);

  // 6. C가 B의 dislike 삭제 시도 - 반드시 권한오류로 실패해야 한다
  await TestValidator.error("권한 없는 멤버의 dislike 삭제 시도")(() =>
    api.functional.discussionboard.commentDislikes.eraseById(connection, {
      id: dislikeB.id,
    })
  );

  // 7. A가 이미 삭제된 자신의 dislike 재삭제(idempotent, 성공적으로 동작함을 보장)
  const retriedA = await api.functional.discussionboard.commentDislikes.eraseById(connection, {
    id: dislikeA.id,
  });
  typia.assert(retriedA);

  // 8. B가 이미 삭제된 자신의 dislike 재삭제(idempotent)
  const retriedB = await api.functional.discussionboard.commentDislikes.eraseById(connection, {
    id: dislikeB.id,
  });
  typia.assert(retriedB);

  // 9. (Cascade) 댓글 삭제-해당 dislike 자동제거(불가시 생략)
  // ※ 댓글 삭제 API 없으면 skip, 가능하다면 구현
}

