  const created = await api.functional.discussionboard.policies.post(connection, { body: validPolicy });
  typia.assert(created);

  // 2-1. 필수값 누락(title)
  const missingTitle = { ...validPolicy };
  delete (missingTitle as any).title;
  await TestValidator.error("title 누락시 validation 에러")(() =>
    // 실제로 title property가 없을 때 서버에서 validation error가 나는지 기대
    api.functional.discussionboard.policies.post(connection, { body: missingTitle as any })
  );

  // 2-2. 중복 title/version 정책 생성
  // 최초 한 번 생성 후, 같은 데이터로 다시 생성 시도
  await api.functional.discussionboard.policies.post(connection, { body: validPolicy });
  await TestValidator.error("중복 title/version에 대한 에러")(() =>
    api.functional.discussionboard.policies.post(connection, { body: validPolicy })
