import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";
import type { IPageDiscussionboardNotifications } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotifications";

/**
 * Test paginated and filtered notification list retrieval for a member, including authorization and edge cases.
 *
 * This E2E test verifies that the notification listing API returns correct notifications for a member based on various filter criteria and pagination parameters.
 * It sets up a member, creates a diverse set of notification records (with type/channel/read/unread variations, date spread, etc.), and validates listing behavior under filter, pagination, and access control scenarios.
 *
 * Steps:
 * 1. Register a test member (the test subject) and another unrelated member.
 * 2. Create notifications for the test subject with various types, channels, read states, and dates. Also create notifications for the unrelated member as control.
 * 3. List notifications as the test subject:
 *    - Filter by notification type
 *    - Filter by channel (on_site/email)
 *    - Filter by read/unread
 *    - Filter by date range (inside and outside coverage)
 *    - Paginate (page/size)
 * 4. At each query, assert results only cover expected notifications and pagination metadata is correct. Edge: filter producing empty result.
 * 5. Attempt to list notifications as unauthorized/other member (verify access control: error or empty, as business rules dictate).
 */
export async function test_api_discussionboard_notifications_test_list_notifications_with_pagination_and_filtering(connection: api.IConnection) {
  // 1. Register test subject member & a control member
  const member1 = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(member1);
  const member2 = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(member2);

  // 2. Create notifications for both members
  // We'll create:
  // - 3 for member1: {type: 'reply', channel: 'on_site', unread, recent},
  //                  {type: 'mention', channel: 'email', read, a few days ago},
  //                  {type: 'warning', channel: 'on_site', unread, old}
  // - 1 for member2 (for isolation)
  // Notification DTOs are randomized with plausible manual type/channel/status
  const notif_recent = await api.functional.discussionboard.notifications.post(connection, { body: { ...(typia.random<discussionboard_notifications.ICreate>()), receiver_member_id: member1.id, type: 'reply', channel: 'on_site', read: false, created_at: new Date().toISOString() } });
  typia.assert(notif_recent);
  const notif_email = await api.functional.discussionboard.notifications.post(connection, { body: { ...(typia.random<discussionboard_notifications.ICreate>()), receiver_member_id: member1.id, type: 'mention', channel: 'email', read: true, created_at: new Date(Date.now() - 4 * 24 * 60 * 60 * 1000).toISOString() } });
  typia.assert(notif_email);
  const notif_old = await api.functional.discussionboard.notifications.post(connection, { body: { ...(typia.random<discussionboard_notifications.ICreate>()), receiver_member_id: member1.id, type: 'warning', channel: 'on_site', read: false, created_at: new Date(Date.now() - 8 * 24 * 60 * 60 * 1000).toISOString() } });
  typia.assert(notif_old);
  const notif_other = await api.functional.discussionboard.notifications.post(connection, { body: { ...(typia.random<discussionboard_notifications.ICreate>()), receiver_member_id: member2.id, type: 'reply', channel: 'email', read: false, created_at: new Date().toISOString() } });
  typia.assert(notif_other);

  // 3a. Filter by type = 'reply' (should only match notif_recent)
  let page = await api.functional.discussionboard.notifications.patch(connection, { body: { type: 'reply', receiver_member_id: member1.id, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('filter by type returns correct results')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.type === 'reply' && n.receiver_member_id === member1.id));

  // 3b. Filter by channel = 'email' (should only match notif_email)
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { channel: 'email', receiver_member_id: member1.id, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('filter by channel returns correct results')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.channel === 'email' && n.receiver_member_id === member1.id));

  // 3c. Filter by read/unread (read:true)
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { read: true, receiver_member_id: member1.id, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('filter by read')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.read === true && n.receiver_member_id === member1.id));

  // 3d. Filter by read/unread (read:false)
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { read: false, receiver_member_id: member1.id, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('filter by unread')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.read === false && n.receiver_member_id === member1.id));

  // 3e. Filter by date range covering only old notification (simulate date range with known created_at)
  const from = new Date(Date.now() - 9 * 24 * 60 * 60 * 1000).toISOString();
  const to = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { receiver_member_id: member1.id, created_from: from, created_to: to, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('filter by date range')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.receiver_member_id === member1.id && n.created_at >= from && n.created_at <= to));

  // 3f. Pagination works: size = 1, should get only one result and correct total count
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { receiver_member_id: member1.id, page: 1, size: 1 } });
  typia.assert(page);
  TestValidator.equals('pagination page size')(page.data.length)(1);
  TestValidator.predicate('pagination total count')(typeof page.total === 'number' && page.total >= 3);

  // 4. Edge: filter with no matches (e.g., nonsense type)
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { receiver_member_id: member1.id, type: 'nonsense_type', page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.equals('empty when no result')(page.data.length)(0);

  // 5. List as another member (should not see member1's notifications regardless of filters)
  page = await api.functional.discussionboard.notifications.patch(connection, { body: { receiver_member_id: member2.id, page: 1, size: 10 } });
  typia.assert(page);
  TestValidator.predicate('other member only sees own notifications')(Array.isArray(page.data) && page.data.every((n: discussionboard_notifications) => n.receiver_member_id === member2.id));
}

