/**
 * Test updating a notification's read/unread status and metadata in discussionboard_notifications.
 *
 * Business context:
 *  - Verifies correct behavior for marking a notification as read by the owner
 *  - Verifies admin privilege to update notification metadata
 *  - Checks that unauthorized updates are forbidden
 *  - Checks correct error handling on updating non-existent or deleted notification
 *
 * Steps:
 * 1. Register a member as the notification owner
 * 2. Register an admin
 * 3. Create a notification for the member
 * 4. As the member, update their notification (e.g., mark as read)
 * 5. As the admin, update the notification metadata for compliance/audit
 * 6. Simulate an unauthorized user's update attempt (should fail)
 * 7. Attempt to update a non-existent notification (should fail)
 *
 * Any steps involving retrieval/listing notifications are skipped as no such endpoints exist in provided materials.
 */
export async function test_api_discussionboard_test_update_notification_read_status_and_metadata(
  connection: api.IConnection,
) {
  // 1. Register a member (owner of notification)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Register an admin
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 3. Create notification (for the member)
  const notification = await api.functional.discussionboard.notifications.post(connection, {
    body: typia.random<discussionboard_notifications.ICreate>(),
  });
  typia.assert(notification);

  // 4. As the member: update (e.g., mark as read)
  const memberUpdateInput = typia.random<discussionboard_notifications.IUpdate>();
  const updatedByMember = await api.functional.discussionboard.notifications.putById(connection, {
    id: notification.id,
    body: memberUpdateInput,
  });
  typia.assert(updatedByMember);

  // 5. As the admin: update notification metadata (e.g., delivery channel/message correction)
  const adminUpdateInput = typia.random<discussionboard_notifications.IUpdate>();
  const updatedByAdmin = await api.functional.discussionboard.notifications.putById(connection, {
    id: notification.id,
    body: adminUpdateInput,
  });
  typia.assert(updatedByAdmin);

  // 6. Attempt forbidden update as unrelated member
  const outsider = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(outsider);
  await TestValidator.error("unauthorized notification update should fail")(
    () => api.functional.discussionboard.notifications.putById(connection, {
      id: notification.id,
      body: typia.random<discussionboard_notifications.IUpdate>(),
    })
  );

  // 7. Attempt to update a non-existent/deleted notification
  await TestValidator.error("update non-existent notification should fail")(
    () => api.functional.discussionboard.notifications.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: typia.random<discussionboard_notifications.IUpdate>(),
    })
  );
}

