import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";

/**
 * Validate notification deletion scenarios (by owner, by admin, unauthorized attempts).
 *
 * 1. Register a member (will be the notification owner)
 * 2. Register a second member (for unauthorized access checks)
 * 3. Register an admin account
 * 4. As admin, create a notification for the member
 * 5. As the member, delete their own notification
 *    - Verify deletion response, acknowledge cannot fetch-by-id (no read endpoint)
 * 6. As admin, create another notification for the member, then delete it directly
 *    - Verify deletion
 * 7. Attempt to delete a non-existent notification as both member and admin (should error)
 * 8. Attempt to delete a notification as another member (should error)
 * 9. Unauthenticated/side-effect/audit checks not possible due to SDK/API surface
 */
export async function test_api_discussionboard_test_delete_notification_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. Register a member (will be used as notification recipient)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Register another member (for permission denial test)
  const otherMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(otherMember);

  // 3. Register an admin user
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 4. As admin, create a notification targeting the member
  const notification1 = await api.functional.discussionboard.notifications.post(connection, {
    body: typia.random<discussionboard_notifications.ICreate>(),
  });
  typia.assert(notification1);

  // 5. Member deletes their own notification
  const deletedNotif1 = await api.functional.discussionboard.notifications.eraseById(connection, {
    id: notification1.id,
  });
  typia.assert(deletedNotif1);

  // 6. There is no endpoint for fetching/deleting notifications by id (read), so cannot verify absence directly
  //    (If a get/list endpoint existed, we would test it here)

  // 7. As admin, create another notification for the member
  const notification2 = await api.functional.discussionboard.notifications.post(connection, {
    body: typia.random<discussionboard_notifications.ICreate>(),
  });
  typia.assert(notification2);

  // Admin deletes this notification directly
  const deletedNotif2 = await api.functional.discussionboard.notifications.eraseById(connection, {
    id: notification2.id,
  });
  typia.assert(deletedNotif2);

  // 8. Attempt to delete a non-existent or already-deleted notification (should raise error)
  await TestValidator.error("delete already-deleted notification as member")(
    async () => {
      await api.functional.discussionboard.notifications.eraseById(connection, {
        id: notification2.id,
      });
    },
  );
  await TestValidator.error("delete already-deleted notification as admin")(
    async () => {
      await api.functional.discussionboard.notifications.eraseById(connection, {
        id: notification1.id,
      });
    },
  );

  // 9. Attempt to delete as another member (should fail with permission denied)
  await TestValidator.error("delete other's notification as different member")(
    async () => {
      await api.functional.discussionboard.notifications.eraseById(connection, {
        id: notification2.id,
      });
    },
  );

  // 10. Unauthenticated/side-effect/audit trail validation impossible here (no API surface for those)
}

