 * - Both admin and member accounts can retrieve details for normal/public channels.
 * - Only admins can retrieve hidden or soft-deleted channel details, while members are denied.
 * - Forbidden/permission error responses occur as expected for member attempts on restricted channels.
 *
 * Steps:
 * 1. Create admin account and login (admin context).
 * 2. Create a mixture of channels: public, hidden, and (simulate) deleted via admin rights.
 * 3. Create & login a regular member account (member context).
 * 4. Try to retrieve channel details for each type (as admin, then as member).
 * 5. Assert admin always succeeds and details are valid.
 * 6. Assert member succeeds only for public channels, but gets permission error for hidden/deleted ones.
 */
export async function test_api_discussionboard_test_get_channel_details_as_admin_and_member(
  connection: api.IConnection,
) {
  // 1. Create and login as admin
  const admin: IDiscussionboardAdmin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a mixture of channels (public, hidden, deleted) as admin
  const publicChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(publicChannel);

  // Simulate hidden channel creation (if 'visibility' exists)
  const hiddenChannelInput = typia.random<IDiscussionboardChannel.ICreate>();
  if (typeof hiddenChannelInput === "object" && hiddenChannelInput !== null && "visibility" in hiddenChannelInput)
    hiddenChannelInput.visibility = "hidden";
  const hiddenChannel = await api.functional.discussionboard.channels.post(connection, {
    body: hiddenChannelInput,
  });
  typia.assert(hiddenChannel);

  // Simulate deleted channel creation (if 'deleted' exists)
  const deletedChannelInput = typia.random<IDiscussionboardChannel.ICreate>();
  if (typeof deletedChannelInput === "object" && deletedChannelInput !== null && "deleted" in deletedChannelInput)
    deletedChannelInput.deleted = true;
  const deletedChannel = await api.functional.discussionboard.channels.post(connection, {
    body: deletedChannelInput,
  });
  typia.assert(deletedChannel);

  // 3. Create and login as member
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 4. Retrieve each channel as admin (should always succeed)
  for (const channel of [publicChannel, hiddenChannel, deletedChannel]) {
    const detail = await api.functional.discussionboard.channels.getById(connection, { id: channel.id });
    typia.assert(detail);
  }

  // 5. MEMBER CONTEXT: Retrieve channels and test permission boundaries
  // Public channel should succeed
  const publicDetail = await api.functional.discussionboard.channels.getById(connection, { id: publicChannel.id });
  typia.assert(publicDetail);

  // Hidden channel should throw permission error
  await TestValidator.error("Member forbidden from hidden channel")(
    async () => {
      await api.functional.discussionboard.channels.getById(connection, { id: hiddenChannel.id });
    },
  );

  // Deleted channel should throw permission error
  await TestValidator.error("Member forbidden from deleted channel")(
    async () => {
      await api.functional.discussionboard.channels.getById(connection, { id: deletedChannel.id });
    },
  );
}

