import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validate errors when creating a channel with duplicate name and missing fields.
 *
 * This test ensures that:
 * 1. An admin can create a unique channel successfully.
 * 2. Attempting to create another channel with the same name fails due to unique constraint.
 * 3. Attempting to create a channel with missing required fields (like name or description) fails with a validation error.
 * 4. No extra/invalid channels are created on failure.
 *
 * Steps:
 * 1. Create an admin user via /discussionboard/admins (dependency).
 * 2. As the admin, create a new channel with valid data via /discussionboard/channels.
 * 3. Attempt to create a channel with the same name (should fail with uniqueness error).
 * 4. Attempt to create a channel with missing name (should fail with validation error).
 * 5. Attempt to create a channel with missing description (should fail with validation error).
 * 6. Confirm only the original channel exists (cannot implement due to lack of list API).
 */
export async function test_api_discussionboard_test_create_channel_with_duplicate_name_or_invalid_request(
  connection: api.IConnection,
) {
  // 1. Create the admin user (dependency)
  const adminInput = typia.random<IDiscussionboardAdmin.ICreate>();
  const admin = await api.functional.discussionboard.admins.post(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Create an initial channel (dependency)
  const channelInput = typia.random<IDiscussionboardChannel.ICreate>();
  const channel = await api.functional.discussionboard.channels.post(connection, { body: channelInput });
  typia.assert(channel);

  // 3. Attempt to create a channel with duplicate name (uniqueness violation)
  const duplicateInput = { ...channelInput };
  await TestValidator.error("duplicate channel name should fail")(() =>
    api.functional.discussionboard.channels.post(connection, { body: duplicateInput })
  );

  // 4. Attempt to create a channel with missing name
  const missingNameInput = { ...channelInput };
  delete missingNameInput.name;
  await TestValidator.error("missing name should fail")(() =>
    api.functional.discussionboard.channels.post(connection, { body: missingNameInput as any })
  );

  // 5. Attempt to create a channel with missing description
  const missingDescInput = { ...channelInput };
  delete missingDescInput.description;
  await TestValidator.error("missing description should fail")(() =>
    api.functional.discussionboard.channels.post(connection, { body: missingDescInput as any })
  );

  // 6. (Cannot validate DB count - no API for channel listing)
}

