import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * E2E test for soft-deleting a discussion board channel as an admin.
 *
 * - Verifies that only admins can delete channels (setup via admin creation).
 * - Ensures the channel is marked as deleted (soft-delete), not hard-removed.
 * - Confirms the same channel cannot be deleted twice (tests idempotency/error).
 * - As user/member endpoints for detail/listing are not present, those role-based access checks are omitted.
 *
 * Process:
 * 1. Create a new admin (to gain deletion rights).
 * 2. Create a new channel as admin.
 * 3. Soft-delete the created channel by id (admin-only action).
 * 4. Validate response is a channel (not hard-removed) and run type checks.
 * 5. Attempt to soft-delete again, confirm error is thrown (already deleted).
 *
 * NOTE: Visibility in list/detail endpoints or to non-admin users is untestable due to missing SDK endpoints
 * and therefore omitted.
 */
export async function test_api_discussionboard_test_soft_delete_channel_as_admin(
  connection: api.IConnection,
) {
  // 1. Create an admin account for elevated privileges
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a new channel as admin
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 3. Soft-delete (mark as deleted) the channel using its id
  const deleted = await api.functional.discussionboard.channels.eraseById(connection, {
    id: channel.id,
  });
  typia.assert(deleted);

  // 4. Try deleting the same channel again – should result in an error or idempotent error
  await TestValidator.error("delete already-deleted channel")(
    () => api.functional.discussionboard.channels.eraseById(connection, { id: channel.id })
  );
}

