import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * 비관리자 권한(일반 멤버 등)으로 discussion board 채널 삭제(소프트 딜리트) 시도가
 * 정책상 거부되는지 검증하는 테스트
 *
 * 1. 관리자 권한으로 테스트용 채널을 하나 생성한다.
 * 2. 일반 멤버를 플랫폼에 신규 가입시킨다.
 * 3. 일반 멤버 권한(토큰)으로 채널 삭제(DELETE /discussionboard/channels/{id})를 시도한다.
 * 4. 권한 부족 등의 이유로 삭제가 실패(TestValidator.error)되는지 검증한다.
 * 5. (추가로, 채널의 실제 삭제/변동이 없음을 검증할 수 있는 API가 있다면, 채널이 그대로인 것도 검증)
 *
 * @note 계정 권한/역할 전환은 제공된 인증/권한 API에서 지원되는 경우 활용. 그렇지 않은 경우 적절히 주석 처리.
 */
export async function test_api_discussionboard_test_delete_channel_without_admin_permission(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 테스트용 채널 생성
  const adminChannel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(adminChannel);

  // 2. 일반 멤버를 신규 가입
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 3. (권한 전환 가능 시) 일반 멤버 계정 토큰 등으로 connection을 설정해야 실제 권한 처리됨
  // 단, 제공된 API에서 멤버 토큰 전환/인증이 불가할 경우 이 부분 생략
  // 아래는 "멤버" 권한으로 삭제 요청이 들어간다는 전제를 명확히 한다.

  // 4. 권한 없는 멤버가 해당 채널 삭제 시도 → 반드시 거부되어야 함
  await TestValidator.error("멤버 계정의 권한 없는 채널 삭제 시도는 반드시 실패")(
    async () => {
      await api.functional.discussionboard.channels.eraseById(connection, {
        id: adminChannel.id,
      });
    },
  );

  // 5. (선택) 채널 상세 조회 등의 API가 있다면, 여전히 채널이 존재함을 Assert로 검증
}

