import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";

/**
 * Validates idempotent behavior when deleting a channel that is already soft-deleted as an admin.
 *
 * Business context:
 * - Channels (forums) can be soft-deleted by admins, which makes them inaccessible to end-users/members but preserves them for audit/logging.
 * - Attempting to soft-delete an already deleted channel should not throw a system error, nor re-apply any side effects, but may log an event or return a notification.
 * - The channel must remain inaccessible to regular members after repeated deletions.
 *
 * Test Scenario Steps:
 * 1. Register a new admin (required for creating and deleting channels).
 * 2. Authenticate as the new admin (assume implicit via admin creation: no explicit login API available).
 * 3. Create a new discussion board channel as the admin.
 * 4. Soft-delete (erase) the channel as the admin.
 * 5. Attempt to soft-delete (erase) the same channel again as the admin:
 *    - Ensure no error is thrown (idempotency).
 *    - Confirm the returned entity/data is valid and unchanged in deleted status.
 *    - Optionally, assert that no duplicate side effects occur (cannot check audit log via API, so focus on functional API and data contract).
 * 6. (LIMITED) Since there is no member/member-access API or visibility assertion, we cannot directly verify member access is blocked. Rely on correct soft delete contract in returned object.
 */
export async function test_api_discussionboard_test_soft_delete_already_deleted_channel(
  connection: api.IConnection,
) {
  // 1. Create a new admin (required for all channel actions)
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a new channel as that admin
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 3. Soft-delete the channel (first deletion)
  const deleted = await api.functional.discussionboard.channels.eraseById(connection, {
    id: channel.id,
  });
  typia.assert(deleted);

  // 4. Attempt soft-delete again on the already-deleted channel (idempotency and error suppression)
  let repeatedDeletion: IDiscussionboardChannel | null = null;
  try {
    repeatedDeletion = await api.functional.discussionboard.channels.eraseById(connection, { id: channel.id });
    typia.assert(repeatedDeletion);
  } catch (err) {
    throw new Error("Repeated soft-delete should NOT throw a system error, but did: " + (err instanceof Error ? err.message : String(err)));
  }

  // 5. Confirm repeated deletion output is valid and matches 'deleted' state (actual structure unknown; idempotency focus)
  // Since returned DTO shape is opaque, we only verify its type and presence.
  TestValidator.predicate("Repeated deletion returns entity object")(typeof repeatedDeletion === "object" && !!repeatedDeletion);
}

