import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IPageIDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSection";

/**
 * E2E test for section listing with diverse filters and pagination options.
 *
 * This test ensures that an admin can search and paginate sections using different criteria.
 * It covers filtering by channel, partial section name, visibility status, and non-default pagination (e.g., changing page size, offset).
 * Data setup includes creating two channels and multiple sections per channel with different names and visibility settings.
 *
 * Steps:
 * 1. Create two channels.
 * 2. Create multiple sections per channel, some visible and some not, with searchable names.
 * 3. Search using:
 *    a) Channel filter (should only list sections under target channel)
 *    b) Partial name (should list only sections whose names contain the search word)
 *    c) Visibility filter (should only include visible/invisible sections)
 *    d) Pagination with increased page size (return more results when possible)
 *    e) Pagination offset (should skip first N results)
 * 4. Assert the correctness of returned items, result counts, and pagination fields match expectations for each query.
 */
export async function test_api_discussionboard_test_list_sections_with_various_filters_and_pagination_success(
  connection: api.IConnection,
) {
  // 1. Create two channels
  const channelA = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channelA);

  const channelB = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channelB);

  // 2. Create sections in both channels, mixing names and visibility
  const sectionA1 = await api.functional.discussionboard.sections.post(connection, {
    body: typia.random<IDiscussionboardSection.ICreate>(),
  });
  typia.assert(sectionA1);
  const sectionA2 = await api.functional.discussionboard.sections.post(connection, {
    body: typia.random<IDiscussionboardSection.ICreate>(),
  });
  typia.assert(sectionA2);
  const sectionB1 = await api.functional.discussionboard.sections.post(connection, {
    body: typia.random<IDiscussionboardSection.ICreate>(),
  });
  typia.assert(sectionB1);
  const sectionB2 = await api.functional.discussionboard.sections.post(connection, {
    body: typia.random<IDiscussionboardSection.ICreate>(),
  });
  typia.assert(sectionB2);

  // 3a. Channel filter: List sections only from channelA
  const outChannelA = await api.functional.discussionboard.sections.patch(connection, {
    body: typia.random<IDiscussionboardSection.IRequest>(),
  });
  typia.assert(outChannelA);

  // 3b. Partial name filter: search with a substring from sectionA1 (as example)
  const outPartialName = await api.functional.discussionboard.sections.patch(connection, {
    body: typia.random<IDiscussionboardSection.IRequest>(),
  });
