import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentLike";

/**
 * 댓글 좋아요 생성/중복/권한/에러 케이스 시나리오를 종합 검증합니다.
 *
 * - 멤버 A가 댓글에 처음 좋아요 → 정상 생성
 * - 멤버 A가 같은 댓글에 중복 좋아요 시도 → 중복 에러
 * - 멤버 B가 동일 댓글 좋아요 → 정상
 * - 존재하지 않는 댓글로 좋아요 → 404/유효성 에러
 * - 미인증 사용자 좋아요 시도 → 인증 오류
 *
 * 각 단계가 정상 동작/실패하는지, 실제 관계형 데이터를 주입해 API 비즈니스 로직을 점검합니다.
 */
export async function test_api_discussionboard_test_create_comment_like_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. 멤버 A 생성
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  // 2. 멤버 A가 댓글 등록
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. 멤버 A가 해당 댓글 좋아요 (정상)
  const likeA = await api.functional.discussionboard.commentLikes.post(connection, {
    body: {
      member_id: memberA.id,
      comment_id: comment.id,
    } satisfies IDiscussionboardCommentLike.ICreate,
  });
  typia.assert(likeA);

  // 4. 멤버 A가 동일 댓글에 중복 좋아요 (중복 에러)
  await TestValidator.error("같은 멤버-댓글 조합 중복 좋아요 불가")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(connection, {
        body: {
          member_id: memberA.id,
          comment_id: comment.id,
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );

  // 5. 멤버 B 생성
  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  // 6. 멤버 B가 같은 댓글 좋아요 (정상)
  const likeB = await api.functional.discussionboard.commentLikes.post(connection, {
    body: {
      member_id: memberB.id,
      comment_id: comment.id,
    } satisfies IDiscussionboardCommentLike.ICreate,
  });
  typia.assert(likeB);

  // 7. 존재하지 않는 댓글 id로 좋아요 → 에러
  await TestValidator.error("존재하지 않는 댓글 ID 좋아요 요청 오류")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(connection, {
        body: {
          member_id: memberA.id,
          comment_id: typia.random<string>(),
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );

  // 8. 미인증 사용자의 좋아요 요청(인증 에러)
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error("인증 없는 좋아요 요청 오류")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(unauthConn, {
        body: {
          member_id: memberA.id,
          comment_id: comment.id,
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );
}

