import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";
import type { IPageIDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSettings";

/**
 * Validate the retrieval and filtering of discussion board settings entries by an admin.
 *
 * This test function ensures that an admin user can:
 * - Retrieve a paginated list of settings for the discussion board
 * - Apply various filters, including by section, owner, setting key, created/updated dates
 * - Receive paginated results containing only relevant settings
 * - See correct pagination/metadata and sorting in the response
 *
 * It also validates failure scenarios:
 * - Sending invalid filter values or malformed pagination parameters triggers validation errors
 * - Non-admin users are forbidden from accessing this endpoint, confirming RBAC enforcement
 *
 * Test process:
 * 1. As an admin, list all discussion board settings (with no filters)
 * 2. As an admin, apply several filters (section, owner, setting key, creation/update date)
 * 3. As an admin, try paging through multiple results
 * 4. As an admin, provide invalid filter/pagination values and expect validation error
 * 5. As a non-admin, attempt to retrieve settings and assert permission error
 */
export async function test_api_discussionboard_test_list_and_search_settings_with_pagination_and_filters_as_admin(
  connection: api.IConnection,
) {
  // 1. As admin, retrieve all settings without any filters
  const allSettings = await api.functional.discussionboard.settings.patch(connection, {
    body: {}, // empty filters
  });
  typia.assert(allSettings);

  // 2. As admin, retrieve with various filters (examples shown)
  const byOwner = await api.functional.discussionboard.settings.patch(connection, {
    body: { owner: "admin_user_id" },
  });
  typia.assert(byOwner);

  const bySection = await api.functional.discussionboard.settings.patch(connection, {
    body: { section: "support" },
  });
  typia.assert(bySection);

  const byKey = await api.functional.discussionboard.settings.patch(connection, {
    body: { key: "moderation" },
