import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSettings";

/**
 * Validate updating an existing settings entry as admin.
 *
 * This test covers standard and edge scenarios for updating discussionboard settings:
 * - Admin can update owner_type, setting_value, description, and section_id fields
 * - Immutable fields like setting_key and id cannot be changed
 * - System returns updated objects reflecting true DB state
 * - Error is raised if trying to update to existing (setting_key, owner_type, owner_id) triple
 * - Omitting updatable fields leaves them unchanged
 *
 * Step-by-step:
 * 1. Create a settings entry and capture its response as the baseline.
 * 2. Successfully update owner_type, setting_value, description, and section_id, confirm the change and immutables.
 * 3. Try a conflicting (setting_key, owner_type, owner_id) triple, expect an error.
 * 4. Submit an update omitting all updatable fields; expect no change to values.
 * 5. Attempt to change immutable "setting_key" or "id"; expect values to remain as originally set.
 */
export async function test_api_discussionboard_test_update_existing_setting_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a settings entry for update
  const original = await api.functional.discussionboard.settings.post(connection, {
    body: typia.random<IDiscussionboardSettings.ICreate>(),
  });
  typia.assert(original);

  // 2. Update some updatable fields of the setting
  const updateBody = typia.random<IDiscussionboardSettings.IUpdate>();
  const updated = await api.functional.discussionboard.settings.putById(connection, {
    id: original.id,
    body: updateBody,
  });
  typia.assert(updated);
  // Confirm fields updated vs original
  TestValidator.notEquals("updated timestamp")(updated.updated_at)(original.updated_at);
  TestValidator.equals("immutable setting_key")(updated.setting_key)(original.setting_key);
  TestValidator.equals("immutable id")(updated.id)(original.id);

  // 3. Edge: try a conflicting key/owner/owner_id update, expect error
  const duplicate = await api.functional.discussionboard.settings.post(connection, {
    body: typia.random<IDiscussionboardSettings.ICreate>(),
  });
  typia.assert(duplicate);
  await TestValidator.error("conflicting key/owner update")(() =>
    api.functional.discussionboard.settings.putById(connection, {
      id: original.id,
      body: { owner_type: duplicate.owner_type, owner_id: duplicate.owner_id } as IDiscussionboardSettings.IUpdate,
    })
  );

  // 4. Edge: omit updatable fields (should not change any fields)
  const partialUpdate = {} as IDiscussionboardSettings.IUpdate;
  const partialResult = await api.functional.discussionboard.settings.putById(connection, {
    id: original.id,
    body: partialUpdate,
  });
  typia.assert(partialResult);
  TestValidator.equals("unchanged key")(partialResult.setting_key)(original.setting_key);
  TestValidator.equals("unchanged id")(partialResult.id)(original.id);

  // 5. Edge: attempt to change immutable fields, expect no change
  const badUpdate = { setting_key: "attempted-change", id: "fake-id" } as any as IDiscussionboardSettings.IUpdate;
  const badResult = await api.functional.discussionboard.settings.putById(connection, {
    id: original.id,
    body: badUpdate,
  });
  typia.assert(badResult);
  TestValidator.equals("immutable setting_key")(badResult.setting_key)(original.setting_key);
  TestValidator.equals("immutable id")(badResult.id)(original.id);
}

