 * - 필터/페이징 파라미터에 허용되지 않는 값, 타입 오류 등 검증 실패 케이스에서는 에러 응답에 비즈니스 룰에 맞는 상세 오류가 포함됐는지 검사합니다.
 *
 * 주요 테스트 절차:
 * 1. 신규 멤버 생성
 * 2. 알림 환경 설정 N개(타입/채널별 다양한 값) 등록
 * 3. 페이징/필터 각각 또는 조합별로 목록 검색 요청 → 응답 결과(건수/내역/페이지네이션) 검증
 * 4. 결과가 없는 필터/범위 외 페이지 등 엣지 케이스 응답 확인
 * 5. 잘못된 타입, 값 등 validation error 발생 구간도 확인 (에러 response structure 체크)
 */
export async function test_api_discussionboard_test_list_notification_preferences_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. 신규 멤버 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
