  // 2. 다양한 알림 환경 설정 등록 (타입, 채널별로)
  const preferences: INotificationPreference[] = [];
  for (let i = 0; i < 5; ++i) {
    const pref = await api.functional.discussionboard.notificationPreferences.post(connection, {
      body: typia.random<INotificationPreference.ICreate>(),
    });
    preferences.push(pref);
    typia.assert(pref);
  }

  // 3. 알림 환경설정 전체 목록 조회 (페이지 1)
  let res = await api.functional.discussionboard.notificationPreferences.patch(connection, {
    body: typia.random<INotificationPreference.IRequest>(),
  });
  typia.assert(res);

  // 4. (엣지) 존재하지 않는 페이지(예: 아주 큰 값) 요청 시 빈 결과/에러 처리 확인
  let errorCaught = false;
  try {
    await api.functional.discussionboard.notificationPreferences.patch(connection, {
      body: { ...typia.random<INotificationPreference.IRequest>(), page: 9999 },
    });
  } catch {
    errorCaught = true;
  }
  TestValidator.predicate("존재하지 않는 페이지 번호 요청시 에러가 발생해야 함")(errorCaught);

  // 5. (엣지) 허용되지 않는 필터 값 사용 시 validation error (예: 존재하지 않는 type/channel 등)
  errorCaught = false;
  try {
    await api.functional.discussionboard.notificationPreferences.patch(connection, {
      body: { ...typia.random<INotificationPreference.IRequest>(), type: "not_exist_type" },
    });
  } catch {
    errorCaught = true;
  }
  TestValidator.predicate("존재하지 않는 알림 type 값 사용시 validation 에러 발생")(errorCaught);
}

