    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);
  const pref2 = await api.functional.discussionboard.notificationPreferences.post(connection, {
    body: typia.random<INotificationPreference.ICreate>(),
  });
  typia.assert(pref2);

  // 6. Attempt to access other user's preference (permission denial)
  await TestValidator.error("fetch another user's notification preference should fail")(() =>
    api.functional.discussionboard.notificationPreferences.getById(connection, {
      id: pref2.id,
    })
  );

  // 7. Call with an invalid format id (not a uuid)
  await TestValidator.error("invalid uuid format should fail")(() =>
    api.functional.discussionboard.notificationPreferences.getById(connection, {
      id: "not-a-uuid" as any,
