/**
 * E2E test for creating a new report history event for moderation workflow.
 *
 * This test covers:
 * 1. Success path: Creation with valid payload, referencing an existing report and including all required metadata.
 * 2. Failure scenarios:
 *    - Missing required fields (should fail validation).
 *    - Invalid report reference (should fail with 400/bad request).
 *    - Invalid event type (should fail with 400/bad request).
 *    - Unauthorized user (must fail with 403 if attempted by non-moderator/admin).
 *
 * Test Steps:
 * 1. Create a valid report to have a legitimate report reference.
 * 2. As a moderator/admin, create a report history event using the report reference and all required metadata; verify response.
 * 3. Attempt to create with missing required fields (expect failure).
 * 4. Attempt to create with an invalid report reference (expect failure).
 * 5. Attempt to create with an invalid event type (expect failure).
 * 6. As a normal user, attempt to create a report history (expect 403 forbidden).
 */
export async function test_api_discussionboard_test_create_report_history_with_valid_and_invalid_data(connection: api.IConnection) {
  // 1. Create a valid report to produce a legitimate report reference.
  const validReport = await api.functional.discussionboard.reports.post(connection, {
    body: typia.random<IDiscussionboardReport.ICreate>()
  });
  typia.assert(validReport);

  // 2. Success: As moderator/admin, create a report history event
  const validReportHistory = await api.functional.discussionboard.reportHistories.post(connection, {
    body: {
      ...typia.random<IDiscussionboardReportHistory.ICreate>(),
      reportId: validReport.id // reference to legitimate report
    }
  });
  typia.assert(validReportHistory);
  // Additional TestValidator field checks can be added here if structure is defined

  // 3. Failure: Missing required fields
  await TestValidator.error("missing required fields")(() =>
    api.functional.discussionboard.reportHistories.post(connection, {
      body: {} as IDiscussionboardReportHistory.ICreate
    })
  );

  // 4. Failure: Invalid report reference
  await TestValidator.error("invalid report reference")(() =>
    api.functional.discussionboard.reportHistories.post(connection, {
      body: {
        ...typia.random<IDiscussionboardReportHistory.ICreate>(),
        reportId: "non-existent-report-id"
      }
    })
  );

  // 5. Failure: Invalid event type
  await TestValidator.error("invalid event type")(() =>
    api.functional.discussionboard.reportHistories.post(connection, {
      body: {
        ...typia.random<IDiscussionboardReportHistory.ICreate>(),
        eventType: "invalid_event_type"
      }
    })
  );

  // 6. As a normal user, create a report history event (expect forbidden)
  // You would need to switch to a normal user context here;
  // For illustration, assuming connection is now a normal user:
  await TestValidator.error("forbidden for regular users")(() =>
    api.functional.discussionboard.reportHistories.post(connection, {
      body: {
        ...typia.random<IDiscussionboardReportHistory.ICreate>(),
        reportId: validReport.id
      }
    })
  );
}

