import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * Test the creation of a report against a discussionboard post, covering both success (creation/log) and negative (invalid target) validation.
 *
 * BUSINESS CONTEXT:
 * Filing a report is a critical part of platform moderation and compliance. This test verifies a member can flag a post for review, that the report is created and linked properly, and that compliance/audit trail is enforced. It also checks input validation in the moderation API.
 *
 * TEST STEPS:
 * 1. Register a new member (the reporter) via /discussionboard/members.
 * 2. Create a new post (the report target) via /discussionboard/posts.
 * 3. File a report on the post using /discussionboard/reports, specifying a reason and anonymity as needed.
 * 4. Validate that the report response links to the right member, post, has correct fields, and that audit trace/log exists.
 * 5. Attempt to file a report with an invalid (nonexistent) post ID, expecting a validation error.
 * 6. Document (but skip) suspension/ban scenario due to API limitations.
 */
export async function test_api_discussionboard_test_create_report_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new reporter member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a new post (report target)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. File a report for the created post
  const reasonExample = "spam";
  const reportInput: IDiscussionboardReport.ICreate = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    targetPostId: post.id,
    reporterId: member.id,
    reasonCategory: reasonExample,
    anonymous: false,
  };
  const report = await api.functional.discussionboard.reports.post(connection, {
    body: reportInput,
  });
  typia.assert(report);
  TestValidator.equals("link reporter")(report.reporterId)(member.id);
  TestValidator.equals("link target post")(report.targetPostId)(post.id);
  TestValidator.equals("reason category")(report.reasonCategory)(reasonExample);
  TestValidator.predicate("audit log/trace present")(!!report.auditLogId || !!report.auditTrace);

  // 4. Negative validation: Try to report a nonexistent post (should error)
  await TestValidator.error("invalid post ID should fail")(async () => {
    await api.functional.discussionboard.reports.post(connection, {
      body: {
        ...reportInput,
        targetPostId: "00000000-0000-0000-0000-000000000000", // invalid UUID, should fail
      },
    });
  });

  // 5. (Not implemented: suspended/banned scenario due to API limitations)
}

