 *
 * This test verifies the following business rules:
 * 1. Regular members should not be able to retrieve all member profiles—they may only see their own, or access is denied for global/system-wide search.
 * 2. Admin or moderator roles are able to list/search all member profiles successfully.
 *
 * Step-by-step process:
 * 1. Register a regular member account (simulate sign-up).
 * 2. Register another account as admin or moderator (simulate elevated role sign-up).
 * 3. As the regular user, attempt to list/search member profiles:
 *    - The response should contain only the user's own profile or access should be denied/restricted.
 *    - Confirm that no other profiles are visible.
 *    - If API returns an error (forbidden or unauthorized), this is considered valid enforcement of policy as well.
 * 4. As the admin/moderator, attempt to list/search all member profiles:
 *    - The response should contain multiple member profiles (including other users).
 *    - Assert that access is granted and more than one profile is visible.
 * 5. Validate strict enforcement by alternating roles and repeating the searches, confirming enforcement each time.
 */
export async function test_api_discussionboard_memberProfiles_test_list_member_profiles_requires_proper_role_for_admin_search(
  connection: api.IConnection,
) {
  // 1. Register a regular member account
  const regularMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(regularMember);

  // 2. Register an admin/moderator member account
  const adminMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(), // Assume admin/moderator role is set up via DTO or by external admin process if available
  });
  typia.assert(adminMember);

  // 3. As REGULAR USER: Attempt to list/search member profiles
  // NOTE: No explicit login API; test assumes session/connection context is swapped as needed
  let regularOutput;
  try {
    regularOutput = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: typia.random<IDiscussionboardMemberProfile.IRequest>(),
    });
    typia.assert(regularOutput);
    // Should only see own profile or result size 1
    TestValidator.predicate("Regular member cannot see other profiles")(
      Array.isArray(regularOutput.data) && regularOutput.data.length === 1,
    );
    // Optionally, review exact user id if possible (pseudo-code; schemas are any)
    // TestValidator.equals("Own profile returned")(regularOutput.data[0].id)(regularMember.id);
  } catch (err) {
    // An error (forbidden/denied) for non-admin search is a valid enforcement of access control
    TestValidator.predicate("Regular member search forbidden or denied")(!!err);
  }

  // 4. As ADMIN/MODERATOR: Attempt to list/search member profiles
  // NOTE: No explicit admin login API; test assumes connection/session switched
  let adminOutput;
  try {
    adminOutput = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: typia.random<IDiscussionboardMemberProfile.IRequest>(),
