/**
 * Test that a member can update their own profile (display name, bio, avatar, locale, timezone),
 * verifying that all profile fields are updated correctly, validated according to schema,
 * and changes are immediately visible.
 *
 * Business Context:
 * A member should be able to update their personal profile information—such as display name, bio,
 * avatar, locale, and timezone—at any time. This scenario validates that the update endpoint
 * persists all changes, upholds validation rules, and that results are directly visible via
 * subsequent queries. Profile creation and update must both tie back to a valid registered member.
 * All changes should be audit-logged (handled server-side).
 *
 * Steps:
 * 1. Register a new member using the appropriate API endpoint.
 * 2. Create an initial profile for this user, binding to the registered member's ID.
 * 3. Prepare a new set of profile values for update (covering all editable fields).
 * 4. Update the member profile with these new values and verify the response.
 * 5. For each changed field, confirm that the update appears immediately in the returned data.
 *    (Direct fetch by profile ID is not available in the API; verification relies on update response shape.)
 * 6. Validate all operations via schema/runtime assertions and field-level value checks.
 */
export async function test_api_discussionboard_test_update_own_member_profile_success(
  connection: api.IConnection,
) {
  // 1. Register a new member for the update scenario
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create an initial member profile for this user
  // (Assumes IDiscussionboardMemberProfile.ICreate contains member FK and all optional profile fields)
  const profile = await api.functional.discussionboard.memberProfiles.post(connection, {
    body: typia.random<IDiscussionboardMemberProfile.ICreate>(),
  });
  typia.assert(profile);

  // 3. Prepare profile update data: update all possible fields with new random/test values
  const updateBody = typia.random<IDiscussionboardMemberProfile.IUpdate>();

  // 4. Call the profile update API by ID
  const updated = await api.functional.discussionboard.memberProfiles.putById(connection, {
    id: profile.id,
    body: updateBody,
  });
  typia.assert(updated);

  // 5. For each updated field, immediately verify the value has changed as expected
  // (Since no API to re-fetch profile by ID, use update response for verification)
  for (const key in updateBody) {
    // Only check explicitly set fields
    if (updateBody[key] !== undefined)
      TestValidator.equals(`profile field: ${key}`)(updated[key])(updateBody[key]);
  }
}

