import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Validate API error responses for retrieving discussion board comment reports by invalid or non-existent IDs.
 *
 * This test verifies that:
 * 1. Attempting to retrieve a comment report by a syntactically-valid but non-existent UUID triggers a 404 Not Found error.
 * 2. Attempting to retrieve a comment report using a syntactically invalid (non-UUID) ID triggers a validation (400 Bad Request) error.
 *
 * Test process:
 * 1. Register a new member to establish API authentication context.
 * 2. Attempt to fetch a comment report using a random valid UUID that is guaranteed not to exist. Assert that a not-found error occurs.
 * 3. Attempt to fetch a comment report using an invalid string as the ID and assert a validation error occurs.
 *
 * This test ensures the API enforces both resource existence constraints and input validation rigorously.
 * No test data is written or modified.
 */
export async function test_api_discussionboard_test_get_comment_report_by_invalid_id_returns_not_found_error(
  connection: api.IConnection,
) {
  // 1. Register a new member for API context
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Attempt to get a comment report with a valid (but non-existent) UUID
  const nonExistentUuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should return not found for non-existent UUID")(() =>
    api.functional.discussionboard.commentReports.getById(connection, { id: nonExistentUuid })
  );

  // 3. Attempt to get a comment report with an invalid (non-UUID) ID
  await TestValidator.error("should return validation error for invalid ID")(() =>
    api.functional.discussionboard.commentReports.getById(connection, { id: "not-a-uuid" as any })
  );
}

