import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * 댓글 중복 신고 제한 테스트: 동일 멤버가 동일 댓글에 대해 제한시간 내 중복 신고할 경우 거절되는지 검증합니다.
 *
 * 본 테스트는 다음의 시나리오를 검증합니다.
 * 1. 신고를 수행할 discussionboard_members 멤버를 생성
 * 2. 신고 대상이 될 discussionboard_comments 엔터티(댓글) 생성
 * 3. 해당 댓글에 대해 첫 번째 신고(합법적 시도)를 접수
 * 4. 동일 멤버/댓글/사유로, 제한시간 내 중복 신고를 재시도
 * 5. API가 중복건을 409 또는 검증 에러로 거절하여, 신규 중복 레코드가 생성되지 않음을 확인
 *
 * [테스트 순서]
 * 1. 신고 회원 생성
 * 2. 신고 대상 댓글 생성
 * 3. 첫 번째 댓글 신고
 * 4. 곧바로 두 번째(중복) 댓글 신고 시도
 * 5. 중복은 거절되어야 하며, 실제 에러(409 등)가 발생함을 검증
 */
export async function test_api_discussionboard_test_create_comment_report_duplicate_recent_report_rejected(
  connection: api.IConnection,
) {
  // 1. 신고 회원 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 신고 대상 댓글 생성
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. 첫 번째 댓글 신고 - 정상적으로 성공해야 함
  const reportReason = "spam";
  const firstReportReq = {
    comment_id: comment.id,
    member_id: member.id,
    reason: reportReason,
    details: "이 댓글은 스팸입니다.",
  } satisfies IDiscussionboardCommentReport.ICreate;
  const firstReport = await api.functional.discussionboard.commentReports.post(connection, {
    body: firstReportReq,
  });
  typia.assert(firstReport);

  // 4. 동일 조건 중복 신고 시도 (제한시간 내)
  const duplicateReportReq = {
    comment_id: comment.id,
    member_id: member.id,
    reason: reportReason,
    details: "동일 사유로 중복 신고 재시도",
  } satisfies IDiscussionboardCommentReport.ICreate;
  await TestValidator.error("동일 멤버/댓글/사유의 중복 신고는 거절되어야 함")(
    async () => {
      await api.functional.discussionboard.commentReports.post(connection, {
        body: duplicateReportReq,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
