import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";

/**
 * Validate backend validation for comment report creation with missing/invalid fields.
 *
 * This test ensures that the comment report endpoint enforces required field and format validation.
 * It attempts to create comment reports with missing or malformed required properties, including
 * invalid UUID formats for critical foreign key fields. It confirms that each improper input is
 * rejected with a validation error at runtime (HTTP 400), and that business rules are
 * consistently enforced at the API layer. Does not attempt to test TS-level compilation errors.
 *
 * Steps:
 * 1. Prepare a member (dependency: /discussionboard/members).
 * 2. Build a valid base comment report DTO for mutation.
 * 3. Attempt to submit reports with each of the following invalid cases:
 *    - Bad UUID in "commentId"
 *    - Bad UUID in "memberId"
 *    - Bad UUID in "reasonCode"
 *    (Missing/undefined or omitted fields are not included since the SDK/typia/TS will prevent such calls.)
 * 4. For each case, assert that a validation/business rule error occurs.
 */
export async function test_api_discussionboard_test_create_comment_report_validation_error_missing_or_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Prepare a reporting member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Build a valid base comment report request
  const validReport = typia.random<IDiscussionboardCommentReport.ICreate>();

  // 3. Define a helper to mutate one property at a time
  const makeInvalid = (
    field: keyof IDiscussionboardCommentReport.ICreate,
    badValue: any,
  ): IDiscussionboardCommentReport.ICreate => ({
    ...validReport,
    [field]: badValue,
  });

  // 4. Try each invalid/malformed case

  // Invalid commentId format (not a UUID)
  TestValidator.error("invalid commentId format should fail")(() =>
    api.functional.discussionboard.commentReports.post(connection, {
      body: makeInvalid("commentId", "not-a-uuid"),
    }),
  );

  // Invalid memberId format (not a UUID)
  TestValidator.error("invalid memberId format should fail")(() =>
    api.functional.discussionboard.commentReports.post(connection, {
      body: makeInvalid("memberId", "not-a-uuid"),
    }),
  );

  // Invalid reasonCode format (not a UUID)
  TestValidator.error("invalid reasonCode format should fail")(() =>
    api.functional.discussionboard.commentReports.post(connection, {
      body: makeInvalid("reasonCode", "bad-uuid-format"),
    }),
  );
}

