    async () => {
      await api.functional.discussionboard.warnings.post(connection, {
        body: invalidActionBody,
      });
    },
  );

  // 7. Permission denied for unauthorized caller
  const anonymousConnection = { ...connection, headers: {} };
  await TestValidator.error("permission denied when unauthenticated")(
    async () => {
      await api.functional.discussionboard.warnings.post(anonymousConnection, {
        body: baseWarningBody,
      });
    },
  );
}

