/**
 * Test the metadata update of a discussion board post attachment by its ID.
 *
 * This test covers the following scenarios:
 *
 * 1. Setup: Register two members (owner and non-owner), create a post for the owner, and associate an attachment to that post.
 * 2. As the owner, update attachment metadata (file_name, file_uri, mime_type) and verify that changes are reflected.
 * 3. As the non-owner, attempt an update and expect a permission error.
 * 4. Attempt to update using an invalid MIME type to trigger a validation error.
 * 5. Attempt to update with a completely invalid attachment ID to trigger not found/validation error.
 *
 * Limitations:
 * - DTO and API do not expose authentication/session management, admin/moderator role simulation, or soft-delete/deleted fields. Tests for those paths are noted but not implemented.
 * - Update with non-existent fields or update-after-delete are not possible with current DTOs.
 *
 * Business context:
 * - Ensures only the owner can update their attachment's metadata unless overridden by administrative context.
 * - Enforces correct input validation for allowed fields.
 * - Protects record integrity by refusing unauthorized and invalid-format requests.
 *
 * Each step is annotated for clarity and future extension where new endpoints/types become available.
 */
export async function test_api_discussionboard_postAttachments_test_update_post_attachment_metadata_fields_and_permission_rules(
  connection: api.IConnection,
) {
  // 1. Register member1 (owner) and member2 (non-owner)
  const owner = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(owner);

  const nonOwner = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(nonOwner);

  // 2. Owner creates a post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. Owner associates an attachment to the post
  const attachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(attachment);

  // 4. As owner, update file_name, file_uri, mime_type
  const updatedFileName = `updated_${Date.now()}`;
  const updatedFileUri = `https://files.example.com/${Date.now()}/file.txt`;
  const updatedMimeType = "text/plain";
  const updateInput = {
    file_name: updatedFileName,
