/**
 * Tests successful deletion of a thread snapshot as an authorized admin or staff.
 *
 * This end-to-end test validates that deleting a thread snapshot by its valid ID works as intended when performed by an authorized admin or staff user. The test covers the full setup sequence (board, member, thread, snapshot creation), executes the deletion, and then verifies that the response reflects the deletion according to platform policy (soft delete or removal).
 *
 * Process:
 * 1. Create a new board (admin context assumed).
 * 2. Create a member (thread owner).
 * 3. Create a thread for that member in the board.
 * 4. Create a snapshot for the thread to represent a version history point.
 * 5. Delete the snapshot by its ID as an admin/staff.
 * 6. Validate that the deleted snapshot's ID matches and that all invariants are respected (including checking for soft-delete status if such a field exists in the snapshot entity).
 *
 * Note: If DTO/entity has a soft-delete property (e.g., deleted_at), test may optionally assert that as well.
 */
export async function test_api_discussionboard_test_delete_thread_snapshot_success(
  connection: api.IConnection,
) {
  // 1. Create a new board (admin privilege context)
  const board = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board);

  // 2. Create a member (thread owner)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 3. Create a thread on that board by the created member
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 4. Create a snapshot for that thread, representing a version
  const snapshot = await api.functional.discussionboard.threadSnapshots.post(connection, {
    body: typia.random<IDiscussionboardThreadSnapshot.ICreate>(),
  });
  typia.assert(snapshot);

  // 5. Delete the thread snapshot as an admin/staff
  const deleted = await api.functional.discussionboard.threadSnapshots.eraseById(connection, {
    id: snapshot.id,
  });
  typia.assert(deleted);

  // 6. Validate that the deleted snapshot output has the same id
  TestValidator.equals("deleted thread snapshot id matches")(deleted.id)(snapshot.id);
  // Optionally: Assert soft-delete marker if such a field exists (e.g., "deleted_at")
  // if ("deleted_at" in deleted)
  //   TestValidator.predicate("soft deleted")(!!deleted.deleted_at);
