import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IdiscussionboardBoards } from "@ORGANIZATION/PROJECT-api/lib/structures/IdiscussionboardBoards";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadSnapshot";

/**
 * Validate that thread snapshot deletions are restricted to privileged users (e.g., admins/audit staff).
 *
 * This test case ensures that an ordinary member (not admin or audit staff) cannot delete a thread snapshot they did not create and holds no special privileges for. It covers the scenario where a snapshot is owned by one member, and another unauthorized member attempts the deletion, which must fail due to insufficient permissions.
 *
 * Test steps:
 * 1. Register two separate discussion board members: `owner` and `attacker`.
 * 2. Create a discussion board with one of the members (as only admin can do this; assume owner is admin or process proceeds with required privilege for setup).
 * 3. As `owner`, create a thread in the board.
 * 4. As `owner`, create a snapshot for the thread, obtaining the snapshot's ID.
 * 5. As `attacker` (ordinary non-privileged member), attempt to delete the snapshot using its ID.
 * 6. Assert that the deletion attempt returns a permission denied error (forbidden/unauthorized), and the snapshot is not deleted.
 *
 * The test confirms business rule that only eligible roles may delete snapshots, protecting version/audit history from unauthorized modifications.
 */
export async function test_api_discussionboard_test_delete_thread_snapshot_without_permission(
  connection: api.IConnection,
) {
  // 1. Register the owner member
  const owner: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(owner);

  // 2. Register the attacker (another member, unauthorized)
  const attacker: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(attacker);

  // 3. Create a board (assume setup executes with proper privilege)
  const board: IdiscussionboardBoards = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(board);

  // 4. As owner, create a thread in the board
  const thread: IDiscussionboardThread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 5. As owner, create a snapshot for the thread
  const snapshot: IDiscussionboardThreadSnapshot = await api.functional.discussionboard.threadSnapshots.post(connection, {
    body: typia.random<IDiscussionboardThreadSnapshot.ICreate>(),
  });
  typia.assert(snapshot);

  // 6. As attacker, attempt to delete the snapshot (expect forbidden/unauthorized)
  await TestValidator.error("permission denied: non-privileged member cannot delete another's snapshot")(
    async () => {
      await api.functional.discussionboard.threadSnapshots.eraseById(connection, {
        id: snapshot.id,
      });
    },
  );
}
